-- conversations (next: node id, 0 = end the talk, -1 = fight, -2 = resolved peacefully, -3 = ambush, -4 = resolved, half XP)
-- shot: '' over your shoulder at the speaker, 'close[:N]' encounter member N's face, 'ots:N' over N's shoulder at you,
-- 'wide' both side-on; actor/emote: which member (1 = leader) plays which emote
DROP TABLE IF EXISTS `dnd_dialogue_node`;
CREATE TABLE `dnd_dialogue_node` (
  `id` INT UNSIGNED NOT NULL,
  `text` VARCHAR(1000) NOT NULL,
  `shot` VARCHAR(16) NOT NULL DEFAULT '',
  `actor` TINYINT UNSIGNED NOT NULL DEFAULT 1,
  `emote` INT UNSIGNED NOT NULL DEFAULT 0,
  `sets` VARCHAR(64) NOT NULL DEFAULT '',
  `patience` TINYINT NOT NULL DEFAULT 0,
  `leaves` VARCHAR(16) NOT NULL DEFAULT '',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DROP TABLE IF EXISTS `dnd_dialogue_option`;
CREATE TABLE `dnd_dialogue_option` (
  `node_id` INT UNSIGNED NOT NULL,
  `idx` TINYINT UNSIGNED NOT NULL,
  `text` VARCHAR(255) NOT NULL,
  `skill` VARCHAR(20) NOT NULL DEFAULT '',
  `dc` TINYINT NOT NULL DEFAULT 0,
  `next_ok` INT NOT NULL DEFAULT 0,
  `next_fail` INT NOT NULL DEFAULT 0,
  `req` VARCHAR(20) NOT NULL DEFAULT '',
  `need` VARCHAR(64) NOT NULL DEFAULT '',
  `adv` VARCHAR(32) NOT NULL DEFAULT '',
  `once` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`node_id`, `idx`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `dnd_dialogue_node` (`id`, `text`, `shot`, `actor`, `emote`, `sets`, `patience`, `leaves`) VALUES
(801, '{{"YOU! Robes, pointy hat, smug look - another wizard. Where are they? My frost-coil schematics vanished in the night, and the only people in this valley who could even READ them are me and... well. You."|"YOU! Sword, shield, hired-muscle swagger. Who sent you? My frost-coil schematics vanished in the night, and somebody paid somebody to fetch them. Somebody with a sword, I''ll wager. Where are they?"}}', '', 1, 25, '', 0, ''),
(802, 'Fizzik drums his fingers on his tool belt. "Well? I''m WAITING."', '', 1, 0, '', 0, ''),
(803, 'Fizzik takes a long, whistling breath through his nose. "Fine. FINE. I keep them in a locked case. This morning - open. No scratches, no forced latch. Whoever did it had a key, and I sleep with mine." He pats his belt. "There''s a spare, of course. It''s in my... it''s..." He pats his belt again, slower. "...It''s somewhere."', '', 1, 6, 'key', 1, ''),
(804, '"DON''T tell me to calm down! Telling a gnome to calm down is like telling a steam valve to relax - it only makes the whistling WORSE!" He jabs a finger at you. "Brakk! Hold this one down while I check their pockets!" / Brakk sighs, and hefts his hammer.', '', 1, 22, '', 0, ''),
(805, '"A frost-coil! It keeps a forge-room as cold as a glacier in midsummer - the smiths of Ironforge will pay a FORTUNE for it." He lowers his voice. "Drawn in my own frost-ink, too. It glows blue whenever it''s cold, so I can work all night without a lamp. Took me a month to brew."', '', 1, 5, 'ink', 0, ''),
(813, 'Fizzik freezes. "A regulating rune... no. No, it didn''t have one." He goes pale - then starts to giggle. "So whoever builds from them turns into an ice sculpture! Ha! Let the thief keep them!" He wipes his eyes. {{"You''ve a sharp mind, wizard. I take back the smug part. Mostly."|"You''ve a sharp mind for a sellsword. I take back the swagger part. Mostly."}}', '', 1, 11, '', 1, ''),
(814, '"A regulating WHAT? There''s no such thing!" Fizzik''s face goes from pink to purple. "You''re making it up - and only a thief would bluff that badly. Brakk - FLATTEN them!"', '', 1, 22, '', 0, ''),
(820, 'Fizzik''s ears go red. "It''s SUBTLE to people who aren''t SNOOPING."', '', 1, 22, '', -1, ''),
(806, '"Brakk - I pay him to stand there looking large - and my apprentice, Nim. Brakk can''t read a tavern sign, and Nim-" / "I can read a little, master!" squeaks the apprentice. "You''ve been teaching me!" / Fizzik doesn''t even look round. "Nim can barely read a pressure dial. Which leaves YOU."', '', 1, 25, 'askedwho', 0, ''),
(821, 'Fizzik waves a hand. "He can read the word ''gear''. Frost-script is another matter entirely - it took ME six years." / Nim stares very hard at his boots.', '', 1, 0, '', 0, ''),
(815, '"A trogg? In the caves?" Fizzik is already stuffing tools into his pack. "Those filthy, illiterate... of COURSE. Brakk - lanterns! We''re going trogg hunting!" / Behind his back, Nim sags with relief.', '', 1, 5, '', 0, ''),
(816, '"A trogg. Opened a LOCKED case. Without a scratch. And then read the labels to know which scrolls to take?" Fizzik''s eye twitches. "Do I LOOK like an idiot to you? Brakk - this one''s lying through their teeth!"', '', 1, 22, '', 0, ''),
(807, 'Brakk shrugs, which takes a while. "I don''t see things, {{wizard|friend}}. I stand near things." He thinks about it. "Heard scratching all night, though. The wee one, up by lamplight. Figured it was mice in boots." / Behind him, Nim drops a wrench.', '', 3, 0, 'scratching', 0, ''),
(818, '"Me?" Brakk looks genuinely hurt. "I can''t read me own name, {{wizard|friend}}. Want me to sign a confession? I''ll use the hammer." / "He can''t READ, you dolt," Fizzik snaps. "Do try to keep up."', '', 3, 15, '', -2, ''),
(808, 'You take in the camp. A cart of brass gears and copper coils. A cold firepit. Brakk, leaning on his warhammer, profoundly bored. Nim, hugging a leather satchel to his chest as if it might fly away. It''s cold enough to see your breath - and from under the satchel''s flap leaks a faint, steady blue light.', '', 1, 0, 'glow', 0, ''),
(811, '"W-writing? Nothing! Letters! To my mother!" Nim squeaks, clutching the satchel tighter - and bursts into tears. / Fizzik steps between you, trembling with rage. "First my schematics, now you''re bullying my APPRENTICE? Brakk!"', '', 2, 274, '', 0, ''),
(812, 'Fizzik opens his mouth to snap at you - and stops. Slowly, very slowly, he turns to look at his apprentice. / "...Nim. You HAVE been studying frost-script. Haven''t you." / Nim makes a noise like a kettle.', '', 1, 6, '', 0, ''),
(810, 'Every eye turns to Nim. The blue glow from his satchel is impossible to miss now. His lip trembles. / "I - I only wanted to COPY them, master! To learn! You never let me near the good stuff - it''s always ''sweep the shop, Nim'', ''oil the gears, Nim''..." He pulls out a roll of softly glowing schematics - and the spare key with it.', '', 2, 24, '', 0, ''),
(822, 'Fizzik opens his mouth to shout... then looks at the copy in Nim''s shaking hands. The lines are neat. Careful. Almost as good as his own. / "...The best, eh?" He clears his throat. "Fine. FINE. From tomorrow you''re on frost-coils, Nim. Under SUPERVISION." / Nim beams. Brakk, unexpectedly, claps.', '', 1, 21, '', 0, ''),
(823, '"Go EASY? He picked my LOCK - and you''re taking his side?" Fizzik looks from Nim to you, and his eyes narrow. "Hold on. A {{wizard|sellsword}} turns up the very morning my schematics vanish, and defends the thief... You were in on it! Brakk - get them both!" / Nim dives behind the cart.', '', 1, 22, '', 0, ''),
(824, 'Fizzik snatches the schematics and the key. "Brakk - take his tools." / Brakk does, gently. Nim doesn''t say a word. Fizzik turns back to you, suddenly deflated. "...Thank you. I suppose. Go on."', '', 1, 274, '', 0, ''),
(825, 'Fizzik takes the copy and holds it up. Where Nim ran out of frost-ink he improvised - lamp-black and ground mica, by the look of it. It shouldn''t work. It glows anyway. / Fizzik is quiet for a long moment. "...That''s clever, Nim. That''s actually clever." / Nim looks like he might faint.', '', 1, 21, '', 0, ''),
(819, '"Your own designs, eh?" Fizzik squints at your sleeves. "Gnomeregan school, by those burn marks. Hmph. A proper tinker doesn''t steal - we merely improve upon." He sniffs. "Only Gnomeregan-trained hands can read frost-script anyway. Me. You. And..." He trails off, frowning at nothing in particular.', '', 1, 21, '', 1, ''),
(826, 'You smile, and somehow it works. Fizzik deflates like a punctured bellows. "...Together. Yes. Fine. I''m - sorry I shouted. It''s been a long night."', '', 1, 0, '', 2, ''),
(817, '"I have FOURTEEN pockets," Fizzik says through his teeth. "I have checked every one. Twice. Brakk checked the one I can''t reach." / "Wasn''t pleasant," Brakk adds.', '', 1, 22, '', -1, ''),
(831, 'Fizzik throws up his hands. "No. NO. You found the flaw - I''m grateful, truly - and now you want to start interrogating my APPRENTICE?" He steps in front of Nim. "The schematics are worthless anyway. We''re done. Off you go, {{wizard|sellsword}}." / Brakk shifts his hammer, meaningfully. Nim won''t meet your eyes.', '', 1, 14, '', 0, ''),
(830, '"ENOUGH!" Fizzik''s voice cracks into a squeak. "I''ve wasted enough breath on you. Brakk - FLATTEN them!" / Brakk sighs, and lifts his hammer.', '', 1, 22, '', 0, ''),
(701, 'Oi! You there, wee one - that''s far enough. This seam''s staked an'' sealed by Clan Coppervein, and every claim-jumpin'' sneak in the valley''s been sniffin'' round it. You''ve the look of a sneak about ye.', '', 1, 25, '', 0, ''),
(716, 'Grumbold folds his arms. "Well? Say yer piece or clear off."', '', 1, 0, '', 0, ''),
(702, 'Grumbold looks you up and down. "Hmph. Ye don''t look like ye could lift a pick, never mind haul off a cart o'' ore. Fine. Off with ye - and if ye see any Rockjaws, send ''em my way."', '', 1, 274, '', 0, ''),
(703, '"Passin'' through, is it? That''s what the last one said, right before me best pick went missin''." He cracks his knuckles. "Lads - teach this one some manners."', '', 1, 14, '', 0, ''),
(704, 'Grumbold''s eyes flick to the frost crackling over your fingertips, then to his diggers. Nobody moves. "...Bah. Not worth the trouble. Go on, then. Git."', '', 1, 0, '', 0, ''),
(705, 'He laughs - a deep, nasty sound. "Ye hear that, lads? The wee thing''s threatenin'' us!" The diggers level their blunderbusses.', '', 1, 11, '', 0, ''),
(706, 'Grumbold squints at the rock, then at the yellow cubes, then at you. He scrapes one with his thumbnail. It crumbles to black dust. His face falls. / "...Pyrite. Three weeks diggin'' fool''s gold." He spits. "Ye''ve an eye on ye, wee one. Go on - I''ve a fella in Kharanos to find."', '', 1, 274, '', 0, ''),
(707, 'You point at a glittering streak. Grumbold''s eyes go wide. "That''s the good stuff, ye daft wee thing - that''s GOLD!" He hefts his pick. "And now ye know where it is. Can''t have that."', '', 1, 5, '', 0, ''),
(708, '"Ye''re kin?" He peers at your beard, then roars with laughter. "Ha! Why didn''t ye say so? Any friend o'' the clan can walk where they like. Mind the troggs, cousin."', '', 1, 11, '', 0, ''),
(710, '"Gold, wee one! A seam of it - glitters like a king''s teeth." He thumps the rock face proudly. "Bought the claim off a fella in Kharanos for every coin I had." He frowns. "Fella seemed in an awful hurry to leave, now I think on it."', '', 1, 25, 'bought', 0, ''),
(711, 'You look past Grumbold at the rock face. It glitters gold, all right - in neat little cubes, too square to be natural-looking. The air down here stinks of rotten eggs, and where his pick has scraped, the "gold" has crumbled to greenish-black dust.', '', 0, 0, 'pyrite', 0, ''),
(712, '"Work''s fine," the digger mutters, with a glance at Grumbold. "Pay''s not. Three weeks and not a copper. He says we get paid when the gold comes out."', '', 2, 14, 'unpaid', 0, ''),
(718, 'The digger shrugs. "Ask him." / Grumbold doesn''t meet anyone''s eye.', '', 2, 0, '', 0, ''),
(713, 'The diggers look at each other, then at Grumbold. "...Three weeks," one says. "Not a copper." They shoulder their blunderbusses and walk off down the valley. / Grumbold watches them go, then sits down heavily on a rock. "Well. That''s that, then." He looks very old, suddenly.', '', 2, 0, '', 0, '2,3'),
(714, '"Fight?" Grumbold laughs without any humour in it. "No, lass, lad, whatever ye are. I want a drink." He waves you on. "Go. Leave an old fool to his rocks."', '', 1, 274, '', 0, ''),
(717, '"Our contract," the digger says slowly, "says we fight whoever he points at." Grumbold points at you.', '', 2, 25, '', 0, ''),
(715, 'Grumbold''s knuckles whiten on his pick. "Ye SEE, lads? SNEAK!"', '', 1, 22, '', -2, ''),
(719, '"Pyrite?" Grumbold goes purple. "PYRITE? I''ve been diggin'' rock since before yer granda grew his first whisker! Don''t ye tell ME what''s gold!" / He jabs a stubby finger at the seam. You can''t quite get the words out to explain it, and the diggers are fingering their blunderbusses.', '', 1, 22, '', -2, ''),
(720, 'A spark leaps from your finger to the nearest cube. It doesn''t melt - it hisses, spits, and gives off a stinking yellow smoke. Grumbold reels back, coughing. / "...That''s no gold." He prods the blackened lump with his pick. "That''s rotten-egg rock. Three weeks diggin'' fool''s gold." He spits. "Go on, wee one. I''ve a fella in Kharanos to find."', '', 1, 274, '', 0, ''),
(721, 'Grumbold opens his mouth to argue - and shuts it again. "...Not on the rolls." He sits down hard on the cart. "Every coin I had. For a claim he never owned." He looks up at you, and the fight''s gone out of him. "Go on, wee one. I''ve a fella in Kharanos to find, and a long walk to think about what I''ll say to him."', '', 1, 274, '', 0, ''),
(722, 'You reach for the details - which hall, which roll, who keeps it - and come up empty. "The ROLLS?" Grumbold''s beard bristles. "Ye think a Coppervein doesn''t know his own clan''s business? Ye''ve never set foot in the Hall o'' Explorers in yer life!" / The diggers snicker.', '', 1, 22, '', -2, ''),
(723, 'You squint past Grumbold at the rock face. It glitters gold in the lamplight - a lot of it. As far as you can tell, the old dwarf has struck it rich.', '', 0, 0, '', 0, ''),
(790, '"That''s IT." Grumbold hefts his pick. "Lads - teach this one some manners!"', '', 1, 22, '', 0, ''),
(101, 'Two wolf pups crouch over a sprung snare, all ribs and teeth. Whatever was caught in it is long gone. They see you, and the growling starts - thin and high, more frightened than fierce. Every time the wind rattles the frozen branches, their ears flatten.', '', 0, 0, '', 0, ''),
(102, 'You sink down, eyes on the snow, and ease backwards one step at a time. The growling falters. The pups exchange a look, decide you''re not worth it, and go back to licking the empty snare.', '', 0, 0, '', 0, ''),
(103, 'The pups read it as a challenge. The bigger one lunges, and the other follows it in.', '', 0, 15, '', 0, ''),
(104, 'The crack of your palms echoes off the valley walls. Both pups jump as if stung - and bolt, yelping, into the trees.', '', 0, 0, '', 0, '0'),
(105, 'A few tufts of white fur cling to the wire: a rabbit, once. And there - half-buried in a drift a few paces away, where it must have been knocked loose - a second rabbit, frozen stiff. The trapper missed it. The pups haven''t smelled it yet.', '', 0, 0, 'rabbit', -1, ''),
(109, 'The pups are still growling, a little closer now. They''re hungry, and you''re standing between them and nothing.', '', 0, 0, '', 0, ''),
(106, 'The frozen rabbit skids across the snow and fetches up against the snare. The pups fall on it in a snarling heap. You walk on; neither of them looks up.', '', 0, 0, '', 0, ''),
(107, 'A tongue of flame leaps from your fingertips with a crack. The pups scramble backwards, tumble over each other, and flee whimpering into the trees.', '', 0, 0, '', 0, '0'),
(108, 'You hold out a hand. The bigger pup snaps at it - teeth clicking a finger''s width from your knuckles - and both of them edge closer, hackles up.', '', 0, 15, '', -2, ''),
(113, 'The whistle shrieks down the valley like a kettle the size of a house. Both pups leave the ground. They are over the ridge before the echo comes back, and somewhere far off a mountaineer shouts something rude about whoever has found Dorrin''s whistle.', '', 0, 0, '', 0, '0'),
(111, 'Ribs like a washboard, legs trembling, coats patchy from the cold. They''d eat anything you threw them - and they''re far too weak to chase anyone for long. Back off calmly and they''ll let you go.', '', 0, 0, 'starving', 0, ''),
(112, 'They look like wolves. Hungry ones. You stare a moment too long, and the bigger pup''s growl climbs a note.', '', 0, 0, '', -1, ''),
(190, 'Hunger wins. The pups stop growling - and lunge.', '', 0, 15, '', 0, ''),
(201, 'Two Rockjaw troggs are tearing apart a mountaineer supply crate, hooting and shoving. The big one clutches something that glints; the smaller one keeps trying to snatch it. Neither has noticed you yet.', '', 0, 0, '', 0, ''),
(202, 'You slip from rock to rock until you''re close enough to hear them breathing. They''re still squabbling over the crate.', '', 0, 0, '', 0, ''),
(203, 'A frozen branch snaps under your boot. Both troggs spin around, howling.', '', 0, 15, '', 0, ''),
(204, 'The glinting thing is a brass compass. The big trogg holds it up to the light, mesmerised, and shoves the smaller one face-first into the snow when it reaches. Everything shiny from the crate - buckles, a tin cup, a spoon - has ended up in a heap at the big one''s feet.', '', 0, 0, 'shiny', 0, ''),
(209, 'Your thumb slips. The button skitters a few feet and stops - right between the big trogg''s toes. It picks the button up, turns it over, and follows the line of its path back across the snow. To you.', '', 0, 15, '', 0, ''),
(205, 'The button spins away, flashing in the sun, and drops into a drift. Both troggs freeze. Then they''re off - shoving and biting each other through the snow after it, the crate forgotten.', '', 0, 0, '', 0, '0'),
(210, 'The compass flashes once in the sun, and both troggs go rigid. Then it''s sailing over their heads into a drift - and they''re gone after it, biting and shoving, the crate already forgotten. Somewhere out in the snow, the big one hoots in triumph.', '', 0, 0, '', 0, '0'),
(211, 'You burst from cover with a bellow that echoes off the cliffs. The troggs drop everything and run, the small one still clutching a spoon.', '', 0, 0, '', 0, '0'),
(212, 'You roar. The big trogg looks at you, thumps its chest, and roars back - louder, and with considerably more teeth.', '', 0, 15, '', 0, ''),
(206, 'You cup your hands and let rip a wet, warbling trogg hoot from the rocks downhill. Both troggs freeze, bristle, and go crashing off to see who''s moving in on their patch - the small one still clutching a spoon.', '', 0, 0, '', 0, '0'),
(207, 'Your hoot comes out as a strangled honk. The big trogg looks straight at your rock, thumps its chest, and comes to see what kind of animal makes a noise like that.', '', 0, 15, '', 0, ''),
(208, 'Both troggs look at you. Then at each other. Then they charge.', '', 0, 15, '', 0, ''),
(301, 'Three crag boars root and grunt in a steaming patch of mud. The largest has a loop of snare wire biting into its foreleg; every step makes it squeal, and the other two press close around it, bristling at anything that moves.', '', 0, 0, '', 0, ''),
(302, 'You talk low and nonsensical, the way farmers do, and inch closer. The big boar trembles but holds still. The wire parts with a twang. It shakes its leg, snorts at you, and goes back to wallowing.', '', 0, 0, '', 0, ''),
(303, 'The big boar squeals as you reach for the wire, and the other two take it as a call to arms.', '', 0, 15, '', 0, ''),
(304, 'The mud is churned and bare - the boars have eaten every root for twenty paces around. They''re hungry and they can''t roam with the big one lamed. Beyond the trees, a stand of frost-turnips pokes through the snow, untouched.', '', 0, 0, 'turnips', 0, ''),
(310, 'Churned mud, trampled snow, bare roots. If there''s anything out here a boar would eat, you can''t see it - and the big one has noticed you poking about.', '', 0, 0, '', 0, ''),
(308, 'You lob the first turnip a little too hard. It bounces off the lame boar''s snout. As far as the boars are concerned, that was an opening shot.', '', 0, 15, '', 0, ''),
(309, 'A thin beam of cold licks along the snare. The wire frosts white, creaks - and snaps at a flick of your fingers. The big boar shakes its leg free, snorts in surprise, and trots off with the other two close behind.', '', 0, 0, '', 0, '0'),
(305, 'The turnips thump into the mud. Three snouts go down at once. While they crunch, the big boar is too busy to care who''s standing beside it.', '', 0, 0, '', 0, ''),
(311, 'You throw your arms wide and stamp and holler. The two healthy boars wheel and trot off a little way - and the lame one, squealing, limps after them, out of the wallow and out of your path.', '', 0, 0, '', 0, '0'),
(306, 'The largest boar lowers its head. The other two follow its lead.', '', 0, 15, '', 0, ''),
(307, 'The wire comes away in your hand. The big boar doesn''t even look up from its turnip.', '', 0, 0, '', 0, ''),
(401, 'A grey timber wolf stands over a fresh goat kill, two half-grown pups at its flanks. Its hackles rise as you come into view. It favours its left side - and a broken trogg spear is lodged deep in its shoulder.', '', 0, 0, '', 0, ''),
(402, 'You lower your gaze and step back, then again. The alpha''s growl fades to a rumble. It doesn''t follow - it drops its head and goes back to the kill, one eye always on you.', '', 0, 0, '', 0, ''),
(403, 'The alpha takes it as a challenge. It lunges - and the pups come with it.', '', 0, 15, '', 0, ''),
(404, 'The spear is barbed - Rockjaw work. Every time the alpha shifts its weight, the shaft grinds in the wound. It''s in agony. But it hasn''t charged you. It''s standing over its pups, not stalking you: guarding, not hunting.', '', 0, 0, 'wound', 0, ''),
(405, 'The pups take every cue from the alpha, and the alpha is in too much pain to want a fight. As long as you keep your hands open and away from the kill, it won''t start one.', '', 0, 0, 'calm', 0, ''),
(406, 'You can''t remember a thing about wolves - and while you rack your brains, you''ve been staring the alpha in the eye. To a wolf, that''s a challenge.', '', 0, 15, '', 0, ''),
(407, 'The alpha''s lips peel back from its teeth as you kneel - and then it lets you. You brace a hand against its shoulder and pull. The spear comes free. The wolf licks the wound, looks at you for a long moment, and leads its pups away into the trees.', '', 0, 0, '', 0, '0'),
(408, 'The barbs catch. The alpha howls - and its pups come for you.', '', 0, 15, '', 0, ''),
(409, 'Sparks shower and crackle across the snow. The pups bolt; the alpha drags the goat a few paces, thinks better of it, and limps after them.', '', 0, 0, '', 0, '0'),
(411, 'From here it''s all matted fur and blood - you can''t make out what''s wrong with it, only that it isn''t moving away. The alpha''s stare doesn''t leave you.', '', 0, 0, '', 0, ''),
(410, 'You take one step toward the goat. That is one step too many.', '', 0, 15, '', 0, ''),
(501, 'The troggs have been tunnelling into the hillside after something that glitters in the rock. A timber prop has given way: one trogg is pinned under the fallen beam, howling, while the big one heaves at it uselessly and the third gnaws its own knuckles.', '', 0, 0, '', 0, ''),
(502, 'You scramble up the rock, pick your spot, and drop onto the far end of the beam. It see-saws up, the big trogg heaves underneath, and the beam shifts - and the pinned one scrambles free. Three pairs of beady eyes regard you in baffled silence. Then the big one grunts, drops a fist-sized lump of glittering rock at your feet, and the three of them lope off into the dark.', '', 0, 0, '', 0, '0'),
(503, 'The beam slips back down. The pinned trogg shrieks, and the big one decides, very clearly, that this is your fault.', '', 0, 15, '', 0, ''),
(504, 'The beam rests across a single rounded stone, like a seesaw with a trogg on one end. A long enough pole wedged under the other end would lift it easily - and there''s a broken pick handle lying in the dirt right beside it.', '', 0, 0, 'lever', 0, ''),
(509, 'A slick of grease blooms across the stone under the beam. It slides off with a wet scrape, and the pinned trogg squirts free like a pip from a grape. Three troggs stare at you, then at the gleaming mess, and back away into the tunnels, hooting in alarm.', '', 0, 5, '', 0, '0'),
(505, 'You jam the handle under the beam and lean on it. The beam rises as if it weighed nothing. The pinned trogg wriggles free, and all three stare at you, then at the handle, then at you again, as though you''d performed a miracle. They back away into the tunnels, hooting softly.', '', 0, 5, '', 0, '0'),
(506, 'You slip along the rock face until you''re right behind the big one. None of them has looked round.', '', 0, 0, '', 0, ''),
(507, 'Loose scree rattles under your boots. Three trogg heads swivel toward you at once.', '', 0, 15, '', 0, ''),
(508, 'The big trogg stops heaving. It turns, very slowly, and looks at you. The third one stops gnawing its knuckles.', '', 0, 15, '', 0, ''),
(601, '"Stop dere, little one. Dis be Frostmane ground now." A troll novice kneels in a circle of frost-chalk, a bone fetish in each hand. Two whelps lounge behind him with spears, looking bored out of their minds. "Grik''nir want dis ritual done by moonrise. You interrupt, you become part of it."', '', 1, 25, '', 0, ''),
(612, '"Well?" the novice hisses. "Speak or go. Moonrise be coming."', '', 1, 0, '', 0, ''),
(602, '"Grik''nir call de cold. De cold call de spirits. De spirits make de Frostmane strong." He shakes a fetish at you. "If de circle be whole." / His eyes flick, just for a moment, to the edge of the circle - where one of the whelps is standing, and the chalk line is smeared under his foot.', '', 1, 6, 'circle', 0, ''),
(603, 'The novice goes grey. "Broken? No. No no no-" He scrabbles at the chalk on hands and knees. "Go! Go, before de spirits come and I have to explain YOU!"', '', 1, 5, '', 0, ''),
(604, '"You lie! Dere be NOTHING wrong wit'' my circle!" The novice leaps up, frost crackling around his fetishes. "Whelps! Dis one want to be a sacrifice!"', '', 1, 22, '', 0, ''),
(605, 'The novice follows your finger to the smeared chalk under the whelp''s foot. There is a terrible silence. / "YOU." He rounds on the whelps, screeching in Zandali. They back away, then turn and slink off into the trees, leaving the novice alone in his broken circle with you.', '', 1, 22, '', 0, '2,3'),
(606, '"Guard duty," the whelp spits. "Grik''nir promise us RAIDING. Instead we watch de chalk-man draw pictures in de snow." / The other whelp snickers. The novice pretends not to hear.', '', 2, 14, 'bored', 0, ''),
(607, 'The whelps exchange a look. "Unguarded?" "East?" / They''re gone before the novice can open his mouth. He watches them go, then turns back to you, very much alone. "...Dis be your fault."', '', 2, 5, '', 0, '2,3'),
(608, 'The whelps exchange a look - then level their spears at you. "Nice try, little one. We take de crate AFTER we take you."', '', 2, 11, '', 0, ''),
(609, 'The novice blanches. "Tired? Already?" He sweeps the fetishes into a pouch. "Whelps - we go. NOW. Before he come himself." / All three trolls hurry off toward the caves, the whelps casting suspicious looks back at you.', '', 1, 5, '', 0, '0'),
(610, '"Grik''nir send YOU?" The novice laughs, high and ugly. "Grik''nir EAT little ones like you! Whelps - kill it!"', '', 1, 11, '', 0, ''),
(611, '"Dis no DRAWING!" The novice''s voice cracks. "Dis be SACRED!"', '', 1, 22, '', -2, ''),
(613, '"Ha!" The novice grins, showing every tusk. "Maybe. As de offering."', '', 1, 11, '', -1, ''),
(614, 'Every troll in the camp goes very still. The novice stands up. "Ironforge," he says softly, "be a long way from here, stunty."', '', 1, 15, '', 0, ''),
(615, 'The novice weighs his chances, alone, against you. He does not like the answer. Muttering curses in Zandali, he gathers his fetishes and stalks off after the whelps.', '', 1, 14, '', 0, '1'),
(616, '"Walk away? From a little one?" The novice laughs and raises his fetishes. Frost blooms in the air around him.', '', 1, 11, '', 0, ''),
(617, 'You point - at a perfectly good stretch of chalk. The novice looks, sees nothing wrong, and looks back at you with narrowed eyes. "You mock de circle, little one? You mock GRIK''NIR?" / The whelps perk up. Finally, something to do.', '', 1, 22, '', 0, ''),
(618, 'A thin ribbon of cold runs from your fingertips along the smeared line. The chalk frosts over, glittering, and the circle is whole. The novice stares at it, then at you. / "...Dat be GOOD frost." He bows - just a little. "Go, frost-friend. Grik''nir no need to know a little one fix his circle."', '', 1, 5, '', 0, ''),
(619, 'You know these marks: Zandali loa-script, a calling circle. Every line has to close - a single break and whatever answers the call takes the caller instead of the offering. The novice would know that too, if he stopped to look.', '', 0, 0, 'loa', 0, ''),
(620, 'Squiggles and bones in the snow. Whatever they mean, it''s lost on you - and the novice has noticed you staring at his work. "Eyes OFF, little one."', '', 1, 14, '', -1, ''),
(690, '"ENOUGH talk!" The novice leaps to his feet. "Whelps - kill it!"', '', 1, 22, '', 0, ''),
(901, '"So. De little ones send a little hero." Grik''nir the Cold rises from a throne of frozen bones, frost curling off his claws. Behind him, two whelps flinch at the sound of his voice. "You come to die cold - or you come to beg?"', '', 1, 25, '', 0, ''),
(905, '"Talk, talk," Grik''nir growls. "My claws get cold waiting."', '', 1, 0, '', 0, ''),
(902, 'You watch the whelps. One has fresh frost-burns down his arm - the kind that come from a master''s claws. The other won''t look at Grik''nir at all. They aren''t loyal. They''re terrified.', '', 0, 0, 'fear', 0, ''),
(903, 'Grik''nir laughs. "You look at my whelps? Den dey look at YOU." He points a frozen claw. "Kill it."', '', 1, 25, '', 0, ''),
(904, 'The whelps look at each other, then at the burns on their arms. One throws down his spear. Then the other. They run. / Grik''nir screams after them, frost exploding from his claws - and then turns slowly back to you, alone.', '', 0, 0, '', 0, '2,3'),
(911, 'The whelps look at each other - and then at Grik''nir, who is smiling. They raise their spears.', '', 0, 0, '', 0, ''),
(906, 'Grik''nir goes perfectly still. "...A new chief." Frost spreads across the ground from his feet. "WHO?" He doesn''t wait for an answer - he''s already storming off toward Frostmane Hold, howling, the whelps scrambling after him.', '', 1, 15, '', 0, '0'),
(907, '"Lies!" Grik''nir bares his tusks. "I KNOW lies, little one. I tell dem every day." He spreads his claws. "Now you die cold."', '', 1, 11, '', 0, ''),
(908, 'While Grik''nir gloats to his whelps, you slip around the pile of frozen bones. You''re right behind him.', '', 0, 0, '', 0, ''),
(909, 'A frozen bone cracks under your foot. Grik''nir spins around, grinning. "Sneaky. I like sneaky. Sneaky taste better."', '', 1, 11, '', 0, ''),
(910, '"Ha! Dat I like." Grik''nir licks his tusks, considering you. "...No."', '', 1, 11, '', -1, ''),
(990, '"ENOUGH!" Frost explodes from Grik''nir''s claws. "Now you die cold!"', '', 1, 15, '', 0, ''),
(1001, 'Three Rockjaw raiders squat round a fire of broken cart boards, gnawing on something you''d rather not look at too closely. A dented mountaineer''s helmet sits upturned between them, brim-full of coins, buttons and bottle caps. The biggest one keeps a hand on it - and keeps glancing at the trail you came down.', '', 0, 0, '', 0, ''),
(1007, 'The raiders squabble over the helmet. None of them has seen you yet.', '', 0, 0, '', 0, ''),
(1002, 'You watch. They take turns staring at the trail, and the boss doesn''t let anyone else near the helmet. When a log in the fire spits, he flinches back so hard he nearly drops it - and the other two snicker behind his back. He''s terrified of the flames.', '', 0, 0, 'firefear', 0, ''),
(1003, 'You ease from boulder to boulder until you''re right behind them. Not one of them has turned round.', '', 0, 0, '', 0, ''),
(1004, 'A raider''s nose twitches. Then all three are on their feet, clubs up, howling.', '', 0, 15, '', 0, ''),
(1005, 'The boss shrieks at the flame, clutches his helmet of treasures to his chest and bolts up the trail. The other two scramble after him, leaving the fire to gutter out.', '', 0, 0, '', 0, '0'),
(1006, 'The boss squints at your little flame, then at his own roaring fire - and laughs a wet trogg laugh. All three reach for their clubs.', '', 0, 11, '', 0, ''),
(1101, '"Shhh." Three Frostmane seers kneel round a smoking clay bowl, eyes rolled back, lips stained blue. The eldest opens one eye - it glows faintly - and fixes it on you. "De loa be talking, little one. Dey say a stranger come. Dey say maybe de stranger die. Maybe not. Sit. Or go. Or die."', '', 1, 6, '', 0, ''),
(1111, 'The eldest seer sways. "De smoke is waiting. So are we."', '', 1, 0, '', 0, ''),
(1102, '"De loa show us de cold one, dying in de little valley. Good. He was loud." The seer smiles with blue teeth. "And dey show us a chief in de north who wear a crown of bone. He want de seers to read only good omens for him. We read what de loa SAY."', '', 1, 6, '', 0, ''),
(1103, 'The smoke takes you. A troll in a crown of frozen bone, asleep on a throne of ram skulls, an axe across his knees - and the ice cracking beneath his feet. When you come back, the eldest seer is staring at you. / "You SAW." He bows his head. "De loa show you de chief, and de cracks. We not fight one de loa favour. Go."', '', 1, 2, '', 0, ''),
(1104, 'The smoke hits the back of your throat like a fist. You cough, splutter and sneeze - and blow half the bowl''s ashes across the eldest seer''s face. / "...De loa," he says, very quietly, "do not like you."', '', 1, 14, '', -2, ''),
(1105, 'The eldest seer looks down at the blue paste on his fingers. Then at the youngest, who is shaking and whispering to his own hands. "...De chief send us dis weed. More every moon." His face hardens. "Den de chief can read his own omens." He sweeps the bowl into the snow and the three of them walk off into the wind.', '', 1, 274, '', 0, '0'),
(1106, '"You call de loa''s gift POISON?" All three seers rise at once, frost crackling around their staves.', '', 1, 22, '', 0, ''),
(1107, 'The youngest seer gasps. "Clean weed. CLEAN. Not de black stuff de chief send." The eldest takes the bundle in both hands as if it were gold. "Dis is a true gift. De loa see it." He presses a cold finger to your brow. "Walk safe, gift-giver."', '', 1, 2, '', 0, ''),
(1108, 'The seers look at each other. The eldest leans close, sniffing. "...De stranger who lives." A slow smile. "Den you live. Go, before de loa change dey mind."', '', 1, 2, '', 0, ''),
(1109, '"De loa send no one." The eldest seer''s eye blazes. "But dey tell us when someone LIE."', '', 1, 25, '', 0, ''),
(1110, '"Ha." The seer pulls the bowl closer. "No."', '', 1, 11, '', -1, ''),
(1190, 'The eldest seer stands, and the smoke stands with him. "ENOUGH. De loa say: dis one goes in de bowl."', '', 1, 22, '', 0, ''),
(1201, 'The den stinks of wet fur and old blood. Two wendigos crouch over a ram carcass just inside, and behind them, in the dark, something much bigger shifts its weight with a grunt of pain: a great white wendigo, one hind leg bound in a filthy crust of ice. It lifts its head, and the others go quiet.', '', 0, 0, '', 0, ''),
(1209, 'The pack watches you. The big one''s breath steams in the cold.', '', 0, 0, '', 0, ''),
(1210, 'You beat your fists against the rock and roar until your throat burns. The two at the carcass flinch back. The big one stares at you for a long, long moment - then, with a grunt of pain, it turns away into the dark, and the pack follows it.', '', 0, 0, '', 0, '0'),
(1202, 'Its left hind leg won''t take its weight - an old trap wound, festering under the ice. It''s the pack''s leader, and it''s hurting, and every time it shifts the others flinch. They''re watching it, not you.', '', 0, 0, 'lame', 0, ''),
(1203, 'You sink down and edge backwards, never turning your back, never looking at the kill. The big one watches you all the way out. At the last moment it lowers its head and goes back to the ram.', '', 0, 0, '', 0, ''),
(1204, 'Your boot scrapes on the stone. The big one roars, and the two at the carcass come at you.', '', 0, 15, '', 0, ''),
(1205, 'You slide along the wall into the dark at its left side, where the bad leg can''t turn it round in time.', '', 0, 0, '', 0, ''),
(1206, 'A loose stone skitters across the floor. Three white heads swing toward you at once.', '', 0, 15, '', 0, ''),
(1207, 'It growls the whole time - a sound you feel in your teeth - but it lets you. The ice comes away, then the rot beneath, and you pack the wound with snow. When you step back the big one stands on all four legs for the first time in who knows how long. It looks at you, then limps deeper into the den, and the pack follows.', '', 0, 0, '', 0, '0'),
(1208, 'You touch the ice and it roars - pain and fury together - and the pack comes boiling out of the dark.', '', 0, 15, '', 0, ''),
(1301, 'The cave is cold enough to crack teeth. Bones carpet the floor - ram, boar, and some that were never animals. At the back, curled on a heap of stolen hides, lies the biggest yeti you have ever seen: white fur gone yellow with age, a frozen beard hanging from its jaw like icicles. Its chest rises and falls. Slowly. For now.', '', 0, 0, '', 0, ''),
(1306, 'Old Icebeard snores, a sound like grinding ice.', '', 0, 0, '', 0, ''),
(1305, 'Among the bones: a broken hunting spear, a dented Stormpike buckler, fresh drag marks. It has been feeding well. And right above the sleeping beast, a great ledge of old ice hangs from the cave roof, cracked through at its base.', '', 0, 0, 'ice_ledge', 0, ''),
(1302, 'You time your steps to its snores. At the back of the cave, under the hides, you find what it has been guarding: a hunter''s pack, still buckled, and a Stormpike signal horn. You''re out in the daylight again before the snoring even changes.', '', 0, 0, '', 0, ''),
(1303, 'A bone cracks under your boot. The snoring stops. One huge pale eye opens - and Old Icebeard rises, and rises, and rises.', '', 0, 15, '', 0, ''),
(1308, 'One lid has slipped half open in its sleep. The eye beneath is milk-white, clouded right across - and the other, when it twitches, is little better. The old miners had it right: the beast below hunts by sound and smell. Come at it from downwind, on the side of the dead eye, and it will never know you were there until you want it to.', '', 0, 0, '', 0, ''),
(1304, 'You''re close enough to smell its breath. It hasn''t moved.', '', 0, 0, '', 0, ''),
(1307, 'The ledge gives with a crack like thunder and comes down on the sleeping yeti in a roar of ice. When the powder settles, Old Icebeard is half buried, dazed and bleeding - and furious.', '', 0, 15, '', 0, ''),
(1401, '"Who - who goes there? Friend? Foe? INSPECTOR?" A gnome in rags waves a wrench at you, his skin blotched and faintly glowing green. Two more crouch behind him, muttering to a broken gear. "No inspectors! The readings are FINE. Everything is FINE!" His eyes keep sliding off your face, as if he can''t quite hold on to it.', '', 1, 25, '', 0, ''),
(1411, '"Well? Well? Speak up, the readings won''t take themselves!"', '', 1, 0, '', 0, ''),
(1402, '"My name?" He looks stricken. "My name is... it''s..." He pats his pockets, one after another, faster and faster. "I had one. I KEEP it somewhere. I write it down so I won''t - so I won''t -" / He trails off.', '', 1, 6, '', 0, ''),
(1403, 'He goes very still. "...Fimble." He says it again, tasting it. "Fimble. FIMBLE. That''s me. That''s ME." For a moment his eyes are clear. "Thank you. I - you should go, before I lose it again." He turns to the others, gentler now. "Come on, lads. Away from the cave. The air''s better away from the cave."', '', 1, 2, '', 0, '0'),
(1404, 'He snaps upright so fast he nearly falls over. "Engineer Third Class, sir! Readings are... readings are..." His face crumples. "The readings were never fine, sir." He salutes with the wrench. "Permission to stand down and go somewhere warm?" / You give it. The three of them shuffle away down the slope, arm in arm.', '', 1, 16, '', 0, '0'),
(1405, '"Third CLASS? I was FIRST class! Inspector, inspector, this one''s a filthy INSPECTOR!"', '', 1, 22, '', 0, ''),
(1406, '"Away?" The gnome blinks, and some of the madness drains out of him. "Away. The air IS cleaner away. Fimble - no - someone said that. Someone said that." He takes the others by the hand and leads them off, still muttering numbers.', '', 1, 0, '', 0, '0'),
(1407, '"Blood? Sickness? You sound like an INSPECTOR."', '', 1, 22, '', -2, ''),
(1408, 'All three sag with relief. "Passed! We PASSED!" One of them bursts into tears. The leader pumps your hand. "Carry on, carry on! We''ll just - carry on!" They wander off, still beaming.', '', 1, 5, '', 0, '0'),
(1409, 'The gnome''s face twists. "That''s what they said LAST time. Right before the doors closed." He raises the wrench.', '', 1, 22, '', 0, ''),
(1490, '"INSPECTOR! INSPECTOR! GET THE GADGETS!"', '', 1, 22, '', 0, ''),
(1501, 'The quarry floor is a maze of half-cut stone. Three Rockjaw troggs are prodding a dwarf in a torn mountaineer''s tabard toward an ore cart, hooting every time he stumbles. He''s chained to it by the ankle. / "Keep yer filthy paws - OW - I''m goin'', I''m goin''!"', '', 0, 0, '', 0, ''),
(1510, 'The troggs shove the dwarf toward the cliff again.', '', 0, 0, '', 0, ''),
(1502, 'The troggs make the dwarf haul the cart to a crack in the cliff and tip the ore down into the dark. They aren''t mining - they''re filling something in. And the chain on his ankle is fixed to the cart by a single rusted pin.', '', 0, 0, 'pin', 0, ''),
(1503, 'You slide down behind the cart while the troggs argue and work the pin loose. The dwarf feels the chain go slack, looks down at you, and grins through a split lip. Then he picks up the cart handle.', '', 0, 0, '', 0, ''),
(1504, 'The pin won''t budge - and the nearest trogg turns round and finds you crouched at its feet.', '', 0, 15, '', 0, ''),
(1505, 'The dwarf''s head snaps up. "That''s me RING! Where''d ye -" / Every trogg turns to stare at you. Which is exactly when Thalgrim Coppervein brings the cart handle down on the nearest one''s head.', '', 0, 5, '', 0, ''),
(1506, 'Your war-cry rolls round the quarry walls until it sounds like a whole company coming. The troggs drop everything and scramble for the tunnels. The dwarf sits down hard on his cart and laughs until he cries.', '', 0, 0, '', 0, '0'),
(1507, 'It comes out more squeak than roar. The troggs look up at you, then at each other, and start climbing.', '', 0, 11, '', 0, ''),
(1508, 'The boulder bounds down the slope in a spray of scree and smashes into the ore cart. The troggs scatter, shrieking - straight into the tunnels - and the dwarf, still chained to what''s left of the cart, cheers.', '', 0, 0, '', 0, '0'),
(1509, 'The boulder won''t budge. A trogg, attracted by your grunting, looks up.', '', 0, 15, '', 0, ''),
(1601, '"Another one." A huge Frostmane troll lounges on a throne of stacked ram skulls, a frost-bitten axe across his knees and a crown of frozen bone on his brow. Two hide-skinners flank him, scraping a fresh pelt. "You come to kneel to Vejrek - or to be a coat. Choose quick, little one."', '', 1, 25, '', 0, ''),
(1611, 'Vejrek drums his fingers on the axe. "Vejrek is waiting."', '', 1, 0, '', 0, ''),
(1602, 'Vejrek looks at the map for a long moment. The hide-skinners have stopped scraping. "...You been in my cave." He rolls his shoulders. "Little ghost. Vejrek respect a ghost who could have killed him and didn''t." He waves the axe at the trail. "Go. And do not come back at night."', '', 1, 274, '', 0, ''),
(1603, '"A MAP?" Vejrek laughs. "You think Vejrek sleep where a map say? Skin dis one."', '', 1, 11, '', 0, ''),
(1604, 'Vejrek''s grin goes very wide. "Clever little one. Yes. Rivals do not get de axe - dey get de needle, in de dark." He stands, and nods to his hide-skinners, who leave without a word. "But you, Vejrek kill with de axe. In de light. Dat is respect."', '', 1, 15, '', 0, '2,3'),
(1605, '"Needle?" Vejrek spits. "Vejrek fight with AXE. And you insult Vejrek."', '', 1, 14, '', 0, ''),
(1606, 'The camp goes silent. Then Vejrek throws his head back and laughs until the skulls rattle. "De little one want de crown! Good! Good!" He waves the hide-skinners away. "Nobody help. Vejrek want to enjoy dis."', '', 1, 11, '', 0, '2,3'),
(1607, '"Crown?" Vejrek doesn''t even stand. "Skin it."', '', 1, 25, '', 0, ''),
(1608, 'Vejrek''s eyes narrow - then glitter. "Grik''nir IS weak. Everyone know it." He strokes the crown. "Go, little one. Tell de valley Vejrek is coming. Tell dem to be ready." He laughs. "Dey will not be."', '', 1, 11, '', 0, ''),
(1609, '"Vejrek know what de tribe need. Vejrek do not need little ones telling him."', '', 1, 14, '', -1, ''),
(1610, 'You kneel in the snow. Vejrek leans forward, enjoying it, and lets you stay there a long, cold moment. "Good. Smart." He spits beside your knee. "Go. Tell dem down south dat Vejrek let you crawl away."', '', 1, 11, '', 0, ''),
(1690, '"ENOUGH." Vejrek rises, and keeps rising. "Skin it."', '', 1, 15, '', 0, ''),
(1701, 'Below a ledge of old mine-workings, a she-bear the colour of dirty snow is digging at the frozen ground while a half-grown cub tumbles round her feet. She''s seen you. She rears up, huffing, and the cub scrambles behind her.', '', 0, 0, '', 0, ''),
(1708, 'The she-bear huffs and paws the snow, watching you.', '', 0, 0, '', 0, ''),
(1702, 'You drop your gaze and step back, then again. She drops to all fours with a final huff and goes back to her digging. The cub peeks out at you from behind her leg.', '', 0, 0, '', 0, ''),
(1703, 'You meet her eye for a heartbeat too long. She charges.', '', 0, 15, '', 0, ''),
(1704, 'Old miners'' runes: ''beast below'' - a den this bears'' family has held for generations. Up on the ledge, out of her reach and out of her way, is where the old miners waited for her to settle each spring.', '', 0, 0, 'den_below', 0, ''),
(1705, 'Scratches and old marks. They mean nothing to you - and while you squint at them, the bear takes a step closer.', '', 0, 0, '', 0, ''),
(1706, 'You haul yourself up onto the ledge and sit very still. After a while the she-bear stops huffing, nudges the cub ahead of her and lumbers off into the den below. The way is clear.', '', 0, 0, '', 0, '0'),
(1707, 'Your hand slips on the ice and you tumble back down - right at her feet.', '', 0, 15, '', 0, ''),
(1801, 'A Frostmane hunting party - two lean snowstriders and a headhunter with a string of fresh scalps at his belt - crouches over a set of tracks, arguing in Zandali and jabbing their spears in different directions. Whatever they were tracking, they''ve lost it.', '', 0, 0, '', 0, ''),
(1802, 'You drag a branch through the snow and leave a trail even a Frostmane couldn''t miss, away into the pines. Before long the hunters pick it up, whooping, and lope away after it.', '', 0, 0, '', 0, '0'),
(1803, 'You look up from your fake tracks to find the headhunter watching you, head on one side.', '', 0, 15, '', 0, ''),
(1804, 'A pause. Then the headhunter bellows something and all three are off northwards at a run, spears high.', '', 0, 0, '', 0, '0'),
(1805, 'Your Zandali comes out as something rude about the headhunter''s mother. He seems to understand that part perfectly.', '', 0, 15, '', 0, ''),
(1806, 'You burrow into the drift. The hunters argue their way right up to you, and stop with their backs turned.', '', 0, 0, '', 0, ''),
(1807, 'The drift collapses on top of you with a soft whump. When you dig your way out, three spears are pointed at your nose.', '', 0, 11, '', 0, ''),
(1901, 'Two winter wolves, white as the drifts, worry at a frozen elk carcass in a hollow below the trail. One lifts its head, nose working, and the other stops chewing.', '', 0, 0, '', 0, ''),
(1909, 'The wolves go back to the elk, but one keeps an ear turned your way.', '', 0, 0, '', 0, ''),
(1902, 'The wind''s coming up the hollow toward you. They can''t smell you - not yet.', '', 0, 0, 'downwind', 0, ''),
(1903, 'You lick a finger and hold it up. Somewhere below, a wolf sneezes - and looks straight at you.', '', 0, 0, '', 0, ''),
(1904, 'The meat lands in the snow. Both wolves look at it, then at you, then back at the meat. Food that isn''t frozen solid wins. You back away while they squabble over it.', '', 0, 0, '', 0, ''),
(1905, 'The wolves don''t take it the way you meant. Hackles up, they come for you.', '', 0, 15, '', 0, ''),
(1906, 'You throw your arms wide and roar. The wolves weigh up the elk against you - and drag what''s left of the elk off into the trees.', '', 0, 0, '', 0, '0'),
(1907, 'You work your way round the lip of the hollow until you''re right behind them.', '', 0, 0, '', 0, ''),
(1908, 'Snow crunches under your boot. Two white heads snap round.', '', 0, 15, '', 0, ''),
(2001, 'You''ve had the feeling of being watched for a while now. Then you see them: two snow leopards on the rocks above the path, tails twitching, pacing you step for step.', '', 0, 0, '', 0, ''),
(2008, 'The leopards keep pace above you, closer now.', '', 0, 0, '', 0, ''),
(2002, 'There - a ledge just ahead where the path pinches in. That''s where they mean to drop on you. With your back to the big boulder short of it, they''d have to come at you head on.', '', 0, 0, 'pounce', 0, ''),
(2003, 'You stop to look - and lose sight of one of them altogether.', '', 0, 0, '', 0, ''),
(2004, 'Big cats stalk the weak and the lame. Stand tall, walk steady, never run. You square your shoulders and walk on at an even pace - and after a while, first one and then the other peels away into the rocks.', '', 0, 0, '', 0, '0'),
(2005, 'Was it ''run'' or ''don''t run''? While you''re thinking, they drop.', '', 0, 15, '', 0, ''),
(2006, 'You set your back to the rock and meet their eyes, one and then the other. A long, cold minute. Then they decide you''re not worth the trouble.', '', 0, 0, '', 0, '0'),
(2007, 'You stare. They stare. Then they jump.', '', 0, 15, '', 0, ''),
(2101, 'A crag boar the size of a pony is tearing up the snow where a farmer''s fence used to be, its hide bristling with broken arrows. It stops. It has seen you. It lowers its head and paws the ground.', '', 0, 0, '', 0, ''),
(2102, 'It huffs and trembles, but it lets you work. One by one the arrowheads come out. When the last one is gone it shakes itself like a dog, gives you a long look, and trots away, limping only a little.', '', 0, 0, '', 0, '0'),
(2103, 'The boar squeals with rage and comes at you.', '', 0, 15, '', 0, ''),
(2104, 'You catch the tusks and plant your feet. It drives you back a yard, two yards - and stops, sides heaving. You let go. It decides, wisely, to be somewhere else.', '', 0, 0, '', 0, '0'),
(2105, 'It charges. You step aside at the last instant and it thunders past into a boulder with a crack you feel in your teeth. It staggers, dazed.', '', 0, 5, '', 0, ''),
(2106, 'You step aside a moment too late.', '', 0, 15, '', 0, ''),
(2201, 'The trail narrows between two boulders, with a scree slope rising on your left. It''s too quiet. A pebble rattles down the slope and stops at your feet.', '', 0, 0, '', 0, ''),
(2202, 'There: two troggs flattened behind a ridge of rock above you, armfuls of stones ready.', '', 0, 0, 'spotted', 0, ''),
(2203, 'Nothing. Probably nothing. Probably.', '', 0, 0, '', 0, ''),
(2204, 'A startled hoot from above, the clatter of dropped stones - and two troggs scramble away over the ridge.', '', 0, 0, '', 0, '0'),
(2205, 'Stones come down like hail and two troggs come down after them.', '', 0, 15, '', 0, ''),
(2206, 'You come up behind them while they''re still watching the trail.', '', 0, 0, '', 0, ''),
(2301, '"Halt, little one." A Frostmane headhunter steps into the road, a troll outrider at his shoulder. "Dis be Vejrek''s road now. Everybody pay de toll."', '', 1, 25, '', 0, ''),
(2308, '"Well?" The headhunter taps his axe on his palm.', '', 1, 0, '', 0, ''),
(2302, '"Everything you carry," the headhunter says pleasantly. "And maybe de {{robe. Vejrek like a nice robe|shiny shield. Vejrek like a nice shield}}."', '', 1, 11, '', -1, ''),
(2303, 'The outrider mutters something in Zandali. The headhunter scowls. "...De seer, eh? Fine. Go. And tell de seer we want our cut."', '', 1, 274, '', 0, ''),
(2304, '"De seers do not wave anybody anywhere." The headhunter grins. "Liar pay double."', '', 1, 25, '', 0, ''),
(2305, 'The headhunter blinks. The outrider snorts with laughter. "...Salt. Dis one know de salt-toll." He shakes his head, half amused. "Nobody know de salt-toll any more. Go on, salt-knower."', '', 1, 11, '', 0, ''),
(2306, '"SALT?" The headhunter looks at you as if you''ve lost your mind. "De toll is EVERYTHING, little one."', '', 1, 14, '', -1, ''),
(2307, 'You hand over a fistful of coins. The headhunter bites one, pockets the lot, and waves you past with a mocking bow. "Vejrek thank you for your gift."', '', 1, 2, '', 0, ''),
(2309, 'The headhunter opens the pouch, sniffs, and his eyebrows climb. "...Real salt. Old-way toll." He tucks it away almost reverently and stands aside. "You pay proper, little one. Go."', '', 1, 2, '', 0, ''),
(2390, '"Enough talk." The headhunter hefts his axe. "We take de toll from de body."', '', 1, 15, '', 0, ''),
(2401, 'A young black bear has its whole head stuffed inside an abandoned hunter''s pack, rooting for something sweet. Its rump is towards you and its stubby tail is wagging. It hasn''t noticed you at all.', '', 0, 0, '', 0, ''),
(2402, 'You ease past with your heart in your mouth. The bear keeps rooting. Behind you, you hear a happy, muffled slurp.', '', 0, 0, '', 0, ''),
(2403, 'A stick snaps. The bear''s head comes out of the pack, sticky with honey, and it is NOT pleased to be interrupted.', '', 0, 15, '', 0, ''),
(2404, 'You hum, low and steady. The bear''s ears twitch. It backs out of the pack, looks at you with honey dripping off its nose, decides you''re not worth the bother, and ambles off with the honeycomb in its jaws.', '', 0, 0, '', 0, '0'),
(2406, 'The honeycomb lands in the snow with a soft thump. The bear''s head comes out of the pack, nose working. It looks at the honeycomb, looks at you, and lollops off after the better prize.', '', 0, 0, '', 0, '0'),
(2405, 'The bear spins round, honey everywhere, and charges.', '', 0, 15, '', 0, ''),
(9000, '"Halt. Name, business, and whether you''ve been bitten by anything. ...Fine. What do you want?"', '', 1, 1, '', 0, ''),
(9012, '"Run it, sweep it, cook for it and bury its dead, when it comes to that. Twelve of us were posted here at first frost. You''re looking at the ones who are left."', '', 1, 1, '', 0, ''),
(9013, '"Some to the trolls. Some to the pass when the gates shut and nobody came to relieve us. I don''t blame them. Much."', '', 1, 1, '', 0, ''),
(9010, 'Brassjaw''s mouth twitches - it might be a smile. She unhooks a red vial from her belt. "You''ll need this more than me. Don''t make me regret it."', '', 1, 2, '', 0, ''),
(9011, '"Hm." She turns back to the road. "Dismissed."', '', 1, 274, '', 0, ''),
(9020, '"Eh? Oh - a visitor. Sit, sit. Not on that, it''s my lunch. What can old Tam do for you?"', '', 1, 1, '', 0, ''),
(9032, '"Forty-one years. Started when the Anvilmar walls were new and my beard was red. Now look at the both of us."', '', 1, 1, '', 0, ''),
(9033, '"Never trust a quiet trogg, never pet a wolf, and never, ever play cards with a gnome."', '', 1, 1, '', 0, ''),
(9030, 'Tam wipes his eyes, laughing. "Nobody''s sat through that whole thing in twenty years!" He presses some coins on you. "Here. For your patience. Gods know you earned it."', '', 1, 2, '', 0, ''),
(9031, '"Eh, you young ones. No time for anything." He goes back to his lunch.', '', 1, 274, '', 0, ''),
(9040, '"Hold up. You''re walking like you''ve somewhere to be. Where''s that, then?"', '', 1, 1, '', 0, ''),
(9052, '"Wolves crossing from the east slopes, mostly. They follow the road at dusk - easier walking than the drifts. Same as us."', '', 1, 1, '', 0, ''),
(9050, 'She crouches by the tracks and swears softly. "Missed that. Wouldn''t have, an hour ago." She flips her belt knife and offers it hilt-first. "Take it. You''ve sharper eyes than I have today."', '', 1, 2, '', 0, ''),
(9051, '"Aye, well. I''ve been watching this road three years. I think I''d know." She waves you on.', '', 1, 274, '', 0, ''),
(9060, '"Anvilmar''s hall. Warm in here, at least - wipe your boots, the abbot''s particular about his floors. What''s your business?"', '', 1, 1, '', 0, ''),
(9072, '"Since the king shut the gates? Every cold soul in the valley ends up at our hearth. Can''t say I blame them."', '', 1, 1, '', 0, ''),
(9073, '"Because I''m guarding a fireplace, friend. Nobody writes songs about that."', '', 1, 1, '', 0, ''),
(9070, 'Durn grins for the first time. "Fair''s fair." He counts some coins out of a little tin. "Don''t tell the sergeant where you got them."', '', 1, 2, '', 0, ''),
(9071, '"Nice try." He leans back against the pillar. "Off you go."', '', 1, 274, '', 0, ''),
(9080, '"Wheet-wheeoo! Ha - got you. Everyone jumps. What brings you up from the valley?"', '', 1, 1, '', 0, ''),
(9092, '"Signal whistle. Three short means trolls, two long means troggs, one long and a warble means come and look at this marvellous bird I''ve found."', '', 1, 1, '', 0, ''),
(9090, 'Gorrim slaps his knee. "Ha! Someone with an ear!" He digs a red vial out of his pouch. "For emergencies. Like meeting someone with an ear."', '', 1, 2, '', 0, ''),
(9091, '"Hm. Close. Not quite." He turns back to the sky, whistling.', '', 1, 274, '', 0, ''),
(9100, '"You come up the west road? See anything with too many teeth and not enough manners?"', '', 1, 1, '', 0, ''),
(9112, '"One trogg. A big one, with a dented helm on its head - MY dented helm. Took it from my tent while I slept. I''d like it back. With interest."', '', 1, 1, '', 0, ''),
(9110, 'Mira''s eyes light up. "That''s it - that''s the hole!" She hands you a little purse. "The bounty. Half of it, anyway. I''ll have the other half out of the trogg."', '', 1, 2, '', 0, ''),
(9111, '"No... no, that''s not it." She goes back to scanning the slopes.', '', 1, 274, '', 0, ''),
(9120, '"I''ve no time for idle travellers. If you''re here to help, speak. If not, the tavern''s that way."', '', 1, 1, '', 0, ''),
(9132, '"Eyes. Swords. Supplies. Relief from Ironforge, which isn''t coming - not with a Dark Iron on the throne. Mostly, people who do what they say they''ll do."', '', 1, 1, '', 0, ''),
(9133, '"A Dark Iron regent on the High Seat. I don''t question it. Out loud."', '', 1, 1, '', 0, ''),
(9130, 'Thaneshield studies you for a long moment, then nods once. "Irregulars get paid. Don''t make me sorry." A purse of Watch silver lands in your hand.', '', 1, 2, '', 0, ''),
(9131, '"Words are cheap. Come back when you''ve done something." He turns to his maps.', '', 1, 274, '', 0, ''),
(9140, '"Slowly. I''ve had an arrow on the string since you came over that rise. Who are you?"', '', 1, 1, '', 0, ''),
(9152, '"From half a mile. You walk like a rockslide. Everyone down there does."', '', 1, 1, '', 0, ''),
(9150, 'Ysolde laughs and unstrings a second bow from her pack. "Here. Something to practise with. Old, but it shoots true."', '', 1, 2, '', 0, ''),
(9151, '"Hmph." The arrow doesn''t move. "On your way, then."', '', 1, 274, '', 0, ''),
(9160, '"East road''s closed past here. You''ll have to turn back - unless you''ve something to say to me first."', '', 1, 1, '', 0, ''),
(9172, '"Rockfalls on the old road, and worse things moving in the hills past them. Nobody goes through till the valleys behind us are quiet."', '', 1, 1, '', 0, ''),
(9173, '"Six days on, no relief. My partner walked to Kharanos for supplies. Four days ago."', '', 1, 1, '', 0, ''),
(9170, 'Brannoc wakes stiff and grateful. "First real sleep in a week." He presses a heavy flask into your hands. "Greater draught. Keep it for something worse than me."', '', 1, 2, '', 0, ''),
(9171, '"No. I''ll manage." He pulls his cloak tighter.', '', 1, 274, '', 0, ''),
(9180, '"Depot guard. If you''re after the steam tank, it doesn''t run. If you''re after the stores, they''re counted. What else is there?"', '', 1, 1, '', 0, ''),
(9192, '"A gnome left it here years ago and said he''d be back for it. It''s rusted to the rails now. I''ve grown fond of it."', '', 1, 1, '', 0, ''),
(9190, 'Kessa whoops. "THAT''S what was short!" She unlocks a crate and hands you a handaxe. "Spare stock. Officially it was never here."', '', 1, 2, '', 0, ''),
(9191, '"Hm. Count looks right to me." She locks the crate.', '', 1, 274, '', 0, ''),
(9200, '"Halt. This is the road to the city gates, and the gates are shut. What d''you want?"', '', 1, 1, '', 0, ''),
(9212, '"Because if I stop, someone''ll try it. And then I''ll have to explain to the king why there''s a fool stuck in his portcullis."', '', 1, 1, '', 0, ''),
(9210, 'Dagran blinks first - and roars laughing. "Done! Done, you win!" He pays up with good grace. "First time this month I''ve lost. Feels good, actually."', '', 1, 2, '', 0, ''),
(9211, '"HA!" He slaps you on the back hard enough to rattle teeth. "Better luck next time."', '', 1, 274, '', 0, ''),
(9220, '"Oh! Hello! Sorry - I''m on patrol, I have to keep walking. Walk with me?"', '', 1, 1, '', 0, ''),
(9232, '"Six years. I know every stone on it. I''ve named most of them. That one''s Gerald. Gerald''s been moved, and I''d like to know who by."', '', 1, 1, '', 0, ''),
(9230, 'Pell beams. "You''re the first person who''s kept up!" She digs in her pack. "Here - patrol rations. Well, the useful bits."', '', 1, 2, '', 0, ''),
(9231, '"Oh. Well. Maybe next time!" She hurries on.', '', 1, 274, '', 0, ''),
(9240, '"You climbed all the way up here? Hm. Most turn back. Sit. Look. Tell me what you see."', '', 1, 1, '', 0, ''),
(9252, '"From here I can see three valleys and the smoke of every troll fire in them. Nobody comes here but the wind. And now you."', '', 1, 1, '', 0, ''),
(9250, 'Hrodar nods slowly. "You see it too." He presses a bag of coins into your hand. "Found them under that stone years back. The mountain gives. Pass it on."', '', 1, 2, '', 0, ''),
(9251, '"Hm. Not yet." He turns back to the view.', '', 1, 274, '', 0, ''),
(9260, '"The gates are open, citizen. By order of the regent." He says the word like it tastes of ash.', '', 1, 1, '', 0, ''),
(9272, '"The king''s gone - turned to stone at the Great Forge, they say. And his daughter came up from Blackrock with an army of Anvilrage at her back and sat herself on the High Seat. We stand our posts. We wait."', '', 1, 1, '', 0, ''),
(9273, '"The king''s. Always the king''s." He doesn''t say which king.', '', 1, 1, '', 0, ''),
(9270, 'The warden''s face doesn''t move. Then he reaches behind him and hands you a shield. "Spare. From the gate stores. You''ve the patience of a warden. Wear it like one."', '', 1, 2, '', 0, ''),
(9271, '"Move along, citizen."', '', 1, 274, '', 0, ''),
(9280, '"Go in, if you must. The regent lets anyone in. It''s getting out again that worries me."', '', 1, 1, '', 0, ''),
(9292, '"Safe? There''s Anvilrage in the halls, cultists in the caves, gnomes starving in Tinker Town and every faction in the world sharpening knives. But the beer''s still good."', '', 1, 1, '', 0, ''),
(9290, 'Brodd snorts. "...Nobody''s asked that nicely in months." He hands you a red vial. "Here. Still can''t let you in. Sorry."', '', 1, 2, '', 0, ''),
(9291, '"Nobody passes." He doesn''t even blink.', '', 1, 274, '', 0, ''),
(9300, '"Welcome to the camp. Mind the fire, mind the rams, and don''t touch the stew. What do you need?"', '', 1, 1, '', 0, ''),
(9312, '"Holding the road east. Feeding everyone who holds it. Mostly the second one."', '', 1, 1, '', 0, ''),
(9313, '"It''s that good. There isn''t enough of it."', '', 1, 1, '', 0, ''),
(9310, 'Aldrena laughs. "Peace in camp. Rarer than gold." She gives you a vial from the camp stores. "Take it. You earned your bowl too, but you''re not getting it."', '', 1, 2, '', 0, ''),
(9311, '"Hmph. Leave it, I''ll sort it." She goes back to the stew.', '', 1, 274, '', 0, ''),
(9320, '"Road toll! One copper per leg, two per wheel, three per... hm. What are you, exactly?"', '', 1, 1, '', 0, ''),
(9332, '"There is now. Captain doesn''t know about it. The captain doesn''t need to know about everything."', '', 1, 1, '', 0, ''),
(9330, 'Olgar goes pale, then red. "No toll! Never was a toll! Here - here, have it all back." He empties his tin into your hands.', '', 1, 2, '', 0, ''),
(9331, '"Ha. Thought not." He folds his arms. "Pay or walk round."', '', 1, 274, '', 0, ''),
(9340, '"Far enough. Past this ridge is the road to Loch Modan, and it''s not for the green. Prove you''re not."', '', 1, 1, '', 0, ''),
(9352, '"Trouble that eats the green for breakfast. Clear Dun Morogh first. Then we''ll talk."', '', 1, 1, '', 0, ''),
(9350, 'Gilda nods, impressed despite herself. "Fine. You''ll need better than a stick when you go over." She hands you a light crossbow. "Bring it back with fewer bolts and more stories."', '', 1, 2, '', 0, ''),
(9351, '"Not yet." She goes back to watching the ridge.', '', 1, 274, '', 0, ''),
(9360, '"Shh! You''ll scare the fish. ...There aren''t any fish. But you might scare them anyway. What?"', '', 1, 1, '', 0, ''),
(9372, '"I''m WATCHING the lake. With a line in it. It''s called multitasking, gnomes taught me that."', '', 1, 1, '', 0, ''),
(9370, 'Up comes a little rusted coffer, tangled in the line. Borin whoops and splits the coins with you. "Best catch I''ve had all winter!"', '', 1, 2, '', 0, ''),
(9371, '"Hmph. Fish don''t like you." He settles back down.', '', 1, 274, '', 0, ''),
(9380, '"North gate post. Nobody''s come over that pass in a month except snow. What brings you?"', '', 1, 1, '', 0, ''),
(9392, '"Because everything in the hills knows we''re here, and everything in the hills is waiting. That''s my guess. I''d love to be wrong."', '', 1, 1, '', 0, ''),
(9390, 'Ragna lowers her weapon, grinning. "That''s the most fun I''ve had in a month." She tosses you a mace. "Keep it. I''ve two."', '', 1, 2, '', 0, ''),
(9391, '"Hah. Go on, then." She leans on her mace and watches the pass.', '', 1, 274, '', 0, ''),
(9400, '"Fever, foot-rot or orc arrow? ...None of them? Then you''re the healthiest soul in Menethil. What is it?"', '', 1, 1, '', 0, ''),
(9401, '"Wipe your boots. No, properly. Half my patients brought the bog in with them."', '', 1, 1, '', 0, ''),
(9412, '"Every season is busy in a swamp. The damp gets into the lungs, the leeches get into everything else, and the Dragonmaw send me the rest. I have not had a dry pair of socks since spring."', '', 1, 1, '', 0, ''),
(9413, '"The Intrepid. Went down in a storm with every hand. The fishermen say you can hear the captain still calling the roll on a still night. I say the fishermen drink."', '', 1, 1, '', 0, ''),
(9410, '"...Thursday, I think." They laugh, tiredly, and press a stoppered vial into your hand. "Here. You''ll need it out there more than I need the shelf space."', '', 1, 2, '', 0, ''),
(9411, '"Kindly meant, I''m sure. Now, if you''ll excuse me - the bog waits for no one."', '', 1, 274, '', 0, ''),
(9420, '"In you come, out of the wet! Hang your cloak by the fire - everyone''s cloak is by the fire."', '', 1, 1, '', 0, ''),
(9421, '"Mind the puddle by the door. It''s not a leak. It''s just Menethil."', '', 1, 1, '', 0, ''),
(9432, '"News? The road to Ironforge is open again, if you believe the mountaineers, and the Dragonmaw are still up in the hills, if you believe your eyes. Ships come in half empty. Folk drink to forget it."', '', 1, 1, '', 0, ''),
(9430, 'The whole common room joins the chorus, badly. "Now THAT''s worth a bowl." A heel of bread and a few coins come across the bar. "Come back and sing another."', '', 1, 2, '', 0, ''),
(9431, '"Hah. Maybe after a few more." The innkeeper is already turning to a sailor waving an empty mug.', '', 1, 274, '', 0, ''),
(9440, '"Aye? Make it quick - tide turns within the hour and I''ll not miss it for a landlubber."', '', 1, 1, '', 0, ''),
(9441, '"Mind the ropes. If you trip on a line on this dock, nobody''s fishing you out."', '', 1, 1, '', 0, ''),
(9452, '"Out? Few. The Intrepid going down put the fear in the crews, and the harbour master won''t clear anything past the point after dark. Some of the lads swear they''ve seen lights on the wreck."', '', 1, 1, '', 0, ''),
(9453, '"The Thandol Span, north - if it''s still standing. Arathi beyond. Nobody''s crossed it in months."', '', 1, 1, '', 0, ''),
(9450, 'They squint at the horizon, then at you, and laugh. "Ye''d make a fair hand." A coin spins across to you. "For luck. The sea takes the unlucky ones."', '', 1, 2, '', 0, ''),
(9451, '"Aye, well. Plenty of folk think they know the sea." They turn back to their ropes.', '', 1, 274, '', 0, ''),
(9460, '"Halt - oh. Not an orc. Good. What''s your business in Menethil?"', '', 1, 1, '', 0, ''),
(9461, '"Wet, aren''t I? Twelve hours on this wall and it hasn''t stopped once."', '', 1, 1, '', 0, ''),
(9472, '"The Dragonmaw hold the high ground east of the road, and they raid the supply carts at the ford. Murlocs on the shore, gnolls in the reeds, and something big eating the crocolisks. Stay on the road and keep your blade dry."', '', 1, 1, '', 0, ''),
(9470, 'For the first time, the sentry grins. "Ye''re all right." A red vial comes out of the guardhouse. "Watch stores. Don''t tell the sergeant."', '', 1, 2, '', 0, ''),
(9471, '"Nice try. Move along."', '', 1, 274, '', 0, ''),
(9480, '"Welcome! Half the shelves are empty and the other half are damp, but take a look."', '', 1, 1, '', 0, ''),
(9481, '"A customer! From the mountains, by the boots. Ironforge coin, I hope?"', '', 1, 1, '', 0, ''),
(9492, '"The supply carts from Dun Algaz get burned at the ford, and the ships won''t sail past the wreck. Everything I sell came in a rowing boat or on somebody''s back."', '', 1, 1, '', 0, ''),
(9490, '"Would you? Bless you." A few coins are counted into your hand. "That''s a down payment on the good word."', '', 1, 2, '', 0, ''),
(9491, '"Words are cheap. Carts aren''t." They go back to wringing out a bolt of cloth.', '', 1, 274, '', 0, ''),
(9500, '"Oh! A traveller. We don''t get many from the mountain road. What can I do for you?"', '', 1, 1, '', 0, ''),
(9501, '"Wet one today, isn''t it? They''re all wet ones. Can I help you?"', '', 1, 1, '', 0, ''),
(9512, '"Not well. The carts don''t come, the ships don''t go, and every night someone swears they hear a ship''s bell out on the water. But we''re harbour folk. We''ve weathered worse."', '', 1, 1, '', 0, ''),
(9510, 'They smile, properly, for the first time. "...Thank you. That means more than you know." They press a few coins on you and won''t hear no.', '', 1, 2, '', 0, ''),
(9511, '"Aye. Maybe." They don''t sound convinced, and the conversation drifts away.', '', 1, 274, '', 0, ''),
(9520, '"Another sword? Good. We need every one. State your business."', '', 1, 1, '', 0, ''),
(9521, '"You came up the Thandol road? Alone? Either you''re very good or very lucky."', '', 1, 1, '', 0, ''),
(9532, '"Bad. Witherbark in the eastern hills, Boulderfist in the west, the Syndicate squatting in Stromgarde, and the Shadowmages'' old horrors walking the ridges. This wall is all that''s left of Arathor, and some nights it doesn''t feel like much."', '', 1, 1, '', 0, ''),
(9533, '"Because if we give it up, there''s nothing between the highlands and the Wetlands but a bridge. Stromgarde fell. We won''t."', '', 1, 1, '', 0, ''),
(9530, 'For a moment the hard face cracks into something like a smile. A red vial is pressed into your hand. "From the stores. We''ve few enough to spare - but you''ll use it better than the rats will."', '', 1, 2, '', 0, ''),
(9531, '"I''ll manage, thank you." They turn back to the hills.', '', 1, 274, '', 0, ''),
(9540, '"A customer! Not many come up the hill who aren''t carrying a spear. What do you need?"', '', 1, 1, '', 0, ''),
(9541, '"Prices are high and I won''t apologise for it. Everything here came over the bridge on someone''s back."', '', 1, 1, '', 0, ''),
(9552, '"Carefully. The carts from Menethil come when they can, and the Syndicate takes their cut of half of them on the road. I sell to soldiers, who don''t haggle, because they might be dead tomorrow."', '', 1, 1, '', 0, ''),
(9550, '"Would you? Then here - for your trouble, in advance." A few coins come across the counter. "Don''t make me regret it."', '', 1, 2, '', 0, ''),
(9551, '"Kind of you. But I''ve heard that from adventurers before." They go back to their tally.', '', 1, 274, '', 0, ''),
(9560, '"Oh - you''re new. We don''t get many new faces that aren''t refugees. What can I do for you?"', '', 1, 1, '', 0, ''),
(9561, '"Mind the mud by the well. And the chickens. And the soldiers. Can I help you?"', '', 1, 1, '', 0, ''),
(9572, '"Everywhere. Stromgarde, when it fell. The farms, when the trolls came down. Dabyrie''s, Go''Shek, the Northfold. This hill was the only place that still had a wall."', '', 1, 1, '', 0, ''),
(9570, 'They look at you for a long moment, and then nod. "...Then the Light go with you." They press a few coins on you and won''t hear no.', '', 1, 2, '', 0, ''),
(9571, '"That''s what the last one said." They don''t say it unkindly, but they don''t say any more.', '', 1, 274, '', 0, ''),
(9580, '"Hold. Not Shadowforge, by the look of you - and not Horde. Good. What d''you want?"', '', 1, 1, '', 0, ''),
(9581, '"Eyes on the Cauldron, always. If the Emperor''s lot come up that ramp, we''ll want every hand."', '', 1, 1, '', 0, ''),
(9592, '"Leave? We were thrown out. The Emperor wanted his smiths to forge for Ragnaros. Some of us didn''t fancy a master made of fire. So here we are - on the doorstep, where Thaurissan can see us every morning."', '', 1, 1, '', 0, ''),
(9593, '"Slaves, golems, overseers, and fire. The quarry''s never stopped in two hundred years. Stay on the rim if you value your skin."', '', 1, 1, '', 0, ''),
(9590, 'The lookout grunts, which from a Dark Iron is high praise. A red vial is pushed into your hand. "From the stores. Don''t make a habit of needing it."', '', 1, 2, '', 0, ''),
(9591, '"Hmph. I''ll keep my own watch, thank you."', '', 1, 274, '', 0, ''),
(9600, '"Outsider! Mind the forge - it bites. Come to buy, or to gawp?"', '', 1, 1, '', 0, ''),
(9601, '"Thorium steel, the best in the world, and the Emperor can choke on it. What can the Brotherhood do for you?"', '', 1, 1, '', 0, ''),
(9612, '"It holds heat like nothing else and takes an edge like nothing else, and it''s only found down here, next to the hottest forge in the world. The Emperor wants all of it. We''d like him not to have it."', '', 1, 1, '', 0, ''),
(9610, 'The smith looks at you properly for the first time. "Huh. You''ve a feel for it." A few coins clink onto the anvil. "For your trouble. Come back when you want real steel."', '', 1, 2, '', 0, ''),
(9611, '"Leave the forge to the smiths, outsider." They turn back to the anvil.', '', 1, 274, '', 0, ''),
(9620, '"An outsider, up here? You''re either brave or lost. Which?"', '', 1, 1, '', 0, ''),
(9621, '"Mind your step. Half this camp''s built on cooling slag."', '', 1, 1, '', 0, ''),
(9632, '"Badly. It''s hot, the water tastes of sulphur, and the Emperor''s men would love to see us all in chains again. But it''s ours. Every stone of it."', '', 1, 1, '', 0, ''),
(9630, 'They look at you for a long time, and then nod once. "...Then good hunting." A few coins are pressed into your hand, gruffly.', '', 1, 2, '', 0, ''),
(9631, '"Words. We''ve had two hundred years of words." They turn away.', '', 1, 274, '', 0, ''),
(9640, '"Citizen." A glance at the Anvilrage across the hall, and his voice drops. "Mind yourself. The regent''s men are listening."', '', 1, 1, '', 0, ''),
(9641, '"Still at my post. The king put me here. Only the king moves me." He says it a little too loudly.', '', 1, 1, '', 0, ''),
(9652, '"Because if we walk, the Dark Irons take the posts, and then it''s their city for good. So we stand here, and we take the regent''s orders, and we wait for something to change."', '', 1, 1, '', 0, ''),
(9653, '"Stone. Solid stone, under a cloth behind the throne. Some say it was the Dark Irons. Some say it was the cultists. I say: somebody did it, and somebody''ll pay."', '', 1, 1, '', 0, ''),
(9650, 'The guard''s jaw unclenches, just a little. A red vial goes from his belt to your hand without either of you looking at it. "Didn''t get that from me."', '', 1, 2, '', 0, ''),
(9651, '"I''ll thank you not to stand so close. People talk." He turns back to the hall.', '', 1, 274, '', 0, ''),
(9660, '"Welcome, welcome - sit anywhere the Dark Irons aren''t. They don''t pay, you see. Regent''s men. Everything''s on the regent''s tab, and the regent never settles."', '', 1, 1, '', 0, ''),
(9661, '"A friendly face! Thank the Light. All I get these days are Anvilrage and gnomes who can''t afford a drink."', '', 1, 1, '', 0, ''),
(9672, '"Terrible. Half my regulars have gone to the hills or the Military Ward, and the other half drink to forget. The regent''s men drink to remember they won. Nobody''s happy."', '', 1, 1, '', 0, ''),
(9670, 'The whole room roars the last line. The innkeeper is wiping their eyes. "We haven''t sung that since - well." A plate of bread and a few coins come across the bar. "On the house. Come back and sing again."', '', 1, 2, '', 0, ''),
(9671, '"Hush, now - not in here, not with ears about." They move off quickly down the bar.', '', 1, 274, '', 0, ''),
(9680, '"Buying? Please be buying. The regency taxes everything twice and the Dark Irons pay in promises."', '', 1, 1, '', 0, ''),
(9681, '"Ah, a customer. Keep your voice down if you want a fair price - the regent''s clerks take a cut of every sale they see."', '', 1, 1, '', 0, ''),
(9692, '"A tenth for the regent, a tenth for the Anvilrage ''protecting'' my stall, a tenth for the senator who writes the receipt. What''s left I can keep, until they think of another tenth."', '', 1, 1, '', 0, ''),
(9690, '"You''re a decent sort, for an adventurer." A few coins are pressed into your palm. "That''s one tenth the regent won''t see."', '', 1, 2, '', 0, ''),
(9691, '"I''ve no time for jokers, friend. Buy something or move along."', '', 1, 274, '', 0, ''),
(9700, '"Ah - a visitor! We don''t get many who aren''t either Dark Irons or arrested. Do come in."', '', 1, 1, '', 0, ''),
(9701, '"These are dangerous times to be curious. Which is, of course, exactly when one must be."', '', 1, 1, '', 0, ''),
(9712, '"Legally? Nobody. The king is not dead, merely... indisposed in diamond, and a regent rules without the Council''s consent, which the old law does not allow. Practically? Whoever has the most hammers in the room."', '', 1, 1, '', 0, ''),
(9713, '"If we knew what was done to him, perhaps. Somebody cast that spell. Somebody knows how it''s undone."', '', 1, 1, '', 0, ''),
(9710, 'They beam like a teacher with a star pupil. "Remarkable. Quite remarkable." A small purse is produced from a drawer. "A scholarship. Spend it on something educational. Or not."', '', 1, 2, '', 0, ''),
(9711, '"Hm. Well. Perhaps a little more reading." They go back to their books.', '', 1, 274, '', 0, ''),
(9720, '"Oh! Hello! You''re not a Dark Iron, are you? No, too tall. Or too short. Wrong colour, anyway. Hello!"', '', 1, 1, '', 0, ''),
(9721, '"Welcome to Tinker Town - what''s left of it. Mind the scrap. Mind the refugees. Mind the scrap the refugees are sleeping on."', '', 1, 1, '', 0, ''),
(9732, '"Badly. Gnomeregan''s still poisoned, Ironforge never really wanted us, and now the regent wants us even less. The High Tinker has a plan to take Gnomeregan back. He always has a plan. Plans don''t feed anybody."', '', 1, 1, '', 0, ''),
(9730, '"Oh, splendid! Splendid!" They press a few coins and a little red vial on you. "From the store. Don''t tell the High Tinker - he''d want to make it explode."', '', 1, 2, '', 0, ''),
(9731, '"Hmph. Big folk never listen." They go back to their tinkering.', '', 1, 274, '', 0, ''),
(9740, '"Oh - you''re not one of the regent''s, are you? Good. Good. Sorry. Everyone''s jumpy these days."', '', 1, 1, '', 0, ''),
(9741, '"The halls aren''t what they were. But you''re welcome in them, I suppose. Somebody should be."', '', 1, 1, '', 0, ''),
(9752, '"The forge still burns. The beer still flows. The king''s a statue and a Dark Iron sits on his throne. We get by."', '', 1, 1, '', 0, ''),
(9750, 'They look at you for a long moment, and then their chin comes up. "...For Ironforge, then." A few coins are pressed into your hand.', '', 1, 2, '', 0, ''),
(9751, '"Easy to say. Harder to do." They walk on.', '', 1, 274, '', 0, ''),
(9760, '"Move along, citizen." Then, lower: "And keep clear of the Keep. Nobody who goes up there on business comes down the same."', '', 1, 1, '', 0, ''),
(9761, '"Still on the wall. The Lady sent the Royal Guard home and kept us. Says a lot about what she thinks of us."', '', 1, 1, '', 0, ''),
(9772, '"They don''t eat. They don''t sleep. They don''t talk to us. I stood a night watch with two of them once, and in the morning there was frost on me and none on them." He shivers.', '', 1, 1, '', 0, ''),
(9773, '"Highlord Fordragon? Resting, she says. Nobody''s seen him in a month. You don''t rest a month."', '', 1, 1, '', 0, ''),
(9770, 'The guard lets out a breath. A red vial goes from his belt to your hand. "For the road. You didn''t get it from me."', '', 1, 2, '', 0, ''),
(9771, '"I''ll thank you to move along. People are watching." He turns back to the street.', '', 1, 274, '', 0, ''),
(9780, '"Come in, come in, sit anywhere. Not by the window - the Lady''s men walk past and count who''s drinking."', '', 1, 1, '', 0, ''),
(9781, '"A new face! Thank the Light. Half my regulars have gone to the Brotherhood and the other half daren''t come out after dark."', '', 1, 1, '', 0, ''),
(9792, '"Rotten at the top and fraying everywhere else. The masons are picketing, the Stockade''s empty, there are dwarves sleeping in the alleys and the Lady''s soldiers have eyes like cats. Same as ever, really." They laugh, not happily.', '', 1, 1, '', 0, ''),
(9790, 'The innkeeper beams. "Haven''t heard that in this room since the rebuilding." A plate of bread and a few coins come across the bar. "On the house. Come back."', '', 1, 2, '', 0, ''),
(9791, '"Hush, now. Not in here." They move off down the bar.', '', 1, 274, '', 0, ''),
(9800, '"Buying? Please be buying. The Lady''s tax-men take a third and the Brotherhood takes the rest off the carts."', '', 1, 1, '', 0, ''),
(9801, '"Ah, a customer. Keep your voice down when you haggle - the Lord Protector''s clerks get a cut of every sale they hear."', '', 1, 1, '', 0, ''),
(9812, '"The roads are Defias country, the harbour''s full of wreckers, and the Lady has doubled the tolls. I sell to the people who can still pay, which is fewer every week."', '', 1, 1, '', 0, ''),
(9810, '"You''re a decent sort." A few coins are pressed into your palm. "That''s the Lady''s third, and she''s not getting it."', '', 1, 2, '', 0, ''),
(9811, '"I''ve no time for jokers. Buy something or move along."', '', 1, 274, '', 0, ''),
(9820, '"Welcome, friend. These are hard days for anyone who asks questions in Stormwind. Ask yours quietly."', '', 1, 1, '', 0, ''),
(9821, '"Ah - a visitor who isn''t wearing black and gold. Come in, come in."', '', 1, 1, '', 0, ''),
(9832, '"The king, by law, and he is at war in the north. His regent, by law, and no one has seen him in a month. In practice? A woman the House of Nobles never confirmed, and who - forgive me - does not cast a shadow quite as a woman should."', '', 1, 1, '', 0, ''),
(9833, '"They rebuilt this city after the orcs burned it, and the Nobles voted not to pay them. It was a crime then. It is a disaster now - half of them have joined the Defias."', '', 1, 1, '', 0, ''),
(9830, 'They smile like a teacher with a star pupil. A small purse is produced from a drawer. "For your studies. Or for your boots. The road is long."', '', 1, 2, '', 0, ''),
(9831, '"Hm. Well. Perhaps a little more reading." They go back to their books.', '', 1, 274, '', 0, ''),
(9840, '"Another one from the mountain? No? Well, you''re welcome anyway. Half the Dwarven District''s sleeping on the floor these days."', '', 1, 1, '', 0, ''),
(9841, '"Ach, a friendly face. We''ve had a lot of the other kind, lately - from home and from up the hill both."', '', 1, 1, '', 0, ''),
(9852, '"Ironforge. The king''s a statue and Moira Thaurissan sits his throne, and when the Anvilrage came for the Mountaineer companies, folk ran. South, mostly. Here. And found the same rot on Stormwind''s throne, just politer."', '', 1, 1, '', 0, ''),
(9850, '"Ha! Good." A few coins and a little red vial come your way. "From the store. For the road."', '', 1, 2, '', 0, ''),
(9851, '"Hmph. Big folk. Never listen." They turn back to their pipe.', '', 1, 274, '', 0, ''),
(9860, '"Oh - you''re not one of the Lady''s, are you? Good. Sorry. Everyone''s jumpy."', '', 1, 1, '', 0, ''),
(9861, '"Stormwind''s not what it was. But you''re welcome in it, I suppose. Somebody should be."', '', 1, 1, '', 0, ''),
(9872, '"The king''s away, the Lady''s on the throne, the masons are on the street and the Defias are in the hills. We get by. Mostly."', '', 1, 1, '', 0, ''),
(9870, 'They look at you a long moment, and their chin comes up. "...For Stormwind, then." A few coins are pressed into your hand.', '', 1, 2, '', 0, ''),
(9871, '"Easy to say." They walk on.', '', 1, 274, '', 0, ''),
(9880, '"Welcome to the Lion''s Pride! Sit, sit. Not many travellers on the road these days - not many who arrive with their purse, anyway."', '', 1, 1, '', 0, ''),
(9881, '"Ah, a fresh face. Supper''s stew, and stew''s all there is. The Brotherhood took the last cartload of everything else."', '', 1, 1, '', 0, ''),
(9892, '"Frightened. The Defias rob the roads, Hogger''s gnolls raid the western farms, and the city sends nobody. The Marshal does what he can with four men and a horse."', '', 1, 1, '', 0, ''),
(9890, 'The innkeeper laughs and slaps the bar. "Haven''t had a night like that since the harvest fair." A bowl of stew and a few coins come your way. "On the house."', '', 1, 2, '', 0, ''),
(9891, '"Not tonight, friend. Not with the Brotherhood''s ears about." They move off.', '', 1, 274, '', 0, ''),
(9900, '"Buying, I hope? The Defias took my last two carts, and the city won''t send an escort."', '', 1, 1, '', 0, ''),
(9901, '"Welcome, welcome. Prices are up - blame the Brotherhood. Everything that comes up the road comes up short."', '', 1, 1, '', 0, ''),
(9912, '"Red bandanas at every bend. They call it a toll. I call it theft. The Marshal calls it ''under review''."', '', 1, 1, '', 0, ''),
(9910, '"You''re all right." A few coins are pressed into your palm. "Don''t spend them on the road."', '', 1, 2, '', 0, ''),
(9911, '"I''ve no time for jokers. Buy or move along."', '', 1, 274, '', 0, ''),
(9920, '"Citizen. Mind the roads - the Defias have got bolder since the city stopped sending patrols."', '', 1, 1, '', 0, ''),
(9921, '"Four of us to hold the whole valley. You don''t happen to want a job, do you?"', '', 1, 1, '', 0, ''),
(9932, '"The Lady sends word the matter is ''in hand''. The Lady sends nobody. The Marshal writes to the Keep every week. The Keep never writes back."', '', 1, 1, '', 0, ''),
(9930, 'They grin, the first in a while by the look of it. A red vial comes your way. "From the garrison chest. Don''t tell the quartermaster."', '', 1, 2, '', 0, ''),
(9931, '"I''ve no time for this. Move along."', '', 1, 274, '', 0, ''),
(9940, '"Welcome to Northshire, traveller. You look tired. Rest a while - the Abbey turns no one away."', '', 1, 1, '', 0, ''),
(9941, '"Peace, friend. We pray for the city, these days. It needs it more than the forest does."', '', 1, 1, '', 0, ''),
(9952, '"The Archbishop writes that the court is... not well. That is all he writes, and the Archbishop is a man who usually writes a great deal."', '', 1, 1, '', 0, ''),
(9950, 'They bless you, and press a small purse into your hand. "For the road. The Light knows it is long."', '', 1, 2, '', 0, ''),
(9951, '"Perhaps another time." They return to their prayers.', '', 1, 274, '', 0, ''),
(9960, '"Oh - you''re not Defias, are you? No. Too clean. Sorry - everyone''s nervous."', '', 1, 1, '', 0, ''),
(9961, '"Elwynn''s a fine forest, when it''s quiet. It hasn''t been quiet for a while."', '', 1, 1, '', 0, ''),
(9972, '"Gnolls in the west, Defias on the roads, kobolds in the mines and murlocs in the lakes. And Stormwind sits up there behind its walls and does nothing."', '', 1, 1, '', 0, ''),
(9970, 'They look at you a long moment, and nod. "...All right. All right, then." A few coins are pressed into your hand.', '', 1, 2, '', 0, ''),
(9971, '"Easy to say." They walk on.', '', 1, 274, '', 0, ''),
(9980, '"Another one with frost-nip? No? Good - I''ve enough of those. What is it, then?"', '', 1, 1, '', 0, ''),
(9981, '"Hold still, let me look at you. Hm. You''ll live. Most folk who come through here do."', '', 1, 1, '', 0, ''),
(9992, '"Troll arrows, trogg bites, and dwarves who think the cold can''t touch them. It can. Half my work is pulling toes back from the brink."', '', 1, 1, '', 0, ''),
(9990, '"...Aye. Aye, I should." They sit, and for a moment don''t say anything. Then they press a small red vial into your hand. "Here. You''ve a kind eye. Use that before you need me."', '', 1, 2, '', 0, ''),
(9991, '"Kind of you, but I''ve work to do." They''re already turning back to their shelves.', '', 1, 274, '', 0, ''),
(10000, '"Welcome in, welcome in! Shut the door behind you - you''re letting the winter in."', '', 1, 1, '', 0, ''),
(10001, '"Mind the floor, it''s just been swept. What''ll it be?"', '', 1, 1, '', 0, ''),
(10012, '"News? Same as ever - the king''s shut the gates, the trolls are bold and the troggs are bolder. But folk still want feeding, so here I stand."', '', 1, 1, '', 0, ''),
(10010, 'That gets a laugh from the whole room. "Now that''s worth paying for." A heel of bread and a few coins are pushed across the bar. "Come back and tell another."', '', 1, 2, '', 0, ''),
(10011, '"Hm. Heard that one before, friend." The smile stays polite, but the bread stays where it is.', '', 1, 274, '', 0, ''),
(10020, '"You have the look of someone who''s been doing something useful. That makes a change. Speak."', '', 1, 1, '', 0, ''),
(10021, '"Ah. Another adventurer. Well? I haven''t all day."', '', 1, 1, '', 0, ''),
(10032, '"Reports. Requisitions. Reports about requisitions. The valleys are in a state and everyone wants me to fix it with a quill."', '', 1, 1, '', 0, ''),
(10030, 'They look at you properly for the first time. "...Yes. Yes, you''re right, and it''s shameful nobody else has said it." A purse is counted out. "For the road. Officially."', '', 1, 2, '', 0, ''),
(10031, '"Very good. I''ll be sure to file that." They''ve already gone back to their papers.', '', 1, 274, '', 0, ''),
(10040, '"Keep moving, citizen - unless you''ve something to report?"', '', 1, 1, '', 0, ''),
(10041, '"Cold enough for you? I''ve been stood here so long I''ve forgotten what my feet look like."', '', 1, 1, '', 0, ''),
(10052, '"Trolls in the hills, troggs in the holes, and wolves anywhere in between. And Ironforge''s shut tight, so nobody''s coming to help. Stay sharp."', '', 1, 1, '', 0, ''),
(10050, 'They snort - and then grin. "Fair. Fair enough." A small red vial comes out of their pack. "Don''t tell the captain. And don''t waste it."', '', 1, 2, '', 0, ''),
(10051, '"Ha! Nice try." They settle back to their watch. "Off with you."', '', 1, 274, '', 0, ''),
(10060, '"Ah, a thirsty face! Or a curious one. Either''s welcome at a brewer''s door."', '', 1, 1, '', 0, ''),
(10061, '"Careful where you step - that barrel''s still working. Taste?"', '', 1, 1, '', 0, ''),
(10072, '"Winter stout. Dark as a mine, strong as a ram, and it''ll keep you warm on a night out on the Pass. Or so I''m told - I never leave the cellar."', '', 1, 1, '', 0, ''),
(10070, '"Ha! Right you are!" A slap on the back nearly knocks you over, and coins jingle into your hand. "You''ve a brewer''s tongue in your head. Remember me when you''re famous."', '', 1, 2, '', 0, ''),
(10071, '"Hmph. Everyone''s a critic." The cup is taken back rather pointedly.', '', 1, 274, '', 0, ''),
(10080, '"Mind the sparks. You want something mended, or are you just enjoying the heat?"', '', 1, 1, '', 0, ''),
(10081, '"Hah - another one come to stand by the forge and thaw out. Go on, then. What''s your business?"', '', 1, 1, '', 0, ''),
(10092, '"Spearheads for the Watch. Hundreds of the things. You''d think the trolls were made of them, the rate they go."', '', 1, 1, '', 0, ''),
(10090, '"Now there''s someone who knows their business." The smith wipes their hands and digs out a few coins. "For your trouble. Don''t spend it all on ale."', '', 1, 2, '', 0, ''),
(10091, '"Not quite." The smith takes back the work with a shake of the head. "Leave it to the professionals."', '', 1, 274, '', 0, ''),
(10100, '"Easy now - he kicks. What brings you out to the pens?"', '', 1, 1, '', 0, ''),
(10101, '"Mind your fingers near that one. Can I help you?"', '', 1, 1, '', 0, ''),
(10112, '"Skittish. Something''s been prowling the fences at night - wolves, maybe, or worse. The rams know before we do."', '', 1, 1, '', 0, ''),
(10110, 'The ram settles, and the rancher lets out a long breath. "Well, I''ll be. Here - you''ve earned this." A few coins and a nod of real respect.', '', 1, 2, '', 0, ''),
(10111, 'The ram butts you flat on your back in the snow. "...Maybe leave it to me," says the rancher, trying not to laugh.', '', 1, 274, '', 0, ''),
(10120, '"Watch your head - low ceilings and loose rock round here. What do you want?"', '', 1, 1, '', 0, ''),
(10121, '"Hah! A surface-dweller, come to see real work. Go on, then."', '', 1, 1, '', 0, ''),
(10132, '"Slow. Troggs in the lower tunnels, and the cold cracks the rock wrong. But there''s good stone in these hills, if you know where to look."', '', 1, 1, '', 0, ''),
(10130, '"By my beard - you''re right!" They clap you on the shoulder. "Here. A finder''s share. Don''t tell the foreman."', '', 1, 2, '', 0, ''),
(10131, '"Hah! Just rock, that. Stick to the surface, friend."', '', 1, 274, '', 0, ''),
(10140, '"Oh! Hello! Don''t touch that. Or that. Actually, don''t touch anything. How can I help?"', '', 1, 1, '', 0, ''),
(10141, '"Hm? Oh, sorry, I was thinking about gears. I''m always thinking about gears. What is it?"', '', 1, 1, '', 0, ''),
(10152, '"We don''t talk about it. Well, we do, constantly, but not to strangers. Radiation, troggs, and a very bad decision. Next question."', '', 1, 1, '', 0, ''),
(10150, '"Of course! A reversed coil! Why didn''t I see that?" The gnome beams up at you and presses some coins into your hand. "A consultant''s fee! Very official."', '', 1, 2, '', 0, ''),
(10151, 'There''s a small bang and a puff of smoke. The gnome looks at you, eyebrows singed. "...I''ll take it from here."', '', 1, 274, '', 0, ''),
(10160, '"Welcome, welcome! Stock''s thin - nothing''s come up the roads in weeks - but what I have, I''ll sell."', '', 1, 1, '', 0, ''),
(10161, '"A customer! Or a browser. Either way, mind the empty crates."', '', 1, 1, '', 0, ''),
(10172, '"Gates shut, roads dangerous, carts turned back at the trogg line. I''ve sold the best of it already, and I''ve had offers for the shelves."', '', 1, 1, '', 0, ''),
(10170, '"Well now. That''s good business." A few coins slide across the counter. "Consider it an investment. In you."', '', 1, 2, '', 0, ''),
(10171, '"Ha! You''re a haggler, I''ll give you that. But no." They tap the counter. "Prices are prices, friend."', '', 1, 274, '', 0, ''),
(10180, '"Oh! Hello. Not many strangers come by these days. What can I do for you?"', '', 1, 1, '', 0, ''),
(10181, '"Cold one today, isn''t it? They''re all cold ones. Can I help you with something?"', '', 1, 1, '', 0, ''),
(10192, '"Not well. With the gates shut and the roads dangerous, nobody''s getting what they need. But folk up here are tough - we''ve lived through worse."', '', 1, 1, '', 0, ''),
(10190, 'They smile, properly, for the first time. "...Thank you. That means more than you know." They press a few coins on you and won''t hear no.', '', 1, 2, '', 0, ''),
(10191, '"Aye. Maybe." They don''t sound convinced, and the conversation drifts away.', '', 1, 274, '', 0, ''),
(3101, 'Three kobolds crouch round a guttering candle stub wedged on a rock, shielding it from the wind with their paws. The biggest - a geomancer with a scorched snout - leaps up and waves a little knife at you. "You no take candle!"', '', 0, 5, '', 0, ''),
(3102, '"Everybody take candle!" the geomancer wails. "Stomp-folk take candle. Trogg take candle. Dark Iron take candle, and boom-powder, by big wall of water! Kobold see!"', '', 1, 14, '', 0, ''),
(3103, 'The kobolds look at each other, squeak in alarm, and snatch up the candle. In a moment they''re gone into a crack in the rocks, still arguing about who gets to carry it.', '', 0, 0, '', 0, '0'),
(3104, '"Kobold not stupid!" The geomancer''s snout flares. The others draw their knives.', '', 1, 15, '', 0, ''),
(3105, 'The flame shivers. The kobolds shriek as one - the geomancer scoops up the candle in both paws and they flee, tails between their legs.', '', 0, 0, '', 0, '0'),
(3106, 'Every dead stub along the wall flares alight at once. The kobolds stare, then drop flat on their bellies. "Candle-maker," the geomancer whispers. "Big candle-maker." They will not get up until you''ve gone.', '', 0, 2, '', 0, ''),
(3108, 'You set the fat white miner''s candle on the rock. The kobolds go very still. Then the geomancer creeps forward, sniffs it, and hugs it to his chest. "You good stomp-folk," he decides, and they scurry off with their treasure.', '', 0, 0, '', 0, '0'),
(3109, 'The geomancer squints at you for a long moment. "...You promise?" You promise. He sits back down, curls round his candle, and pointedly ignores you. The others follow suit.', '', 1, 24, '', 0, ''),
(3201, 'Two ogres plant themselves in the middle of the road. The bigger one thumps a club as long as you are into his palm. "You. Small thing. Dis Mo''grosh road. Pay Chok''sul toll, or Gor''mul smash."', '', 1, 25, '', 0, ''),
(3202, '"Toll is..." The ogre counts on his fingers. He loses his place, glares at his hand, and starts again. The other ogre tries to help and they both lose count. "...Many shiny," Gor''mul decides.', '', 1, 6, 'cant_count', 0, ''),
(3204, '"Gor''mul getting angry," Gor''mul announces, in case you hadn''t noticed.', '', 1, 14, '', -1, ''),
(3205, 'The ogres look at each other. "Chok''sul greedy," the smaller one rumbles. "Chok''sul take toll and not share." They stomp off up the road, muttering, to have words with their boss.', '', 0, 0, '', 0, '0'),
(3206, '"You lie!" Gor''mul roars. "Chok''sul not here today! Smash!"', '', 1, 15, '', 0, ''),
(3207, 'You count their takings with great ceremony - two coppers, a button, a lot of pebbles - and announce a staggering fortune. The ogres are overjoyed. Gor''mul pats you on the head, hard, and they lumber off to tell Chok''sul how rich they are.', '', 0, 0, '', 0, '0'),
(3208, 'You hold out the sack. Gor''mul tips it into his palm - a heap of glittering mica and polished river stones - and his eyes go wide. "Shiny," he breathes. "So much shiny." They forget you entirely.', '', 0, 0, '', 0, '0'),
(3290, '"Enough talk!" Gor''mul hefts his club. "Gor''mul take toll from small thing''s pockets. After smash."', '', 1, 15, '', 0, ''),
(3401, 'Two Dark Iron dwarves kneel over a crate stamped with the anvil of Thaurissan, packing black powder into iron casings. One looks up, hand going to his hammer. "Bronzebeard dog. Walk on, if ye value yer knees."', '', 1, 14, '', 0, ''),
(3402, 'While they glare at you, you take a good look at the crate. The fuse cords coiled on top are dark and limp - soaked through. Whoever stored them did it next to the water.', '', 0, 0, 'wet_fuse', 0, ''),
(3403, '"Oi! Eyes off the goods!" The sapper slams the lid shut.', '', 1, 274, '', -1, ''),
(3404, 'The insurgent goes pale under the soot. "We''re - aye, we know, we know. Tell the Emperor it''ll be done." They grab their tools and hurry off towards the hills, leaving the crate behind.', '', 0, 0, '', 0, '0'),
(3405, '"Ye think we''re fools?" The insurgent rises, hammer in hand. "No witnesses."', '', 1, 15, '', 0, ''),
(3406, 'By the time they''ve finished arguing about who forgot the matches, every fuse cord is in your pack. The sapper reaches into the crate, freezes, and swears. They stare at each other, then at you - and decide they''d rather explain this to their masters than to you.', '', 0, 0, '', 0, '0'),
(3407, 'The sapper lifts a cord, and water drips off the end. He looks at the insurgent. The insurgent looks at him. "YOU were meant to keep them dry!" They are still shouting at each other as they storm off, leaving the useless crate behind.', '', 0, 0, '', 0, '0'),
(3408, 'The insurgent reads the orders, then the Mountaineers'' seal stamped across them, and goes grey. "They know," he breathes. "They know everything." The two of them are gone before you can say another word.', '', 0, 0, '', 0, '0'),
(3490, '"Enough." The insurgent stands, and the sapper hefts a lit casing. "Should''ve walked on."', '', 1, 15, '', 0, ''),
(5101, 'A murloc the size of a rain barrel squats in the reeds, cramming fish into its mouth as fast as two smaller ones can carry them. They are running out of fish. It looks at your pack, then at you, in that order. / "Mrrglgl?"', '', 0, 0, '', 0, ''),
(5102, 'The foragers never come within arm''s reach. They toss each fish from as far away as they can and flinch when it lands. One of them is missing two fingers. Whatever drops in front of the big one, it eats - a fish, a crab, a boot - and whoever is nearest when the fish run out is going to have a very bad afternoon.', '', 0, 0, 'feeders', 0, ''),
(5103, 'The loaf sails over the reeds and lands with a splash. The big murloc is after it before the ripples spread, bulling through the mud like a cart with a broken axle. The two foragers look at each other, look at you - and run the other way, as fast as their flippers will take them.', '', 0, 0, '', 0, '0'),
(5104, 'The big murloc stops chewing. Its eyes roll toward you, one at a time. It has decided something.', '', 1, 15, '', -1, ''),
(5105, 'You gargle. It is, by any standard, a terrible noise - and the big murloc goes perfectly still. Then it gargles back, lower, and the foragers stare at you with something like worship. Whatever you just said, it was either a blessing or a recipe. The big one heaves itself up and wades off down the channel, and the small ones follow it at a careful distance.', '', 0, 0, '', 0, '0'),
(5106, 'The basket slides to a stop against its belly. It sniffs. It has never smelled smoke on a fish before. It eats the first one whole, then the second one slowly, then sits down in the mud with the basket in its lap and an expression of perfect peace. The foragers creep away on tiptoe. You do the same.', '', 0, 0, '', 0, ''),
(5107, 'The big murloc turns its whole body to look at the foragers. The foragers show their empty claws, frantic. It does not believe them. They bolt into the reeds with the big one crashing after them, and the noise goes on for some time, getting further away.', '', 0, 0, '', 0, '0'),
(5108, 'A tongue of flame licks across the fish in its claws. The skin crackles. The big murloc looks at the fish. It sniffs. It takes one small, suspicious bite - and its eyes go wide. It holds the next fish out toward you, politely, and waits. You cook that one too. By the fifth, it is your friend for life, and too full to move.', '', 0, 0, '', 0, ''),
(5190, 'The last fish is gone. The big murloc looks at the foragers. The foragers point at you.', '', 1, 15, '', 0, ''),
(5601, 'Three gnolls crouch round a boar haunch, dividing it with a great deal of snarling. The big one does the cutting. The two mongrels watch every slice and get, somehow, the gristle every time. One of them spots you and yips. / "No share! No share for pink-skin!"', '', 1, 14, '', 0, ''),
(5602, 'The big one cuts, hands out a scrap, cuts again - and every third slice goes not into a paw but down beside his leg. He''s sitting on the best of it. The mongrels are so busy watching his knife that they''ve never once looked at his knee.', '', 0, 0, 'cheat', 0, ''),
(5603, 'The mongrels look at the big one''s knee. The big one looks at you with pure hatred. Then one mongrel lunges for the liver, the other for the big one''s ear, and the three of them go rolling through the fire in a ball of fur and teeth. By the time it breaks up they are all running in different directions, each with a piece of boar and none of them interested in you.', '', 0, 0, '', 0, '0'),
(5604, 'You walk into the middle of them, pick up the haunch, and take a bite. Nobody moves. The big one''s lip curls - and then, slowly, his ears go flat. He knows what a bigger dog looks like. The three of them back off into the reeds, whining, and leave you the camp.', '', 0, 0, '', 0, '0'),
(5605, 'The big one''s hackles go up, and the mongrels'' follow. / "Pink-skin thinks gnoll is stupid!"', '', 1, 15, '', -1, ''),
(5606, 'It''s a good howl. All three gnolls freeze, ears swivelling. The big one stuffs the liver into his mouth - whole - and the mongrels see it, and for a moment it could go either way. Then fear of the Alpha wins. They scatter, leaving the haunch in the dirt.', '', 0, 0, '', 0, '0'),
(5607, 'The mongrels see the totem first and drop flat on their bellies. The big one stares at it, then at you, working it out: whoever carries that carries the Alpha''s word. He pushes the whole haunch toward you with one paw, very carefully, and backs away with his tail between his legs.', '', 0, 0, '', 0, '0'),
(5690, '"ENOUGH TALK!" The big one kicks the haunch aside and comes up with a spear in his paw. "Pink-skin is share now!"', '', 1, 15, '', 0, ''),
(5801, 'Where the tunnel road comes out above the marsh, three Dragonmaw orcs have rolled a cart across it and planted a banner. The big one in the scale coat doesn''t even stand up. / "Road''s shut. This is Dragonmaw land now, top to bottom. Turn round and walk back into your hole - or leave your boots and your blood here. I''ve no preference."', '', 1, 274, '', 0, ''),
(5802, '"Whose order?" He spits. "Nek''rosh''s. The Chieftain. He holds the high camp, and every road through this swamp answers to him - and I answer for this one. Ma''ruk Wyrmscale. Remember it. You''ll be saying it to the worms."', '', 1, 0, 'nekrosh', 0, ''),
(5803, 'Ma''ruk is on his feet before you finish. "Late? I sent word two days - " He stops. Looks at the scout. The scout looks at the ground. "You never went." He rounds on the scout with a roar, and in the shouting that follows nobody is watching the road at all. Somewhere in it you hear: "- to the high camp, ALL of us, and you''ll tell him yourself!" They leave the cart where it stands.', '', 0, 0, '', 0, '0'),
(5804, 'Ma''ruk laughs, short and ugly, and picks up his axe. "Clever. I''ll have that tongue for my belt."', '', 1, 11, '', -1, ''),
(5805, 'The scout is already looking back up the tunnel. The grunt has gone grey. Ma''ruk holds your eye for a long moment - and you don''t blink. "...Three of us," he says at last, "to hold a ditch against a column. Nek''rosh can hold it himself." He pulls up the banner, and they go, not quite running.', '', 0, 0, '', 0, '0'),
(5806, 'The scout is bored. Ma''ruk is enjoying himself. But the grunt, the young one at the back, keeps glancing at the goat track that climbs away over the ridge - and every time Ma''ruk raises his voice, he flinches. He doesn''t want to be here. He wants someone to give him a reason to go.', '', 0, 0, 'grunt_scared', 0, ''),
(5807, 'Three orcs, three axes, one cart. If there''s more to see, Ma''ruk''s glare doesn''t give you time to see it.', '', 0, 0, '', -1, ''),
(5808, 'The grunt looks at you. He looks at Ma''ruk''s back. Then he sets his axe down on the cart, very quietly, and walks up the goat track without a word. He doesn''t look round. It takes Ma''ruk a moment to notice. / "...Where''s he going? WHERE ARE YOU GOING?"', '', 0, 0, '', 0, '3'),
(5890, '"I''m done listening." Ma''ruk rolls his shoulders and steps round the cart. "Kill it."', '', 1, 15, '', 0, ''),
(6001, 'Two men stand at the edge of the surf, grey as driftwood, water running out of their coats and never stopping. The taller one holds a sodden roll of paper and reads from it in a voice like a hull scraping sand. The other stands at his shoulder, waiting. Nobody answers. / "...Abel Marsh. Abel Marsh! - Corwin Tate. Corwin Tate!..."', '', 0, 0, '', 0, ''),
(6002, 'It''s a muster roll. He calls each name twice, waits for the answer, and when none comes he makes a mark and goes on - and when he reaches the bottom, he turns the paper over and starts again from the top. He has been doing this since the ship went down. He is the captain, and he will not leave his post until every hand is accounted for. None of them ever will be.', '', 0, 0, 'roll', 0, ''),
(6003, 'The captain''s head comes up. "...All hands?" / "Aye, Captain. Mustered on the beach. Every one." / For a long moment he only looks at you, and the water runs out of his sleeves. Then he rolls up the paper, carefully, and hands it to the mate. "Then we''re done here, Mister Snellig." / "Aye, sir." The tide comes in over their boots, and their knees, and when it draws back there is only sand.', '', 1, 0, '', 0, '0'),
(6004, 'The mate''s head turns toward you with a sound like a wet rope. "The Captain is calling the roll," he says. "You will not interrupt the Captain."', '', 2, 274, '', -1, ''),
(6005, 'The words carry further than they should over the water. The captain stops reading. He stands very straight, as if someone had finally come aboard to relieve him. "...I had the watch," he says. "I had the watch, and I lost them." / "You kept it, sir," says the mate. "Longer than anyone." / The captain nods, slowly. He lets the roll fall, and the surf takes it - and then, gently, them.', '', 1, 0, '', 0, '0'),
(6006, 'Eight strokes, in four pairs. On the last one the captain lowers the roll. The mate takes off his hat. "Eight bells, sir," he says. "End of the watch." / "So it is, Mister Snellig. So it is." The captain looks out at the wreck one last time, and something in his drowned face comes loose and lets go. "Dismiss the hands." / The next wave goes through them like smoke.', '', 1, 0, '', 0, '0'),
(6090, 'The roll crumples in the captain''s fist. "MUTINY," he says, to nobody, to everybody. "Mister Snellig - repel boarders."', '', 1, 15, '', 0, ''),
(6101, 'An old gnoll sits on a heap of bones as high as your chest, gnawing one. A brute and a narrow-eyed trapper stand either side of the track. The old one doesn''t stop gnawing to speak. / "Road is Gnawbone''s. Everybody pay. Pay one bone." He looks you up and down. "You have many bones. Pick."', '', 0, 0, '', 0, ''),
(6102, '"BIG bone." He holds up the one he''s working on - a thighbone as long as your arm, grooved by years of teeth. "Bigger than this. Gnawbone has all the small bones. Gnawbone is tired of small bones." The brute nods as though this were wisdom. The heap, you notice, is nearly all cracked and split, and the old gnoll keeps shifting his seat as if it bothered him.', '', 1, 0, 'bigbone', 0, ''),
(6103, 'The old gnoll stops gnawing. He looks down. He pulls the thighbone out from under himself and turns it over, and there, where you pointed, is a hairline crack. The brute backs away from the heap. The trapper makes a sign against bad luck. "...How long?" whispers Gnawbone. "How long has Gnawbone sat on the curse?" They are gone into the marsh before you can answer, and they leave every bone behind.', '', 1, 0, '', 0, '0'),
(6104, 'The old gnoll''s eyes narrow, and he takes the bone out of his mouth to point it at you. "Gnawbone asks for bone. Gets talk. Talk is not bone."', '', 1, 14, '', -1, ''),
(6105, 'The brute grins and plants his elbow on a stump. It takes a long time, and it is not pretty, and at the end of it the back of his paw hits the wood. Silence. Then the old gnoll wheezes - laughing - and waves a bone at the road. "Strong bones. Keep them. Go." The brute is still staring at his own arm as you walk past.', '', 1, 11, '', 0, ''),
(6106, 'You hold it up with both hands, like an offering. The old gnoll takes it, sniffs it, turns it over. "...Good bone," he admits. "Old. Well gnawed." He adds it to the heap - a hand''s width from where it was a moment ago - and waves you through. The trapper watches you go with a long, thoughtful look, and says nothing.', '', 1, 273, '', 0, ''),
(6107, 'You lay it across the track. It is longer than he is. The old gnoll climbs down off his heap - his knees crack - and walks the length of it, touching it with one claw. When he looks up his eyes are wet. "Gnawbone waited whole life for this bone." He drags it away himself and will not let the brute help, and the road stands empty behind him.', '', 1, 0, '', 0, '0'),
(6190, '"No bone." The old gnoll spits out a splinter and stands up on his heap. "Then Gnawbone takes one. Hold it still."', '', 1, 15, '', 0, ''),
(6401, 'The heart of the Dragonmaw camp: a hide tent with the front rolled up, a table made of a door, and three orcs bent over a map held down with knives. The one at the head of it wears a necklace of dwarven rank badges. He hasn''t seen you yet. / "- the supply road, at dusk, when the carts bunch at the ford. Burn the lot. Menethil starves by the new moon."', '', 1, 0, '', 0, ''),
(6402, 'From the shadow of the next tent you hear all of it. The plan is the supply road at dusk. The seer in the black hood thinks it''s too soon and says so, twice. And the centurion - the one with the good sword - agrees with the chieftain every time, a little too fast, and keeps one hand near the map as if it were already his. He was not in camp last night. The seer knows it. The chieftain doesn''t.', '', 0, 0, 'plan', 0, ''),
(6403, 'A tent peg turns under your boot. Three heads come up from the map.', '', 0, 0, '', -1, ''),
(6404, 'The chieftain turns his head, slowly, to look at the centurion. The centurion''s hand is on his sword before he can stop it - and that is all the answer anyone needs. The table goes over. The seer steps back out of the way with the look of someone who has been waiting a long time for this.', '', 1, 15, '', 0, ''),
(6405, '"A spy." The chieftain straightens, and he is a good deal bigger standing up. "In my own tent. Somebody will lose skin for this - after you."', '', 1, 25, '', -1, ''),
(6406, 'Nobody speaks. The seer is the first to move: he pulls his knife out of the map and begins to roll it up. "I said it was too soon," he remarks, to the air. The chieftain''s jaw works. He looks at the marsh, at the road to the pass, at you. "...Strike the camp," he says, as though the words were being pulled out of him with tongs. "We go north. This swamp isn''t worth the men."', '', 1, 0, '', 0, '0'),
(6407, 'The centurion starts forward and the chieftain stops him with one arm. "No. It asked for me." He takes his axe down from the tent pole and shrugs off his cloak. "Stay out of it, both of you. When I''ve finished, hang what''s left on the road where the dwarves can see it." The other two step back.', '', 1, 0, '', 0, '2,3'),
(6408, 'You are a hundred paces down the hill when the shouting turns into steel on steel. By the time it stops, there is smoke rising from the high camp, and a line of Dragonmaw filing north out of it without a banner. Whoever won, there are too few of them left to hold a road.', '', 0, 0, '', 0, '0'),
(6490, 'The chieftain has heard enough. He sweeps the knives off the map with the back of his hand. "Kill it. Then double the watch."', '', 1, 15, '', 0, ''),
(6701, 'You smell the place before you see it: rotten eggs, hot tar and something worse. A Dark Iron dwarf with a rag over his nose stirs a cauldron the size of a bathtub, feeding the fire with one hand and the pot with the other, while two more wait well back with empty casks. He sees you and jabs the ladle at you. / "OFF my hill! This is delicate work! Ye''ll put me off my count!"', '', 1, 14, '', 0, ''),
(6702, 'Blasting-oil - a great deal of it. The surface is shivering, there''s a yellow crust climbing the rim, and the fire under it is roaring. He keeps adding saltpetre by the ladle to make it stronger. The two with the casks have noticed what he hasn''t: they''ve backed off another ten paces while you were looking. One more ladle and there will be nothing on this hill but a hole.', '', 0, 0, 'unstable', 0, ''),
(6703, 'You get one good lungful and spend the next minute coughing. Balgaras cackles behind his rag. "Aye, she''s ripe! Breathe deep!"', '', 1, 11, '', -1, ''),
(6704, '"Too hot? I''ve brewed oil since before ye -" He looks. The crust has reached the rim. A single slow bubble rises through the oil, the size of a fist. Balgaras puts the ladle down, extremely gently, and begins to walk backwards. The two with the casks have already gone. Halfway down the hill he breaks into a run.', '', 1, 0, '', 0, '0'),
(6705, '"The buyer!" He nearly drops the ladle. "Nobody said - it''s not - it''ll be ready when it''s READY!" He rounds on the other two. "You said next week!" / "We said the buyer''d come when he came!" / Balgaras throws down his rag. "I''ll not be rushed and I''ll not be blamed! Brew it yourselves!" He stamps off over the hill, the other two hurrying after him with the casks, all three shouting at once.', '', 1, 0, '', 0, '0'),
(6706, 'Balgaras squints at you over the rag. "Ye''re no buyer. Ye''re not even singed." He lifts the ladle out of the pot, dripping, and it smokes where the drops land.', '', 1, 274, '', -1, ''),
(6707, 'For one heartbeat, nothing. Then the cauldron makes a sound like the mountain clearing its throat, and the top of the hill goes white. When you can hear again, the three Dark Irons are picking themselves out of the heather, smoking gently, with no eyebrows and no idea which way is up.', '', 0, 15, '', 0, ''),
(6708, 'He sees the seal and his whole manner changes. "Overseer! Nobody told us - " He whips the rag off his face and stands to attention, which lets him smell his own work for the first time. "...It''s a wee bit strong, sir. I was just saying to the lads, it wants cooling. We''ll take it back to the forge and do it properly. Lads! Douse that fire!" They carry the cauldron away between them, very, very carefully.', '', 1, 0, '', 0, '0'),
(6790, '"I''ve lost my count," says Balgaras, with terrible calm, "and it''s YOUR fault." He dips a flask in the cauldron and stoppers it with his thumb. "Lads. Show our guest what it does."', '', 1, 15, '', 0, ''),
(11201, 'A great slab of an ogre sits on a boulder beside the road, with a club across his knees and a cloth tied round his jaw. Two more stand behind him. He holds out a hand the size of a shield. / "Toll. Road is Tho''grun''s. Pay shiny, or Tho''grun breaks you in half and keeps BOTH halves." He winces as he says it.', '', 1, 0, '', 0, ''),
(11202, 'The cloth round his jaw is soaked through, and one side of his face is swollen up like a ripe melon. Every time he talks he winces. A tooth gone bad - an ogre''s tooth, as big as your thumb. He''s been in agony for days, and he''s taking it out on everyone who comes down this road.', '', 0, 0, 'tooth', 0, ''),
(11203, 'A big ogre with a big club. You can''t read more than that before he leans forward, scowling.', '', 0, 0, '', -1, ''),
(11204, 'You get your hand in his mouth - very bravely - find the tooth, and pull. The roar shakes dust off the hills. Then Tho''grun is holding a black tooth in his palm and staring at it, and the pain is gone from his face for the first time in a week. "...Tiny one is GOOD." He gives you the tooth, as a great honour, and waves the road open with his club.', '', 1, 11, '', 0, ''),
(11205, '"OW." Tho''grun clutches his jaw and glares at you. "Tiny one makes it WORSE."', '', 1, 14, '', -1, ''),
(11206, 'Tho''grun has no idea what a licence is, or a tax inspector, and neither do his guards. They look at each other. The idea that there is someone above the boss, who sends little people to count things, worries them deeply. "Tho''grun... pays next time," he mutters, and the three of them shuffle off into the hills before anyone can ask for anything else.', '', 0, 0, '', 0, '0'),
(11207, 'The keg''s Dark Iron stencil means nothing to him, but the smell does. He knocks the bung out with one finger and drinks. The fire ale goes down; his eyes water; and then - slowly - the swelling in his jaw stops mattering at all. "Is good toll," he says thickly, and hugs the keg like a child. "Road is open. Road is open for ever."', '', 1, 11, '', 0, ''),
(11290, 'Tho''grun stands up, and keeps standing up. "No toll. Then Tho''grun takes it out of you."', '', 1, 15, '', 0, ''),
(11401, 'The Explorers'' League dig has new owners. A Dark Iron in a soot-black coat stands at the lip of the shaft, directing two diggers, a heavy book open in one hand. The League''s tents have been knocked flat. He glances up at you and smiles thinly. / "Hammertoe sends a messenger. How quaint. Tell him the dig is under new management."', '', 1, 0, '', 0, ''),
(11402, '"A disc," he says, as if to a child. "Titan-make. The Ironforge fools found the door and didn''t know what it was. I do." He taps the lintel of the shaft with his hammer. You look at it too, while he''s talking: the marks cut into it are old and deep, and not all of them say ''welcome''.', '', 1, 0, 'disc', 0, ''),
(11403, 'You show him the warding-mark among the others - the one that means *keepers*, the one the League had carefully not dug past. Magregan reads it twice. His smile goes. He reads his own book, and goes slightly grey. "...Pack up," he says to the diggers, quietly, and then much louder: "PACK UP."', '', 0, 0, '', 0, '0'),
(11404, '"Thank you for your contribution," says Magregan, and closes the book. "Diggers - we have a new hole to fill."', '', 1, 274, '', -1, ''),
(11405, 'He snatches the map out of your hands before you''ve finished unrolling it. Hammertoe''s own hand, and the real vault marked, miles from here - under the Uldaman road. Magregan looks at his shaft, at the map, at the shaft again, and you can see him counting the weeks he''s wasted. "Diggers! Pick up your tools." He doesn''t thank you. He doesn''t need to; he''s already gone.', '', 0, 0, '', 0, '0'),
(11406, 'Magregan looks at you for a long moment, weighing it. Then he looks north up the road, as if he can hear the boots already. "...Hammertoe never could keep his rifles in a row," he says, and shuts his book with a snap, and goes - but he walks backwards for the first twenty paces.', '', 1, 0, '', 0, '0'),
(11490, '"Enough." Shadow gathers in Magregan''s free hand. "You''ll do for ballast in the shaft."', '', 1, 15, '', 0, ''),
(11601, 'Troggs crowd the mouth of a cave in the hillside: thin troggs, ribs showing. The biggest of them, scarred and wearing a dwarf''s helmet upside down, pounds a bone maul on the ground as you come near, and the rest bare their teeth. / "GRAHH. Stone-skin! Food? FOOD?"', '', 1, 15, '', 0, ''),
(11602, 'The cave''s pool is a crust of cracked mud. Their mushroom-beds have shrivelled. Every trogg here is thirsty and starving, and the war-chief is only holding them back because he hasn''t decided yet whether you''re worth eating. You notice, though, the green line of scrub along the foot of the east ridge: water''s running under there.', '', 0, 0, 'thirst', 0, ''),
(11603, 'Bones and mud and a terrible smell. The troggs edge closer while you look.', '', 0, 0, '', -1, ''),
(11604, 'You lead them out along the ridge and dig, and an arm''s length down the ground goes dark and wet. Then the troggs are all digging, and the water''s coming up, and nobody''s thinking about you any more. Murdaloc drinks first, of course. Then he looks at you, pounds his chest twice, and goes back to the digging.', '', 1, 273, '', 0, ''),
(11605, 'Murdaloc''s maul comes down a hand''s breadth from your foot. "NO. Stone-skin talks too much."', '', 1, 14, '', -1, ''),
(11606, 'The troggs go silent. The idol is earthen-work - a stone figure of the old makers - and to a trogg it is holier than anything in the world. Murdaloc goes down on his knees in front of it, and the whole warren with him. When he looks up at you, it''s with something like terror. He picks up the idol in both hands, very carefully, and backs into the dark, and his tribe goes with him.', '', 0, 0, '', 0, '0'),
(11607, 'You roar. It echoes round the hills. For a long, long moment the war-chief stares at you - and then he puts his head on one side, bows his shoulders, and mutters something that sounds very like ''big stone-skin''. The troggs part to let you through.', '', 1, 2, '', 0, ''),
(11690, '"FOOD!" Murdaloc swings the maul over his head and the starving troggs surge forward.', '', 1, 15, '', 0, ''),
(11801, 'The ravine floor is cracked and smoking. Something long and black uncoils from the rocks above you: a drake, scales like burnt iron, two whelps hissing at its feet. Its voice is a furnace door opening. / "Another thief. Another little thief come for my clutch."', '', 1, 0, '', 0, ''),
(11802, '"Seven eggs I laid in the warm stone. Six lie there now." Its head swings toward a hollow in the rock, where six black eggs steam gently. "Someone came in the night. Someone with hands." It looks at your hands.', '', 1, 0, 'egg', 0, ''),
(11803, 'The drake brings its head down until its eye is the size of a shield in front of your face, and looks into you for a long time. You hold still. At last it breathes out - hot, and smelling of sulphur - and draws back. "...No. You are a fool, not a thief. Go. And if you find the thief..." It doesn''t finish. It doesn''t need to.', '', 1, 0, '', 0, ''),
(11804, 'Smoke curls from its nostrils. "Lies. I can smell lies, little thing. They smell like you."', '', 1, 274, '', -1, ''),
(11805, 'The drake goes absolutely still. Then, very gently, it takes the egg from your hands in its jaws - the teeth do not even scratch you - and lays it among the others, and curls round all seven. The whelps creep in under its wing. When it looks at you again, it is a different look entirely. "Go in peace, egg-bringer. No fire of mine will touch you."', '', 1, 0, '', 0, ''),
(11806, 'Its eyes narrow to slits, and then turn west, toward the ogre hills. "The Dustbelchers." It is up into the air in a single beat of its wings, the whelps scrambling after it, and the sound of its roar rolls away over the badlands. You find you don''t want to be anywhere near those hills tonight.', '', 0, 0, '', 0, '0'),
(11890, '"Thief." The drake''s throat glows orange from inside. "Burn."', '', 1, 15, '', 0, ''),
(12001, 'A siege golem of riveted iron stands in the middle of an empty patch of dust, steam leaking from every seam, its ram-arm raised. As you come close its head swivels to you with a grinding noise, and a voice like a kettle shrieks out of a grille in its chest. / "HALT. THIS AREA IS GUARDED. HALT. THIS AREA IS GUARDED." There is nothing in the area.', '', 1, 25, '', 0, ''),
(12002, 'A brass plate, half rubbed off by sand: PROPERTY OF L. VERIATUS. IN EVENT OF MALFUNCTION: ISSUE STAND-DOWN WITH OWNER AUTHORISATION. Under that, someone has scratched by hand: ''or just hit it with something heavy, it usually works''. The golem watches you read it.', '', 0, 0, 'plate', 0, ''),
(12003, 'A long, grinding pause. Then: "AUTHORISATION... ACCEPTED." The ram-arm lowers. Steam sighs out of it all at once, and it turns, creaking, and starts the long walk back to Lotwil''s camp, saying "GOOD DAY" to a cactus on its way past.', '', 0, 0, '', 0, '0'),
(12004, 'You go under the ram as it swings and come up behind it, and the lever is exactly where you''d put it if you were a gnome. Clunk. The golem''s lights go out; it sags; it sits down in the dust with a sound like a dropped stove. In a while, Lotwil will come and find it.', '', 0, 0, '', 0, ''),
(12005, 'The ram catches the air a finger''s width from your head. "HALT," says the golem, louder.', '', 1, 5, '', -1, ''),
(12006, 'The rod goes in with a click. Every light on the golem turns green. "NEW OPERATOR," it announces. "AWAITING ORDERS." You tell it to go home. It goes home - and, being a golem, it goes in a perfectly straight line, through a cactus, two rocks and a thorn bush.', '', 0, 0, '', 0, '0'),
(12090, '"INTRUDER," the golem decides. Its ram draws back with a hiss of steam.', '', 1, 15, '', 0, ''),
(12201, 'Angor Fortress squats over the canyon, and its commander meets you in the gate: a Dark Iron in scorched plate, a warhammer on his shoulder, two soldiers behind him. All three are thin. / "Ironforge spy, or Shadowforge courier? Choose your answer carefully. We''ve been waiting a long time for one of those, and we''d be glad to kill the other."', '', 1, 0, '', 0, ''),
(12202, 'Their armour is polished, but their belts have been taken in. The chanter''s robe is patched with sacking. Nobody has relieved this garrison in a very long time, and every one of them knows it - and the commander knows they know it. He''s holding his fortress for masters who have forgotten it exists.', '', 0, 0, 'forgotten', 0, ''),
(12203, 'Three Dark Irons with weapons. That''s all you can tell, before the commander''s patience shows on his face.', '', 0, 0, '', -1, ''),
(12204, 'The commander''s jaw works. Behind him, the warrior lowers his axe a little, and doesn''t raise it again. "...A year," says the commander, at last. "A year and two months." He looks up at his walls as if seeing them for the first time. "Open the stores. Eat what''s left. We march for the Gorge at dawn." He doesn''t look at you again.', '', 1, 0, '', 0, '0'),
(12205, 'The warhammer comes down off his shoulder. "A spy, then."', '', 1, 274, '', -1, ''),
(12206, 'He breaks the seal with his thumb and reads, and his face does several things at once. The orders recall the garrison to the Searing Gorge - and they are dated eleven months ago. Somebody lost them on the road. "Eleven months," he says, very quietly. "Eleven months we''ve held this rock for nothing." He folds the orders into his gauntlet. "Form up."', '', 0, 0, '', 0, '0'),
(12207, 'He stares at you. You hold his eye. "...Nobody else would," he repeats, and something in him wants it to be true so badly that he lets it be. "Form up! We march for the Gorge!" His soldiers are already gathering their packs.', '', 1, 0, '', 0, '0'),
(12290, '"Spy." The commander raises his hammer. "Angor has not fallen yet."', '', 1, 15, '', 0, ''),
(12401, 'What you took for a ridge of red rock is shifting. A great stone face opens two eyes like cave mouths, and dust pours off its shoulders as it heaves itself half upright. Its voice is a landslide, slowed down. / "WHO... DIGS... IN ME?"', '', 1, 0, '', 0, ''),
(12402, '"I SLEPT," says the giant, "WHEN THIS LAND WAS GREEN. NOW THE SMALL ONES DIG. THEIR SHAFTS ARE IN MY... BACK." It sounds more aggrieved than angry. "I WISH ONLY TO SLEEP."', '', 1, 0, 'dreamer', 0, ''),
(12403, 'The giant considers this for a long time, as mountains do. "...GOOD," it says. Its eyes close. Its shoulders settle. The dust stops falling. In a minute there is only a long red ridge again, with a face you can see if you squint.', '', 1, 0, '', 0, ''),
(12404, 'The old song is slow and very low, and you can''t sing it nearly low enough, but the giant knows it. Its eyes go half-closed. It hums along, and the ground hums with it, and the small stones dance on the rock. By the last line it has lain back down. By the time you stop singing, it is asleep.', '', 0, 0, '', 0, ''),
(12405, 'You shout, and the giant blinks. Something so small, shouting at it - it has not happened in ten thousand years. It is so surprised that it forgets to be angry, and lies back down to think about it, and in the middle of thinking about it, falls asleep.', '', 0, 0, '', 0, ''),
(12406, '"SMALL... AND LOUD." The giant heaves itself a little higher, and rocks crack off its shoulders.', '', 1, 15, '', -1, ''),
(12490, 'The mountain wakes all the way. It stands. The ground goes out from under you.', '', 1, 15, '', 0, ''),
(13201, 'On the Cauldron''s rim a line of chained slaves hauls ore carts up a ramp, under the eye of a Dark Iron in black plate with a barbed whip coiled at his belt. Two guards flank him. He looks you over the way a butcher looks at a pig. / "You''ve no chain on. Easily fixed. I''m short six pairs of hands this week."', '', 1, 0, '', 0, ''),
(13202, 'The slaves are worn to the bone and moving slowly - too slowly. The carts come up half full. Blackheart''s eyes keep going to a tally-board by the ramp, and every time they do, his jaw tightens. He''s behind his quota, badly, and somebody above him is going to notice.', '', 0, 0, 'quota', 0, ''),
(13203, 'Chains, carts, a whip. You don''t learn more before Blackheart notices you staring.', '', 0, 0, '', -1, ''),
(13204, 'Blackheart goes very still. He knows exactly what Thaurissan does to overseers who miss quota. He looks at the slaves, and the tally-board, and you, and does the sums. "...Bad air in the pit," he says at last, flatly. "Six slaves lost. Very sad." He unlocks the chain himself and turns his back, and the slaves run for Thorium Point before he can change his mind. A moment later, so does he - the other way.', '', 1, 0, '', 0, '0'),
(13205, 'The whip uncoils. "Wrong answer."', '', 1, 274, '', -1, ''),
(13206, 'He reads the first page and goes grey under the soot. The ledger is his - every faked tally, every slave reported delivered and never sent, every bar of iron that went into his own pocket. One copy of this in the right hands at the Shadowforge and he''s in the forge himself. "What do you want?" he says hoarsely. You tell him. The chains come off. He takes the ledger in exchange and leaves, at speed.', '', 1, 0, '', 0, '0'),
(13207, 'For one long moment you think it''s worked. Then he laughs. "The Emperor''s inspectors don''t walk." He stops laughing. "But I''ll admit, that was nerve." He looks at you with something like respect - and signals his guards to step back. "Go on. Get out of my sight before I change my mind."', '', 1, 11, '', 0, ''),
(13290, '"Enough talk." Blackheart''s whip cracks. "Chain this one with the rest."', '', 1, 15, '', 0, ''),
(13401, 'On a pulpit of black rock above Firewatch Ridge, a robed figure with burning eyes preaches to two cultists and the empty air. "The world is a cracked egg, and the Old Gods are hatching! Flame and stone shall unmake it!" He sees you and spreads his arms. / "A pilgrim! Have you come to hear the truth, child? The end is coming. I know the day."', '', 1, 5, '', 0, ''),
(13402, '"The Hour of Twilight!" He thrusts a tract at you: a crude woodcut of the world on fire, and a date in red - the day the sky splits and the deep things rise. You look at the date. You count. It was last week. Neither of his followers seems to have noticed. Yet.', '', 1, 0, 'prophecy', 0, ''),
(13403, 'You point at the date. Then at the sky, which is unsplit. Then at the ground, from which nothing has risen. The two cultists look at the date too. One of them, slowly, starts counting on his fingers. The highlord begins to explain about recalculations, and celestial error, and the day the world ends being more of an idea - but his congregation is already drifting off down the ridge, and after a while he gives up and follows them, still explaining.', '', 0, 0, '', 0, '0'),
(13404, 'His burning eyes narrow. "A doubter. The Hour has a place for doubters, child. It is very hot."', '', 1, 25, '', -1, ''),
(13405, 'You read it aloud: the Twilight''s own scripture, in their own hand, naming a different day entirely - and calling anyone who preaches otherwise a heretic, fit for the fire. The cultists turn and look at their highlord. He looks at the tract. "That is a FORGERY -" he begins, and his followers, being Twilight''s Hammer, take the scripture''s side. He runs. They chase him. You have the ridge to yourself.', '', 0, 0, '', 0, '0'),
(13406, 'You climb on a rock and announce, at the top of your lungs, a doom so much worse than his - with dragons, and worms, and tax collectors - that the two cultists turn to listen to you instead. The highlord tries to out-shout you and can''t. When you finish, his followers are looking at you with shining eyes. He drags them away by their collars before they can convert.', '', 1, 14, '', 0, ''),
(13490, '"Then you shall be the first to burn!" The highlord''s hands fill with violet flame.', '', 1, 15, '', 0, ''),
(13601, 'Three Dark Irons crouch round a hole in the rock, two geologists with hammers and a watchman leaning on a halberd. One of the geologists is tapping at a seam of glittering stone with enormous care. He waves you back without looking up. / "Stay back! Thorium! Biggest seam since the Cataclysm - since before it! Don''t you DARE breathe on it."', '', 1, 0, '', 0, ''),
(13602, '"Thorium," he breathes, and strikes the seam again: a little puff of yellowish air hisses out, and the watchman wrinkles his nose. The stone glitters, all right - but it''s the wrong glitter, and that smell is rotten eggs. They have struck a gas pocket, and they''re hitting it with a steel hammer, next to a camp-fire.', '', 1, 0, 'strike', 0, ''),
(13603, 'You explain, slowly, about gas, and steel, and sparks. The geologist stops with the hammer in the air. He looks at the fire. The watchman looks at the fire. Then all three of them are running, and you''re running too - and behind you, a moment later, the seam goes off with a WHUMP and a sheet of yellow flame, and when the smoke clears the camp is gone. The geologists are sitting on a rock some way off, singed and very grateful. They don''t argue when you suggest they go home.', '', 0, 0, '', 0, '0'),
(13604, 'The watchman straightens up and hefts his halberd. "He said stay back."', '', 1, 274, '', -1, ''),
(13605, 'The geologist snatches the map. It''s a Thorium Brotherhood vein-survey, years old - and the seam it marks is a real one, rich and deep, in the far end of the Gorge. He forgets the hole he''s been tapping at. He forgets you. "PACK UP! We''re moving!" They''re gone in minutes. Somebody should probably warn the Brotherhood.', '', 0, 0, '', 0, '0'),
(13606, 'You get down beside him and read the layers together, and he is so delighted to have someone who understands strata that he forgets you''re the enemy. By the time you''ve worked out together that the real seam runs a mile north, you''re old friends. He gives you a lump of the ore, as a keepsake, and moves the whole camp.', '', 1, 273, '', 0, ''),
(13690, '"Spy!" shrieks the geologist. "Brotherhood spy! Get it!"', '', 1, 15, '', 0, ''),
(13801, 'A golem of polished black glass stands at the end of a ruined dig, among broken tents and rusted tools. It is beautiful, and enormous, and its eyes are two coals. When you take a step closer its head turns, with a sound like a bell. / "HALT. THE DIG IS UNDER GUARD. STATE YOUR BUSINESS WITH THE EXPEDITION."', '', 1, 0, '', 0, ''),
(13802, 'The plinth is carved in the Explorers'' League''s hand: OBSIDION, KEEPER OF THE DIG, MADE BY THE HANDS OF THE EXPEDITION, TO GUARD THEM UNTIL THEY RETURN. Under the broken tents, you can see, the expedition did return - and never left again. The golem has guarded their bones for years.', '', 0, 0, 'keepers', 0, ''),
(13803, 'The coals of its eyes dim a little. For a long while it says nothing. Then it turns its great head to the broken tents, and back to you. "THE EXPEDITION... DOES NOT RETURN." It isn''t a question. It lowers itself onto one knee among the bones, very slowly, like a dog lying down beside its master, and goes still. Its eyes stay lit, just. It lets you pass.', '', 0, 0, '', 0, ''),
(13804, 'The rune flares when it touches the glass, and the golem''s eyes flare with it - a keeper''s mark, the expedition''s own. "AUTHORITY RECOGNISED," it says, and something in the voice sounds almost relieved. "KEEPER... RELIEVED OF WATCH." It turns and walks, slowly, out of the dig and away up the Gorge, and does not look back.', '', 0, 0, '', 0, '0'),
(13805, 'You walk past it as if you''ve every right to. The golem''s head follows you all the way, but it decides - after a long, grinding pause - that someone walking that confidently must be with the expedition.', '', 0, 0, '', 0, ''),
(13806, '"HALT," says the golem again, and this time the ground shakes when it steps forward.', '', 1, 5, '', -1, ''),
(13890, '"INTRUDER AT THE DIG." The golem''s fists come up, glittering.', '', 1, 15, '', 0, ''),
(14001, 'A young human in a Twilight robe much too big for him kneels before a lumpy clay idol on a rock, muttering a prayer he clearly hasn''t learned yet. He jumps up when he sees you and brandishes a knife, with both hands, shaking. / "Stay back! I - I serve the Hour! I''m very dangerous! Please stay back."', '', 1, 24, '', 0, ''),
(14002, '"I''m FINE," he says, and then his face crumples. "They said there''d be power. They said I''d be someone. I was a farmhand in Redridge. Now I''m out here on my own, guarding a rock, and the others laugh at me, and I miss my mum." He wipes his nose on the enormous sleeve.', '', 1, 0, 'homesick', 0, ''),
(14003, 'He stares at you as if nobody has ever suggested it. "...Can I?" He looks at the idol, and back the way you came, and then he pulls off the robe, drops it on the rock and runs - in his shirt and breeches, as fast as he can, east, toward home.', '', 0, 0, '', 0, '0'),
(14004, 'He reads it twice. It''s from Redridge, in a careful, unpractised hand: the harvest is in, the dog had puppies, they''ve kept his room, come home. He sits down on the rock with the letter on his knees and cries, and you let him. Then he gets up, kicks the idol off the rock, and goes.', '', 1, 0, '', 0, '0'),
(14005, 'He goes white. He has seen the way the highlord looks at him. "...You think so?" You do. The knife drops. So does the robe. He is gone down the ridge before it hits the ground.', '', 0, 0, '', 0, '0'),
(14006, '"You''re LYING!" he squeaks, and the knife shakes harder. "Go away!"', '', 1, 274, '', -1, ''),
(14090, 'He panics. The knife comes at you in a wild overhand, and he''s screaming a prayer that ends in fire.', '', 1, 15, '', 0, ''),
(14201, 'A Dark Iron in a leather apron stands beside a war golem twice his height, adjusting something in its chest with a long spanner while its furnace-heart roars. An apprentice works the bellows. He sees you, and instead of reaching for a weapon, he puffs himself up. / "Ah! A witness! Behold - the Mark Nine! Faster, stronger, hotter than anything Blackrock has ever seen! Go on. Admire it."', '', 1, 25, '', 0, ''),
(14202, 'He beams. "Isn''t it? My finest work. My MASTERWORK. They laughed at the Mark Eight. Nobody will laugh at THIS." He talks for some time about pressure ratios. It''s clear that what he wants more than anything in the world is for someone important to see it.', '', 1, 0, 'vain', 0, ''),
(14203, '"Myself? To the Emperor?" He goes pink with pride. "Well - yes. Yes, why not! Why should I waste it out here?" He and his apprentice and the golem set off at once for the Shadowforge, the steamsmith rehearsing his speech out loud. You hope, for his sake, the Emperor is in a good mood.', '', 1, 0, '', 0, '0'),
(14204, 'His face darkens. "A critic." He turns to the golem. "Mark Nine - test target."', '', 1, 14, '', -1, ''),
(14205, 'He reads the schematic and his face goes from red to purple. It''s his golem - every rivet of it - drawn a year ago, and signed by another steamsmith. His Mark Nine is a copy, and somewhere a rival has been building the original. "THAT THIEVING -" He grabs his spanner and storms off to have it out with him, the apprentice and the golem trailing behind.', '', 1, 0, '', 0, '0'),
(14206, 'You point at the valve. He laughs - and then looks, and stops laughing. A crack runs right through it. If he''d fired the furnace up to full, the Mark Nine would have gone off like a bomb, taking the forge, the apprentice and himself with it. He looks at you as if you''ve just saved his life, which you have. "...I owe you," he says, and means it, and lets you go.', '', 1, 2, '', 0, ''),
(14290, '"Mark Nine!" The steamsmith throws a lever. "Live-fire trial!"', '', 1, 15, '', 0, ''),
(14401, 'Between four iron stakes, sunk deep and glowing with runes, a figure of living flame strains against chains of dark metal. A lesser elemental flickers at its side. When it sees you its fire leaps up, white-hot. Its voice crackles like a forest burning. / "A free thing! A thing with HANDS! Break these chains, and you will have the gratitude of fire."', '', 1, 0, '', 0, ''),
(14402, '"The Dark Irons bound me," it hisses, "to heat their forges. Every day they come and bleed me into their furnaces." You look at the stakes: four of them, glyphs carved in a circle, and one stake leaning, its base cracked by years of heat. Strong as the binding is, it''s only as strong as that stake.', '', 1, 0, 'chains', 0, ''),
(14403, 'You strike the cracked stake with everything you''ve got. It splits. The chain on that side falls slack - and then all four burst at once, their runes going dark. Smoldar rises, huge and blinding, and for an awful moment you think it''s going to burn you where you stand. Then it bows, in a rush of heat, and is gone, up into the smoke over the Gorge.', '', 0, 0, '', 0, '0'),
(14404, 'The chains flare and the elemental screams with them. "FOOL. You make it TIGHTER."', '', 1, 15, '', -1, ''),
(14405, 'You trace the glyph backwards across the stakes, one after another, and each one goes dark as you finish it. With the fourth, the chains simply fall. Smoldar looks down at them, and then at you, for a long, crackling moment. "You unmade it. Clean." It sounds impressed. "Fire remembers." Then it''s gone in a column of sparks.', '', 0, 0, '', 0, '0'),
(14406, 'It hesitates. Fire doesn''t promise easily. But the chains bite, and at last it speaks the words - an oath in the tongue of flame that makes the air shimmer. You speak the counter-word to the binding, and the chains fall. Smoldar keeps its oath: it rises into the sky and goes, burning, toward the mountain, and the Gorge feels cooler for its going.', '', 1, 0, '', 0, '0'),
(14490, '"Then BURN with them!" The chains glow white and the fire lunges as far as they''ll let it.', '', 1, 15, '', 0, ''),
(15001, 'The throne room is lit red by the Great Forge below. On the High Seat sits a dwarf woman in black and gold, a slim crown on her brow, two Anvilrage wardens at her shoulders. Behind the throne, where Magni once stood, there is a shape under a heavy cloth - a shape the size of a dwarf, very still. She looks at you for a long moment. / "Another adventurer. Have you come to kill me, or to kneel? Both have been tried this week."', '', 1, 0, '', 0, ''),
(15002, 'She is very good at this - the cool voice, the steady hands. But she never once looks at the shape under the cloth, and her wardens are watching the doors, not you. She isn''t ruling this city. She''s holding it, with her fingertips, and she''s terrified of what happens when she lets go: to her, and to her son, who would be king after her.', '', 0, 0, 'afraid', 0, ''),
(15003, 'A queen on a throne, guards at her side. Her face gives you nothing.', '', 0, 0, '', -1, ''),
(15004, '"All three." She says it slowly, as if tasting it. "The Wildhammers would spit on me. The Bronzebeards would rather die." A pause. "...But they would come, if I asked. To see me humbled, if nothing else." She looks, at last, at the cloth. "Father always said a king is the first among the clans, not over them." She rises. "Send for the Wildhammer thane. And Muradin''s people. Tell them the regent asks."', '', 1, 2, '', 0, ''),
(15005, 'Her eyes go cold. "You presume a great deal." The wardens'' hammers come up an inch.', '', 1, 274, '', -1, ''),
(15006, 'The shard catches the forge-light: a sliver of diamond, and in it, unmistakable, the grain of a dwarf''s beard. Moira''s composure breaks for the first time. She comes down from the throne and kneels to look at it. "He''s in there. Still in there. I didn''t..." She stops. "The ritual wasn''t mine. I took the throne because someone had to. But if he can be woken..." She looks up at you, and she isn''t a regent now, only a daughter. "Find who did it. Whatever you need, the wardens will not stop you."', '', 1, 0, '', 0, ''),
(15007, '"The Council of Three Hammers," she says, "is a dream my father had." But you see the wardens look at each other - they know the law as well as you do. Moira sees it too. "...Very well. A council. Let them come and tell me to my face." She waves you away, and you go, and behind you she calls for a scribe.', '', 1, 0, '', 0, ''),
(15090, '"Enough." Moira''s hand closes on a dark gem at her throat. "Wardens."', '', 1, 15, '', 0, ''),
(15101, 'The Great Forge thunders. Bronzebeard smiths work at the anvils - grim, silent, sweating - while an Anvilrage overseer walks between them with a soldier at his back, checking every blade. He sees you and points with his hammer. / "You. Can you swing a hammer? The regent needs a thousand blades by the month''s end and these fools are giving me five a day."', '', 1, 25, '', 0, ''),
(15102, 'They''re slowing down on purpose. You can see it: a quench left a moment too long, a blade put back in the fire for no reason, an apprentice sent for coal three times. The smiths are working to rule, every one, and the overseer hasn''t worked out why the numbers keep falling.', '', 0, 0, 'slowing', 0, ''),
(15103, 'The overseer opens his mouth to argue, and then looks at the rack of blades - and picks one up, and flexes it, and frowns. It''s poor steel. All of it. "...They''d do this to their own city?" he says. "To THEIR OWN weapons?" He throws the blade down. "Fine. Fair wages, and no whip. Tell them." And to your surprise, he goes, and the forge sounds different behind him.', '', 0, 0, '', 0, '0'),
(15104, '"Get out of my forge," says the overseer, "or get in a chain."', '', 1, 14, '', -1, ''),
(15105, 'You raise the old hammer of the forgemasters'' guild - lost the day the regency came - and the forge goes silent. One by one, every smith in the Great Forge puts down his tools and turns to face it. Then they turn to face the overseer. There are forty of them. He has one soldier. He leaves the hammer where it is and leaves the forge, slowly, and nobody stops him.', '', 0, 0, '', 0, ''),
(15106, 'You take a hammer and a bar of hot iron and work it the way the old smiths of Ironforge do - and when you''re done the overseer turns it in his hands for a long time. "...Huh," he says. He lets you go, and goes off muttering to watch the anvils more closely. Behind his back, the smiths are grinning.', '', 1, 273, '', 0, ''),
(15190, '"Saboteur!" The overseer raises his hammer. "Take this one!"', '', 1, 15, '', 0, ''),
(15301, 'In a side-tunnel off the Deeprun Tram, three figures crouch round a shuttered lantern: a Forsaken in a dark cloak, another with a coil of rope, and a huge orc squashed uncomfortably into a dwarf''s coat. The Forsaken looks up, unhurried. / "Ah. A tourist. You''ve taken a wrong turn, friend - the tram is that way. Go and catch it."', '', 1, 0, '', 0, ''),
(15302, 'Maps. The Military Ward''s guard posts, the Gates, the throne room, each one marked with times - patrols, changes of the watch. Someone has been very busy. And at the bottom of the sheet, a note: ''contact at the Stonefire, third bell, he''ll bring the last of it''. They''re waiting for someone, and he''s late.', '', 0, 0, 'maps', 0, ''),
(15303, 'Scraps of paper. The orc shifts his bulk between you and them.', '', 0, 0, '', -1, ''),
(15304, 'The Forsaken''s face doesn''t change - it can''t, much - but the orc''s does. "I TOLD you," he hisses. "I told you the dwarf was trouble -" They''re already packing. Two minutes later the tunnel is empty but for a scorched patch where they burned their maps.', '', 0, 0, '', 0, '0'),
(15305, 'The Forsaken sighs. "And you were doing so well." A blade slides out of his sleeve.', '', 1, 274, '', -1, ''),
(15306, 'You read the first line of their cipher aloud, in plain Common. The Forsaken goes very still. If you have the key, so might the regency - and every message they''ve sent for a month is an open book. "Burn it all," he says quietly to the others, and they do, and go, and you never see them again.', '', 0, 0, '', 0, '0'),
(15307, 'You draw breath to shout. The orc''s hand is already on the Forsaken''s shoulder, pulling. "Not worth it," he grunts. "Not today." They go back up the tunnel toward the tram, fast.', '', 0, 0, '', 0, '0'),
(15390, '"Pity," says the Forsaken, and the orc''s axe comes out from under the dwarf''s coat.', '', 1, 15, '', 0, ''),
(15401, 'In the Forlorn Cavern a robed figure stands on a crate, preaching to a small, hungry-looking crowd, two acolytes passing among them with a bowl. "The king of stone! Do you not see? The deep earth has claimed him - the Old Gods have SPOKEN! And who will hear them next?" He spots you. / "A new face! Come, friend, listen. The end of the world is very good news, if you''re on the right side of it."', '', 1, 5, '', 0, ''),
(15402, '"Turned to stone at the Great Forge''s heart!" the preacher cries. "No mortal hand could do that - only the will of the deep." But as he says it, one of his acolytes looks quickly at the floor. Whatever happened to Magni, the cult knows more about it than a ''sign''.', '', 1, 0, 'sign', 0, ''),
(15403, 'You say it plainly, loud enough for the crowd. A ritual. Cast by hands. The crowd murmurs. The acolyte who looked at the floor drops the collection bowl and bolts - and that''s all the crowd needs. The preacher shouts after them about blasphemy, but nobody''s listening, and in the end he climbs down off his crate and slips away into the dark.', '', 0, 0, '', 0, '0'),
(15404, 'The preacher smiles thinly. "The doubters are always the first into the fire, friend."', '', 1, 25, '', -1, ''),
(15405, 'You read it out: the ritual of binding stone, written in the cult''s own hand, with Magni''s name and the Great Forge and the hour, and a list of the acolytes who stood the circle. One of the names is standing right in front of you, holding the collection bowl. The crowd turns. The preacher and his acolytes run, and the crowd chases them out of the cavern, and somewhere a city guard is going to have a very interesting afternoon.', '', 0, 0, '', 0, '0'),
(15406, 'Every grand line he delivers, you answer. The crowd starts laughing. Then the acolytes start laughing. The preacher tries to soldier on, purple-faced, and finally gives up and stamps off the crate, and the crowd claps - for you.', '', 1, 14, '', 0, ''),
(15490, '"Then be the first offering!" The preacher''s hands fill with violet fire.', '', 1, 15, '', 0, ''),
(15501, 'In a corner of Tinker Town, three gnomes in patched coveralls and breathing-masks are going through a heap of scrap, pocketing anything that shines. Their skin has the grey-green tinge of Gnomeregan''s poison. They freeze when they see you. The nearest raises a spanner like a sword. / "It''s OURS. We found it first. Go and find your own scrap."', '', 1, 0, '', 0, ''),
(15502, '"Gnomeregan happened," says the gnome, bitterly. "Then the radiation happened. Then Ironforge happened - a corner and a blanket, and they''d rather we stayed in it. Now there''s a regent, and the regent doesn''t care about gnomes at all, and Mekkatorque''s so busy with his plans he hasn''t been down here in weeks. We''re just... forgotten."', '', 1, 0, 'forgotten', 0, ''),
(15503, 'They look at each other. "...Would you?" The spanner comes down. "He listens to big folk. He never listens to us." They go back to their blankets, not to the scrap, and the oldest one even manages a smile. "Tell him we''ve a design for a better air-filter. He''ll want to hear about that."', '', 0, 0, '', 0, ''),
(15504, 'They know what it is the moment they see the label. One of them pulls off his mask and smears it on his face, his hands, and you watch the grey tinge fade a shade. "That''s - that''s proper medicine. That''s from the Gnomeregan infirmary." They divide it three ways, very carefully, and forget all about the scrap.', '', 1, 273, '', 0, ''),
(15505, 'The mask''s air-line has split and is hissing. You bind it with a strip of leather and a bit of wire, and the gnome takes a long, clear breath for the first time in days. After that, nobody''s very interested in fighting over scrap.', '', 1, 2, '', 0, ''),
(15506, 'You make it worse. The pipe hisses louder. "Get AWAY from it!"', '', 1, 274, '', -1, ''),
(15590, '"Mine!" shrieks the gnome, and swings the spanner, and the others pile in.', '', 1, 15, '', 0, ''),
(15601, 'At the back of the Hall of Explorers, a figure of carved stone has stepped down off its plinth. An earthen guardian, a museum piece for three hundred years - and now its eyes are lit like lamps and it stands across the corridor to the League''s vaults. Its voice is two millstones turning. / "THE MAKER''S SLEEP IS BROKEN. NONE PASS WITHOUT THE KEEPER''S WORD."', '', 1, 0, '', 0, ''),
(15602, 'The plaque reads: EARTHEN GUARDIAN, DISCOVERED ULDAMAN. DORMANT. DO NOT TOUCH. Underneath, a League scholar has added in pencil: ''Keeper''s word, per the Uldaman tablets: The past is a door. (If it ever wakes up - which it won''t.)'' It has. Whatever was done to the king at the Great Forge woke it too.', '', 0, 0, 'password', 0, ''),
(15603, 'A pause, long as a century. "THE WORD IS SPOKEN." The guardian turns, steps back up onto its plinth, and is still. Its eyes dim to embers. The way to the vaults is open.', '', 0, 0, '', 0, ''),
(15604, 'The disc''s runes flare when it sees them, and the guardian bows - all the way, until its stone brow almost touches the floor. "A MAKER''S KEY. FORGIVE THE WATCHER." It retreats to its plinth, and you could swear it looks embarrassed.', '', 0, 0, '', 0, ''),
(15605, 'You make the old signs from the Uldaman friezes - slowly, carefully. The guardian watches your hands. Then it answers in kind, and steps aside.', '', 0, 0, '', 0, ''),
(15606, 'Your hands say something they shouldn''t. The guardian''s eyes flare. "FALSE SIGN."', '', 1, 15, '', -1, ''),
(15690, '"INTRUDER." The guardian raises two fists the size of anvils.', '', 1, 15, '', 0, ''),
(15801, 'In the back of the Military Ward, three dwarves in Stormpike blue crowd round a table. The captain looks up sharply, and a rifle comes up across the room. / "Well, well. The regent sends her errand-runners further every day. Sit down, spy. Slowly."', '', 1, 0, '', 0, ''),
(15802, 'A plan of the throne room, every warden''s post marked. A sketch of the Great Forge''s lift. And the hour of the regent''s evening audience, underlined three times. These aren''t loyalists waiting it out. They mean to kill Moira, and soon - and if they do, every Dark Iron in the city will rise.', '', 0, 0, 'plot', 0, ''),
(15803, 'A table, some papers they cover quickly. You don''t get a good look.', '', 0, 0, '', -1, ''),
(15804, 'The captain listens. He doesn''t like it - but he isn''t a fool, and he''s seen what Dark Irons do to a city. "...The clans," he says at last. "Muradin. The Wildhammers." He rolls up the plan. "If they come, we''ll be ready. If they don''t -" He doesn''t finish. But the rifle goes down.', '', 1, 273, '', 0, ''),
(15805, '"That''s what a spy would say," says the captain, and the rifle doesn''t waver.', '', 1, 274, '', -1, ''),
(15806, 'You put the ring on the table. The king''s own seal - the one Magni wore every day of his reign, taken from the throne room the night of the ritual. The captain picks it up with shaking hands. All three of them go down on one knee - not to you, to the ring. "Where did you find this?" he whispers. You tell him. "Then you''re one of us. Whatever you need."', '', 1, 2, '', 0, ''),
(15807, 'He thinks about it. Then he lowers the rifle, slowly, and almost smiles. "No. You''d be the worst spy in Ironforge." He waves you to the door. "Go on. And if you see the regent - you never saw us."', '', 1, 11, '', 0, ''),
(15890, '"She sent you to kill us," the captain decides. "Not tonight."', '', 1, 15, '', 0, ''),
(16101, 'The Stonefire Tavern is in ruins: chairs broken, a table upended, a barrel leaking ale across the floor. Three Dark Iron drunks have the place to themselves, singing tunelessly, while the barkeep cowers behind the bar. The loudest one swings round on his stool. / "Shhh! SHHHH! Another one! Barkeep - a drink for our new friend. On YOUR tab." Great laughter.', '', 1, 11, '', 0, ''),
(16102, 'Bruuk leans over the bar, whispering. "They''ve been here since noon. Haven''t paid a copper. Say they''re the regent''s men and the regent pays. She doesn''t. If they don''t pay up soon, I''ll lose the tavern." The drunks have run up a tab long enough to wallpaper the room.', '', 0, 0, 'tab', 0, ''),
(16103, 'The loudest one cackles and slams his elbow down on the table. It''s a long, grunting, red-faced minute. Then his knuckles hit the wood. He stares at them. His friends stare at him. "...Fair''s fair," he says thickly, and empties his purse on the bar, and the three of them stagger out into the Commons.', '', 0, 0, '', 0, '0'),
(16104, '"Oh, THIS one''s funny," says the loudest drunk, picking up a stool.', '', 1, 14, '', -1, ''),
(16105, 'The first line of the Grim Guzzler''s song and all three of them go quiet. It''s the song from home - from the Grim Guzzler, deep in Blackrock - and by the second verse they''re singing along, tears in their beards. By the last, they''re hugging you, and each other, and the barkeep. They pay their tab. They overpay. They leave singing.', '', 1, 11, '', 0, ''),
(16106, 'You climb onto the bar and roar until the bottles rattle. When you stop, the three drunks are looking up at you with their mouths open. Then, very quietly, they put money on the bar and tiptoe out.', '', 0, 0, '', 0, ''),
(16190, '"BRAWL!" shouts the loudest drunk, delighted, and hurls a tankard.', '', 1, 15, '', 0, ''),
(16201, 'In the Vault of Ironforge, a Dark Iron in a senator''s robe sits at the ledger-desk with a pot of ink, a stack of deeds and a clerk blotting each page. The bankers stand well back. He doesn''t look up. / "If you have business with the vault, take a number. The regency''s affairs come first."', '', 1, 0, '', 0, ''),
(16202, 'Deeds to Bronzebeard holdings - mines, halls, the clan''s own vaults - being copied out with a new name at the bottom of each. The originals go into a sack at his feet. He is rewriting who owns half of Ironforge, page by page, and the ink on the top one isn''t dry.', '', 0, 0, 'forgery', 0, ''),
(16203, 'Papers. Lots of papers. The clerk moves to block your view.', '', 0, 0, '', -1, ''),
(16204, 'His pen stops. He looks at the wet ink, and at you, and does a sum in his head about how the regent would take this. "...Clerical error," he says, and the originals come back out of the sack. "Purely clerical." He leaves rather quickly, the clerk scurrying after him.', '', 1, 0, '', 0, '0'),
(16205, 'The senator lays down his pen. "Guards," he says mildly, to nobody in particular.', '', 1, 274, '', -1, ''),
(16206, 'The true deed - the Bronzebeard clan''s own, sealed by Magni himself - lies on top of the forgery, and every banker in the vault can see the difference. The senator looks at it for a long moment. Then he stands, gathers his robe, and walks out without a word. The bankers burn the forgeries.', '', 0, 0, '', 0, ''),
(16207, '"Hanging?" The senator laughs, but it comes out thin. He looks at the bankers, who are looking at him, and very slowly puts the cap back on his ink. "Perhaps... this can wait for a more convenient day."', '', 1, 0, '', 0, '0'),
(16290, '"How tiresome." The senator stands, and fire kindles in his palm.', '', 1, 15, '', 0, ''),
(17001, 'The throne room of Stormwind Keep. On the king''s throne sits a tall, beautiful woman in black and gold, very much at her ease; two soldiers in black armour stand below her, and they do not move at all, not even to breathe. The Royal Guard is nowhere to be seen. / "Another hero come to look at me," says Lady Katrana Prestor, warmly. "Do come closer. The Lord Protector always has time for the little people."', '', 1, 0, '', 0, ''),
(17002, 'She is perfect: the voice, the smile, the hands folded just so. But the torchlight throws her shadow up the wall behind the throne, and the shadow is wrong - too long in the neck, and something folded at its shoulders. Her soldiers'' eyes catch the light like a cat''s. Whatever holds Stormwind, it is not a woman, and it has sent away everyone who might have noticed.', '', 0, 0, 'shadow', 0, ''),
(17003, 'A great lady on a great throne. She smiles at you as if you were a child who has wandered in.', '', 0, 0, '', -1, ''),
(17004, '"Bolvar is - resting," she says, and for the first time she has to think about her answer. You keep going: the Guard dismissed, the regent unseen, the Blackwings who never eat or sleep. Somewhere behind you a door opens - the City Guards on the stair have been listening. The Lady looks at them, and at you, and the warmth goes out of her face like a blown candle. "Keep your little city, then," she says softly. "For now." She rises, and her soldiers close about her, and they go out by the king''s private stair, and when the Guard reach the top it is empty.', '', 0, 0, '', 0, '0'),
(17005, '"How tiresome you are." Below her, the black soldiers turn their heads toward you, both at once.', '', 1, 274, '', -1, ''),
(17006, 'You hold it up: a scale as long as your hand, black as a cooled forge, still faintly warm - found where no lizard ever crawled, in the Keep''s own halls. The Lady''s smile does not move, but her eyes do; they go gold, and the pupils narrow to slits, for one heartbeat, before she can stop them. Her soldiers have seen it. So have you. "Clever," she whispers. "Clever little thing." And she simply leaves - down the private stair, unhurried, her black soldiers behind her - as if the throne had never interested her at all.', '', 0, 0, '', 0, '0'),
(17007, 'You lay it out: no confirmation by the Nobles, no seal from the king, no regent''s consent. A Lord Protector who protects nothing but herself. The Lady laughs - and keeps laughing - and then, quite suddenly, stops. "Law," she says. "How very human." She stands. "Then let the Nobles have their chair. I have other errands." She goes, and the Blackwings with her, and nobody sees which way.', '', 0, 0, '', 0, '0'),
(17090, 'The Lady sighs. "Enough." Something vast moves in her shadow on the wall. "Kill it."', '', 1, 15, '', 0, ''),
(17201, 'A walled garden behind the Keep: roses, a fountain, a stone bench. On the bench, reading - or pretending to - sits a thin nobleman in very good clothes. He looks up sharply. / "These are private grounds. Lord Gregor Lescovar does not receive visitors without an appointment. Run along."', '', 1, 0, '', 0, ''),
(17202, 'The roses have been trampled at one end of the bed, and the trampling is recent. In the shadow of the hedge, quite still, someone is crouching - a man in dark leathers and a red bandana, a knife across his knees, watching you. Lescovar isn''t reading. He''s waiting for a meeting, and his guest came early.', '', 0, 0, 'marzon', 0, ''),
(17203, 'Roses. A fountain. A nobleman who very much wants you gone.', '', 0, 0, '', -1, ''),
(17204, 'Lescovar goes white. The man in the hedge doesn''t wait to see how it ends - there''s a rustle, and the hedge is empty. "I - it was only the Keep''s rotas," Lescovar stammers, "nothing important, the Lady never pays us, the Brotherhood at least -" He stops, and puts his face in his hands. "Take it to SI:7, then. I''m finished either way."', '', 0, 0, '', 0, '0'),
(17205, '"Guards!" Lescovar is on his feet, and behind him the hedge moves.', '', 1, 5, '', -1, ''),
(17206, 'He reads the first line and knows his own hand. ''My friends of the Brotherhood - the Keep''s watch changes at the ninth bell -'' Lescovar sits down very slowly on the bench. In the hedge something goes away, fast. "What do you want?" he says at last. "No. Don''t tell me. I know what you want." He takes out a second letter, unsealed, and hands it to you. "Every name. Take it to Shaw."', '', 0, 0, '', 0, '0'),
(17207, 'Lescovar hesitates - and then, with the relief of a man glad to be rid of it, hands you a fat oilcloth packet. "Tell VanCleef this is the last," he hisses. "Tell him I''m done." You walk out of the garden with the Keep''s secrets under your arm, and by nightfall SI:7 has them, and Lescovar is gone from the city.', '', 0, 0, '', 0, '0'),
(17290, 'A whistle from the hedge, and Marzon the Silent Blade steps out, smiling.', '', 2, 15, '', 0, ''),
(17301, 'Outside the city architect''s office, a picket: three big men in mason''s aprons and red bandanas, with painted boards - WE BUILT YOUR CITY, PAY US - and a heap of loose cobbles at their feet that are not there for decoration. The leader plants himself in your path. / "Nobody goes in. Not till the city pays what it owes."', '', 1, 0, '', 0, ''),
(17302, '"We rebuilt Stormwind," says the leader. "After the orcs burned it. Every wall, every arch, every street. Two years'' work. And the nobles voted not to pay us, and the Lady laughed, and the guild''s gone over to Edwin VanCleef and the Brotherhood. We''re the last ones still asking nicely." He hefts a cobble. "Nicely-ish."', '', 1, 0, 'wages', 0, ''),
(17303, 'The leader looks at you for a long time. Then he hands over a battered ledger, every page a name and a number. "Two hundred and six masons," he says. "You tell him every one." You go in. The architect reads it, and goes grey, and signs a draft on the treasury with a shaking hand - and outside the placards go down, one by one.', '', 0, 0, '', 0, ''),
(17304, '"Another one who thinks we''re stupid," says the leader, and the others pick up cobbles.', '', 1, 14, '', -1, ''),
(17305, 'It''s the guild''s own wage-ledger - the city''s copy, with the treasury''s seal on every page, and in the margin of the last one, in a clerk''s neat hand: ''Payment refused by order of the Lord Protector.'' The leader reads it twice. "So it was HER," he says. "Not the guild. Not the architect." He turns his picket round, very deliberately, to face the Keep. "Come on, lads. Wrong door."', '', 0, 0, '', 0, '0'),
(17306, 'You take a hammer and a chisel and set a cobble in the broken step, true and tight, and the masons gather round in spite of themselves. "Who taught you that?" the leader demands - and then he laughs, the first time in two years, by the sound of it. "All right. All right. We''ll talk to him. Nicely."', '', 1, 11, '', 0, ''),
(17390, '"That''s it. Bricks, lads!"', '', 1, 15, '', 0, ''),
(17501, 'On the canal walk, a thin man in a red bandana is counting coins out of a strongbox, and beside him stands the biggest human being you have ever seen, holding the lid. The thin one doesn''t look up. / "Toll''s ten silver for this stretch. Hamhock here collects. Or you can swim - Hamhock likes it when people swim."', '', 1, 0, '', 0, ''),
(17502, 'Hamhock is enormous, and slow, and very proud of being enormous. He keeps glancing at Bazil to see whether he''s doing it right. He''s never lost a fight in his life - you can see it - and he''s never once been asked to fight fair.', '', 0, 0, 'hamhock', 0, ''),
(17503, 'A small man and a very large one. The large one cracks his knuckles.', '', 0, 0, '', -1, ''),
(17504, 'Hamhock beams. Nobody ever asks Hamhock to arm-wrestle. You set your elbows on a crate, and it takes a long, long minute - but his arm goes down, and Hamhock looks at it in wonder. "Fair''s fair, Baz," he rumbles, and picks up the strongbox, and walks off with it, and Bazil has no choice but to follow.', '', 0, 0, '', 0, '0'),
(17505, '"Wrong answer," says Bazil, and Hamhock puts down the lid.', '', 1, 274, '', -1, ''),
(17506, 'Bazil stops counting. The key is the Stockade warden''s own, the big iron one - and Bazil''s brother has been in the Stockade three years. "Where did you get that?" he says, and doesn''t wait for an answer. He snatches it, and slams the strongbox shut, and he and Hamhock are gone down the canal steps before you can say another word.', '', 0, 0, '', 0, '0'),
(17507, 'Bazil goes still. He''s heard what happens to the people the Blackwings sweep up. "...Dark, you say." He''s already packing the strongbox. "Hamhock. We''re moving house."', '', 0, 0, '', 0, '0'),
(17590, '"Hamhock. Swimming lesson."', '', 1, 25, '', 0, ''),
(17601, 'The Slaughtered Lamb''s back room. The tables have been pushed to the walls and a circle chalked on the floorboards, and two robed figures are bent over it with candles, arguing in whispers. They straighten up fast. / "Private function," says the elder, a red-robed man with ink on his fingers. "The bar is upstairs. Go and drink something."', '', 1, 0, '', 0, ''),
(17602, 'It''s a summoning circle - and a big one, far too big for the imps the Lamb''s warlocks usually deal in. It isn''t finished: one arc is left open, the way you leave a door open for a guest. The younger one keeps looking at the gap and swallowing. Somebody paid them to call this, and they''re more afraid of it than you are.', '', 0, 0, 'circle', 0, ''),
(17603, 'Chalk and candles. They watch you look, and don''t like it.', '', 0, 0, '', -1, ''),
(17604, 'The young one breaks first. "I SAID it was too big -" he says, and kicks over a candle, and smears the chalk with his boot. The elder rounds on him - and then looks at the circle, and at you, and lets out a long breath. "...Fine. Fine. The client can find someone else." They gather their things and go up the stairs, and the circle is only chalk again.', '', 0, 0, '', 0, '0'),
(17605, '"Then you can be the first thing it eats," says the elder, and his candle-flame turns black.', '', 1, 25, '', -1, ''),
(17606, 'You lay the iron sigil across the open arc. The chalk smokes. The candles gutter, every one, and from somewhere much further away than the cellar something roars, thwarted, and is gone. The two warlocks stare at the sigil, then at each other. "That," says the younger one faintly, "is a Kirin Tor seal." They leave - quickly - and they don''t come back.', '', 0, 0, '', 0, '0'),
(17607, 'You name it - its true name, and the price its kind always take: the summoner, first. The elder''s face changes. He didn''t know. Whoever hired them didn''t tell them. "...We''re leaving," he says, and they do, and he stops at the door to say, quietly, "The client wore black and gold."', '', 0, 0, '', 0, '0'),
(17690, 'The elder spits a word, and the chalk circle flares violet.', '', 1, 15, '', 0, ''),
(17701, 'In an alley off Old Town a lean man in grey leathers is leaning on the wall as if he''d always been there. He has a knife in each boot and doesn''t bother to hide either. / "You''re the new one. Don''t look so surprised - the whole city knows you came through the gate. SI:7 has a job for someone nobody knows."', '', 1, 0, '', 0, ''),
(17702, '"The Lady," says Renzik, very quietly, "is not a lady. We know it. We can''t prove it - not to the Archbishop, not to the Nobles. Every agent we send near the Keep doesn''t come back. But a stranger, running an errand to the Cathedral with a sealed letter, who''d notice? You''d be doing your city a service. You''d also be doing it for free." He grins.', '', 1, 0, 'offer', 0, ''),
(17703, '"Good." A sealed letter goes from his sleeve to your hand. "Archbishop Benedictus. Nobody else. If anyone in black and gold asks, you''re delivering a sermon." He''s gone before you look up.', '', 0, 0, '', 0, '0'),
(17704, 'He sees the brass cipher-wheel and stops grinning. "That''s Shaw''s. That''s from the dead drop under the canal bridge - nobody knows that drop." He looks at you with new respect, and something like alarm. "All right. You''re in. Bring that to the Cathedral with this," - a letter - "and then forget my face."', '', 0, 0, '', 0, '0'),
(17705, 'He laughs, delighted. "Three streets back, the beggar with the good boots. Not bad." He pushes off the wall. "You''ll do. When the time comes, SI:7 will remember you." And he''s gone, and so is the beggar with the good boots.', '', 0, 0, '', 0, '0'),
(17706, '"Testing you? Friend, if I were testing you, you''d have failed already."', '', 1, 11, '', -1, ''),
(17790, '"Pity. Can''t have you remembering my face, then." Both knives come out of his boots.', '', 1, 15, '', 0, ''),
(17801, 'In a corner of the Dwarven District three dwarf mountaineers have made a camp of crates and bedrolls, and they have their rifles across their knees. All three come up at once when they see you. / "That''s close enough. Who sent you? The regent? The Lady? We''re not going back, and we''re not going quietly."', '', 1, 0, '', 0, ''),
(17802, '"Ironforge," says the eldest, as if the word tastes of ash. "The king''s a statue and Moira Thaurissan sits on his throne, and when the Anvilrage came for the old Mountaineer companies, we ran. Thought Stormwind would take us in. Then we got here and found the same rot on the throne, just with nicer manners." He looks at his rifle. "So we sit. And we wait. And we jump at shadows."', '', 1, 0, 'fled', 0, ''),
(17803, 'The rifles come down. "...Aye," says the eldest. "Aye, that''s all we''re asking." They give you their names, and their companies, and the name of a captain in Thelsamar who''ll vouch for them, and for the first time since you walked up, they sit back down.', '', 0, 0, '', 0, ''),
(17804, 'They know it on sight - every dwarf in Khaz Modan would. The Bronzebeard signet, warm from your pocket. The eldest takes it in both hands and holds it to his brow. "You''ve been in the city," he says. "You stood in the throne room. Then there''s hope." He gives it back, carefully. "When you go back, tell them the Third Company is waiting for the word."', '', 0, 0, '', 0, ''),
(17805, 'You tell them: the factions, the loyalists, the regent who is less sure of her throne than she looks. They listen like men drinking water. "Then it''s not over," the youngest says. The eldest nods slowly. "Not over. Right." They put the rifles away.', '', 0, 0, '', 0, ''),
(17806, '"You don''t know anything," the eldest snaps. "You''re guessing."', '', 1, 274, '', -1, ''),
(17890, '"She sent you. I KNEW she''d send someone." The rifles come up.', '', 1, 15, '', 0, ''),
(18001, 'On a bench outside the House of Nobles sits a Dark Iron dwarf in court finery, a rolled treaty in his lap, and behind him stands a bodyguard built like a furnace door. The envoy looks up with a diplomat''s smile. / "A citizen! How charming. I am here on behalf of Her Majesty the Regent of Ironforge, to present our friendship to the Lord Protector. One regent to another. You''ll excuse me - I''m expected."', '', 1, 0, '', 0, ''),
(18002, 'He''s been expected for three days, by the look of the crumbs on the bench. He keeps glancing up at the Keep, and every time he does, he grips the treaty a little tighter. He''s seen the Blackwings. He''s smelled the throne room. The envoy is terrified of the friend he''s been sent to make - and he daren''t go home without the treaty signed.', '', 0, 0, 'unwilling', 0, ''),
(18003, 'A dwarf and his treaty. The bodyguard''s knuckles crack like kindling.', '', 0, 0, '', -1, ''),
(18004, 'The smile slips. "She - the Regent - wanted allies," he says, very low. "Anyone. Ironforge is hers by a thread." He looks at the Keep again. "But that... that isn''t an ally. That''s a mouth." He rolls up the treaty and puts it away. "I will tell her. Every word. Bruegal - we''re going home."', '', 0, 0, '', 0, '0'),
(18005, '"I think we''re done talking," says the envoy, and the bodyguard steps forward.', '', 1, 274, '', -1, ''),
(18006, 'He knows the seal - Moira''s own, the black anvil and the crown - and breaks it with shaking hands. It''s the dispatch that should have reached him a week ago: ''Make no treaty. The woman in Stormwind is not what she seems. Come home.'' The envoy reads it three times, and then laughs, a high, cracked laugh of pure relief. "Bruegal! Pack the bags!"', '', 0, 0, '', 0, '0'),
(18007, 'The envoy looks at you, and at the empty square, and at the Keep. He has no protection here at all, and he knows it. "...A diplomat knows when he is not welcome," he says stiffly, and goes, and his bodyguard goes with him, glaring.', '', 0, 0, '', 0, '0'),
(18090, '"Bruegal. Remove this person."', '', 1, 25, '', 0, ''),
(18301, 'The Pig and Whistle in Old Town, and a fight about to happen: a huge, very drunk man and a grizzled old soldier nose to nose in the middle of the floor, and everyone else edging toward the walls. / "THIEF!" roars the drunk. "He took my ring! My WEDDING ring!" The old soldier squares up. "Say that again, Bartleby. Go on."', '', 1, 5, '', 0, ''),
(18302, 'The tavernkeeper wrings a cloth. "Bartleby lost his wedding ring - again - and Harry''s wearing a ring on a string, and Bartleby''s decided it''s his. It isn''t. Harry''s had that since the Second War. Nobody can get Bartleby to listen, and Harry won''t show him, on principle."', '', 0, 0, 'ring', 0, ''),
(18303, 'You point at the string round Harry''s neck. Harry glares - and then, grudgingly, pulls it out: a soldier''s ring, a regiment''s crest, nothing like a wedding band. Bartleby stares at it. "...Oh," he says. His great shoulders sag. "Oh. Sorry, Harry." Harry buys him a drink. The room breathes out.', '', 2, 0, '', 0, ''),
(18304, '"Stay out of it!" they both shout at once.', '', 1, 14, '', -1, ''),
(18305, 'Bartleby sees the ring in your palm and goes perfectly still. Then he picks it up as if it might break, and puts it on, and bursts into tears, and hugs Harry, who puts up with it. "Drinks are on Bartleby," the tavernkeeper announces, to cheers, and Bartleby is too happy to argue.', '', 1, 0, '', 0, ''),
(18306, 'By the second verse Bartleby is singing along. By the third, so is Harry, despite himself. By the end the whole tavern is roaring the chorus and nobody remembers what the fight was about.', '', 1, 11, '', 0, ''),
(18390, 'Bartleby swings. Harry ducks. You''re in the way.', '', 1, 15, '', 0, ''),
(19101, 'At the mouth of Fargodeep Mine, on a ledge above the cart-track, a big kobold with a whip and a candle on his head is screaming at two miners hauling ore. He sees you and points the whip. / "YOU! You no take candle! Narg see you looking at candle! Nobody take Narg''s candle!"', '', 1, 25, '', 0, ''),
(19102, 'The miners aren''t working because Narg shouts. They keep glancing back down the shaft, into the dark, and every so often a sound comes up out of it - a long, low scraping, like something very big turning over in its sleep. They''ve dug too deep. Narg''s shouting because he''s scared too.', '', 0, 0, 'deep', 0, ''),
(19103, 'Kobolds, a cart, and a lot of shouting. The candle wobbles.', '', 0, 0, '', -1, ''),
(19104, 'Narg goes quiet. The miners look at him. "...Big thing," Narg says at last, much smaller. "Big thing below. Eat Grik. Eat Tobb." He sniffs. "You go. You fight big thing. Narg keep kobolds in mine. No farms." He holds out a grubby paw to shake. It''s the most solemn thing you''ve ever seen.', '', 1, 0, '', 0, ''),
(19105, '"NO! Lies! You want CANDLE!" Narg cracks the whip.', '', 1, 274, '', -1, ''),
(19106, 'Narg''s eyes go huge. It''s a proper candle - fat, white, Goldshire-made, the kind kobolds dream about. He takes it with both paws as if it were a crown. "...For Narg?" You nod. The miners crowd round to look. Nobody cares about the farms any more. Nobody cares about anything but the candle.', '', 1, 0, '', 0, ''),
(19107, 'You reach for his candle. Narg shrieks, clutches it to his head with both paws, and bolts down the shaft, and his miners go after him, and the farms of the Fargodeep road have a quiet night.', '', 0, 0, '', 0, '0'),
(19190, '"CANDLE THIEF!" Narg shrieks, and the miners come at you with picks.', '', 1, 15, '', 0, ''),
(19301, 'At the forest''s western edge, a gnoll camp: hides on poles, a cold firepit, and three Riverpaw gnolls who come up snarling. The biggest, grey-muzzled, holds the others back with one paw. / "Man-thing. This Hogger''s forest. You go now, or Gruff tells Hogger, and Hogger eats you."', '', 1, 15, '', 0, ''),
(19302, 'They''re thin. All three of them - ribs showing through the fur, the runts worst of all. There''s a fresh kill hanging in the camp, but it''s untouched, and it''s marked with Hogger''s sign: his. The pack hunts; Hogger eats; the pack starves. Gruff keeps looking at the kill.', '', 0, 0, 'hungry', 0, ''),
(19303, 'Three gnolls with spears. None of them blinks.', '', 0, 0, '', -1, ''),
(19304, 'Gruff looks at the kill for a long time. Then he takes it down, and tears it in three, and gives the biggest pieces to the runts. "...West," he says. "Westfall. Good hunting, no Hogger." He picks up his spear. "You tell Hogger Gruff gone. Tell him Gruff say: eat your own bones." The pack goes.', '', 0, 0, '', 0, '0'),
(19305, '"Man-thing talks too much," Gruff growls, and lets go of the runts.', '', 1, 274, '', -1, ''),
(19306, 'It''s the old totem - the skull and feathers the Riverpaw carried before Hogger came, the one Hogger threw in the river. Gruff drops his spear. The runts whine and crowd round it. "Old pack," Gruff says, very softly. "Before Hogger." He takes it from you, and holds it high, and the three of them go off into the trees together, singing - if gnolls can be said to sing.', '', 0, 0, '', 0, '0'),
(19307, 'You show your teeth and hold his eye, and hold it, and hold it - and Gruff looks away first. The runts see it. In gnoll terms you''ve just won the argument, and possibly the pack. Gruff grumbles something and leads them off into the forest, west, away from the farms.', '', 0, 0, '', 0, '0'),
(19390, '"Enough talk! Hogger''s forest!" The pack attacks.', '', 1, 15, '', 0, ''),
(19601, 'Where the stream runs out of Crystal Lake, three murlocs have come up onto the bank. Two crouch over the water with spears; the third, taller, with shells braided into its fins, raises a staff of driftwood and gurgles at you, very loudly. / "MRRRGLL! Mrgl mrgl - NRGLLL!"', '', 1, 5, '', 0, ''),
(19602, 'They''re fishing. Badly. The stream''s fished out - there''s a dead weir of farmers'' nets across it lower down - and the two with spears are thin as reeds. The tidecaller is shouting at you, but it keeps looking at your pack. It can smell your food from here.', '', 0, 0, 'starving', 0, ''),
(19603, 'You set out what you have on a flat stone and step well back. For a long moment nothing happens. Then the smallest murloc darts in, grabs, and darts back - and then all three are eating, and gurgling, and the tidecaller makes a sound at you that is very nearly polite. When they go back into the lake, they leave a ring of pretty pebbles on the bank, for you.', '', 0, 0, '', 0, '0'),
(19604, 'The tidecaller freezes. Then it throws back its head and makes a noise like a kettle - delight, you think - and snatches the charm and presses it to its forehead, and the others bow. Whatever it is, it matters to them more than the stream. They take it back down into the lake, and you never see them on the bank again.', '', 0, 0, '', 0, '0'),
(19605, 'You puff up, and gurgle, as deep and wet and rude as you can manage. The murlocs stare. Then the tidecaller gurgles back - and you answer - and it goes on for some time - and finally it lowers its staff and leads the others back into the lake, looking over its shoulder at you with something like respect.', '', 1, 0, '', 0, ''),
(19606, 'Whatever you just said in Murloc, it wasn''t good. The spears come up.', '', 1, 14, '', -1, ''),
(19690, '"MRRRAAAGL!" The tidecaller points its staff, and the spears come at you.', '', 1, 15, '', 0, ''),
(19701, 'At a bend in the road above Goldshire, a woman in a red bandana sits on a fence-rail, swinging her boots, while two lookouts lounge nearby with crossbows. She smiles like a cat. / "Well now. Another traveller on the Brotherhood''s road. There''s a toll, of course. But you look interesting. Interesting people pay in other ways."', '', 1, 0, '', 0, ''),
(19702, 'She''s good - easy, charming, dangerous. But her purse is too heavy for a road-toll collector''s, and her boots are new Stormwind leather, and when she speaks of ''the Brotherhood'' her mouth twists. She''s skimming. A lot. And she''s afraid of the day VanCleef counts the takings.', '', 0, 0, 'skimming', 0, ''),
(19703, 'A pretty smile and two crossbows.', '', 0, 0, '', -1, ''),
(19704, 'The smile freezes. For a second she looks at her lookouts, wondering how much they''ve heard. "...You''re bluffing," she says. Then: "But I wasn''t planning on staying in Elwynn forever." She hops off the fence and goes, fast, with her heavy purse - and her lookouts go after her, shouting for their share.', '', 0, 0, '', 0, '0'),
(19705, '"And here I thought you were interesting." She snaps her fingers. The crossbows come up.', '', 1, 274, '', -1, ''),
(19706, 'She reads the orders - VanCleef''s own hand, a list of collectors to be ''retired'' for theft, her name the first on it - and laughs, not happily. "Well. That settles it." She tears the paper up and lets it blow away. "Tell anyone who asks that Morgaine the Sly went to Booty Bay and took up knitting." She''s gone before you can answer, and her lookouts are too confused to follow.', '', 0, 0, '', 0, '0'),
(19707, 'You look past her, to the older lookout who hasn''t said a word - the one Morgaine keeps glancing at - and you address him instead. He grins, and nods, and makes a sign. "Let ''em through, Morgaine. Brotherhood''s got bigger fish." She glares, but she lets you go - and that night the post is abandoned.', '', 0, 0, '', 0, '0'),
(19790, '"Shame," says Morgaine, and the crossbows fire.', '', 1, 15, '', 0, ''),
(19901, 'In a clearing south of the river, two Defias in mage''s robes are working over a circle of stones. The air above it shimmers and crackles, and frost keeps forming on the grass. One looks up, irritated. / "We''re not open for business. Come back tomorrow. Or don''t. Spells for hire - fair rates - but not today."', '', 1, 0, '', 0, ''),
(19902, 'The circle''s wrong. One of the ward-stones has cracked, and the power that should be going round is leaking out of the gap - that''s the frost. Every time they cast, it gets worse. The younger wizard''s fingertips are already white with frostbite. They learned at Azora, and left before they''d finished learning.', '', 0, 0, 'unstable', 0, ''),
(19903, 'Stones in a ring. Something hums. They want you gone.', '', 0, 0, '', -1, ''),
(19904, 'The younger one looks at her hands, and then at her partner. "...He would," she says. "Theocritus always said we''d come crawling back." The elder sighs. "Better crawling than handless." They kick the stones apart and set off down the road toward the Tower, arguing all the way.', '', 0, 0, '', 0, '0'),
(19905, '"Everyone''s an expert," snaps the elder, and frost runs up his staff.', '', 1, 14, '', -1, ''),
(19906, 'They know the seal - every apprentice at Azora does. Theocritus''s own, and with it a pardon, unsealed, never sent: ''Come home. All is forgiven. Bring the good teapot.'' The elder reads it twice and sits down on a ward-stone. "The teapot," he says faintly. "He remembered the teapot." They pack up that hour.', '', 0, 0, '', 0, '0'),
(19907, 'You kneel and set the cracked stone right, and trace the broken line closed. The shimmer steadies; the frost melts. The two wizards stare at you. "Where did you study?" the elder demands. You don''t answer. He grumbles, but he packs up the circle and leaves the road alone after that.', '', 0, 0, '', 0, '0'),
(19990, '"Fine. Free sample." The air goes white with frost.', '', 1, 15, '', 0, ''),
(20401, 'In the vineyard below Northshire Abbey, a lanky man in a red bandana is sitting on a wine barrel, eating grapes, while two thugs pull the vines about. He waves a bunch at you. / "Garrick Padfoot, proprietor. Brotherhood property now, this. Tasting''s free. Everything else costs."', '', 1, 0, '', 0, ''),
(20402, 'The vines are being ruined, not harvested. And up the valley, through the trees, you can see the Abbey''s bell-tower - close enough that a shout would carry. Garrick keeps one eye on it. He''s set up camp in sight of the Abbey''s walls, and he knows exactly how bad an idea that is.', '', 0, 0, 'abbey', 0, ''),
(20403, 'Grapes, barrels, and a man who thinks he''s funny.', '', 0, 0, '', -1, ''),
(20404, 'Garrick stops chewing. He looks at the bell-tower. "...The Marshal," he says. "McBride." He spits out the grapes. "Lads. Lads! We''re leaving." They go, at a run, and leave the barrel and the grapes behind.', '', 0, 0, '', 0, '0'),
(20405, '"I think that''s enough free tasting," says Garrick, and drops off the barrel.', '', 1, 274, '', -1, ''),
(20406, 'It''s the vineyard''s deed, under the Abbey''s seal, made over to the old vintner''s daughter - the girl the Brotherhood told she''d lost it. Garrick reads it and his ears go red. "She said it was hers. I told the lads she was lying." He gets up. "...I''m a thief. I''m not a thief of orphans." He takes his thugs and goes.', '', 0, 0, '', 0, '0'),
(20407, 'You walk right up to him, close, and say nothing at all. Garrick stops smiling. His thugs stop pulling vines. "...Right," he says. "Right. Harvest''s over, lads."', '', 0, 0, '', 0, '0'),
(20490, '"Tasting''s over." Garrick draws, and his thugs come at you.', '', 1, 15, '', 0, ''),
(7501, 'A troll in a mask of bark and feathers dances round a fire inside a ring of stones, rattling a gourd. Two warriors watch the hills. On the flat stone in the middle of the circle lies a little bundle of straw and cloth, and a lock of fair human hair is tied round its neck. / "Closer, closer, little farmer. Your shadow is mine now - and soon de rest of you will come walking after it."', '', 1, 0, '', 0, ''),
(7502, 'The bundle on the stone is a doll, and the hair on it belongs to somebody at the Dabyrie farm. Every time the witch doctor rattles his gourd, the doll''s shadow stretches toward him across the stones - further than the firelight could throw it. Break the doll''s place in the circle and whatever he''s pulling on comes loose. The warriors keep their eyes on the hills, not on the stone.', '', 0, 0, 'shadow', 0, ''),
(7503, 'The doll goes tumbling out of the ring in a spray of sparks. The fire gutters blue, then out. Somewhere far off across the farmland, a dog starts barking. The witch doctor stares at the empty stone - and his warriors stare at him, and back away, making signs against bad luck. He shrieks at them, and they run, and after a moment he runs too.', '', 0, 0, '', 0, '0'),
(7504, 'The witch doctor stops dancing. "You," he says, pointing the gourd. "De loa want a second shadow."', '', 1, 25, '', -1, ''),
(7505, 'You speak, and the fire leans away from you. The warriors feel it; one of them takes a step back. Vol''mun laughs - and keeps laughing a moment too long. "...Dis is not your loa''s circle," he says, but the gourd is still, and the shadow on the stones has stopped stretching. He snatches up the doll and slips off into the dark, and the warriors are glad to follow.', '', 1, 0, '', 0, '0'),
(7506, 'He sees what you''re holding before you snap it - his own fetish, the one that marks him as Witherbark''s doctor - and he screams. The crack of the wood goes through the circle like a dropped plate. The fire dies. The doll on the stone is just straw. The warriors look at Vol''mun, and for the first time they look at him the way you''d look at a man who has been robbed of everything. He goes without a word.', '', 0, 0, '', 0, '0'),
(7590, '"Enough." Vol''mun throws a fistful of powder in the fire and it flares green. "Take it!"', '', 1, 15, '', 0, ''),
(7701, 'Three ogres stand in a triangle outside a stockade of sharpened logs, throwing a kobold between them. The kobold is shrieking. The ogres are having a lovely time. The biggest one sees you and stops, with the kobold held upside down by one leg. / "Little one want to play?"', '', 1, 11, '', 0, ''),
(7702, '"ME boss," says the biggest one, at once. "Me boss," says the next biggest, a moment later - and then they both look at each other, and the third ogre looks very carefully at the sky. Clearly this has come up before, and never been settled.', '', 0, 0, 'two_bosses', 0, ''),
(7703, '"Wrong?" The biggest ogre looks at the kobold, then at you. "How is wrong?" You explain that a kobold thrown *underhand* goes much further. They try it. It does. The kobold sails over the stockade, lands in a bush, and is never seen again - and the ogres are so impressed with this new game that they follow it into the hills to find another one.', '', 0, 0, '', 0, '0'),
(7704, 'The biggest ogre drops the kobold on its head. "Little one is not funny."', '', 1, 14, '', -1, ''),
(7705, 'The second ogre''s face goes slowly purple. "...You say WHAT?" The biggest ogre opens his mouth to deny it, and is hit with a club before he gets there. The kobold scrambles away while they roll in the dirt, and the third ogre, very sensibly, sits down to watch. It is still going on when you are out of sight.', '', 0, 0, '', 0, '0'),
(7706, 'You set the tin crown on your head. All three ogres go perfectly still. They do not know what a crown is for, exactly, but they know who wears one: the boss of bosses. The biggest one puts the kobold down very gently, and pats it on the head. Then all three bow - badly - and back away into the stockade.', '', 0, 0, '', 0, ''),
(7707, 'The kobold flies. You leap, and catch it out of the air, and land, and set it on its feet. The kobold runs. The ogres stare at you with new respect - and then, slowly, at each other. "Little one... good at game," says the biggest. "Better than ME." The second ogre snorts. Clearly the question of who is boss has just got more complicated.', '', 1, 273, 'two_bosses', 0, ''),
(7790, '"New game," says the biggest ogre, and drops the kobold. "Throw little one."', '', 1, 15, '', 0, ''),
(7801, 'At the end of Boulderfist Hall, on a chair made from a cart, sits the biggest ogre you have ever seen, with a slate in one hand and a stub of chalk in the other. A shaman and a guard stand either side of him. He looks up from his sums - they are wrong - and fixes you with one small, clever eye. / "Or''Kalar is learning to be smart. You are interrupting the learning."', '', 1, 0, '', 0, ''),
(7802, '"Ogres are strong," says Or''Kalar. "Humans are weak and they have castles. Or''Kalar wants to know why. So the Syndicate man comes and teaches Or''Kalar to count, and to read, and Or''Kalar gives him gold and lets his men walk past the hall." He holds up the slate proudly. You notice the tutor isn''t here. You notice, too, that the gold went one way and the lessons don''t seem to be going anywhere.', '', 1, 0, 'tutor', 0, ''),
(7803, 'You give him one: what has a neck and no head, two arms and no hands? He thinks about it for a very long time. The guard thinks about it. The shaman thinks about it. Then Or''Kalar''s face splits into a huge grin and he roars "SHIRT!" and bangs the slate on the arm of the chair. "Or''Kalar IS smart. The teacher says so. The teacher says so every time Or''Kalar pays him." He says it proudly. You notice that the teacher isn''t here.', '', 1, 11, 'tutor', 0, ''),
(7804, 'Or''Kalar puts down the chalk. "Or''Kalar is learning that some little ones talk too much."', '', 1, 274, '', -1, ''),
(7805, 'Or''Kalar''s eye narrows. He is slow, but he is not stupid, and he has been wondering the same thing. "Bring the teacher," he says quietly, and the guard goes. When he comes back he is carrying a human by the collar, and the human''s pockets are full of Boulderfist gold and a letter to Stromgarde. Or''Kalar reads it - slowly - and then looks at you. "Or''Kalar learns a new word today." He does not say which one. You leave before he shows the tutor.', '', 1, 0, '', 0, ''),
(7806, 'He reads it with his finger, mouthing every word, and you watch his face change at each line - ''the ogre is a fool'' - ''keep him counting'' - ''when Stromgarde falls, we won''t need him''. When he reaches the end he folds it, very carefully, and puts it inside his shirt. "Or''Kalar has a lesson for the Syndicate," he says, and stands, and the whole hall shakes. He doesn''t look at you again on the way out. He has somewhere to be.', '', 1, 0, '', 0, '0'),
(7807, 'It''s a long, long silence. Or''Kalar looks at you; you look at Or''Kalar. Then he writes something on the slate - a large, wobbly word - and turns it to show you. It says SCARED, spelled wrong. He grins. "Or''Kalar is not. But Or''Kalar is SMART." And he lets you go.', '', 1, 11, '', 0, ''),
(7890, 'Or''Kalar throws the slate at the wall. "No more learning. SMASHING."', '', 1, 15, '', 0, ''),
(7901, 'A farmer''s cart stands across the road, its horse shivering. Three Syndicate men surround it - one going through the sacks, one on the road with a hand crossbow, one up the bank with a bow. The farmer has already run. The one with the crossbow sweeps a bow to you, smiling. / "Toll road, friend. Same price for everyone: everything."', '', 1, 2, '', 0, ''),
(7902, 'The leader is enjoying himself. The archer is watching the road behind you, nervous. And the hired sword going through the sacks keeps glancing at the leader''s purse - a fat one - and then at his own empty belt. Somebody hasn''t been paid in a while.', '', 0, 0, 'unpaid', 0, ''),
(7903, 'Three of them, one of you. That''s about as far as you get before the crossbow comes up.', '', 0, 0, '', -1, ''),
(7904, 'The archer is down the bank before you finish, staring up the road. The leader hesitates - and in that moment, from somewhere behind the hill, a horse whinnies. It''s only the farmer''s horse. It''s enough. "Leave it!" The three of them are into the trees, and the cart is yours to drive back to Refuge Pointe.', '', 0, 0, '', 0, '0'),
(7905, 'The leader''s smile doesn''t move. "That''s a no, then." The crossbow comes level with your chest.', '', 1, 274, '', -1, ''),
(7906, 'The hired sword straightens up slowly from the sacks. "...Three weeks," he says. The leader laughs, a bit too loud. "You''ll get your share -" "Three WEEKS." The sword is out, but it''s not pointed at you. The archer slips away into the trees. A moment later, the leader follows - at a run, his purse a good deal lighter than it was.', '', 0, 0, '', 0, '0'),
(7907, 'The leader looks at his own face, drawn in charcoal, and the reward written under it in red ink, and so do the other two. The sum is large. The two of them look at each other, then at their leader, and you can see the arithmetic happening. The leader sees it too. He backs away up the road with the crossbow on them, not you - and as soon as he''s out of sight, they go after him.', '', 0, 0, '', 0, '0'),
(7990, '"Shame," says the leader, and nods to the archer on the bank.', '', 1, 25, '', 0, ''),
(8101, 'High in the ruins of Stromgarde Keep, a woman in a grey Syndicate cloak kneels before a vault door, working at a ward of pale blue light with a silver knife. Her apprentice holds a lantern for her. She doesn''t look round. / "If you''re Ravenholdt, you''re too late. If you''re Stromgarde, you''re far too late. If you''re neither - go away, I''m counting."', '', 1, 0, '', 0, ''),
(8102, 'A blood-ward: old, strong, and keyed to the Trollbane family - it will open for them and only them, and it punishes everyone else who tries. She''s managed to peel back three of its seven layers, and the effort has drawn her face grey. Her hands shake. She''s been at this for days, and she''s tired - of the ward, of the cold, of the Syndicate.', '', 0, 0, 'weary', 0, ''),
(8103, 'A pretty light on a door. You stare at it until your eyes water, and she clicks her tongue at you.', '', 1, 0, '', -1, ''),
(8104, 'Her knife stops. She looks at the ward, then at the hill under her knees, then at you. "...You''re bluffing," she says. A long pause. "You''re probably bluffing." She doesn''t want to bet the hill on probably. She gets up, very slowly, pockets the knife, and walks away down the stairs, with her apprentice scrambling after her.', '', 1, 0, '', 0, '0'),
(8105, 'She stands, and the silver knife comes round to point at you. "Witnesses," she sighs, "are the worst part of this job."', '', 1, 274, '', -1, ''),
(8106, 'The moment the ring touches the ward, the whole door lights up gold, and the layers she peeled away knit themselves back together in a blink. She snatches her hand back from it, swearing. Days of work, gone. She looks at the ring, at you, and something in her shoulders gives up. "Trollbane''s ring. Of course it is." She laughs, once, without humour. "I''m going home." She means it.', '', 1, 0, '', 0, '0'),
(8107, 'She sits back on her heels and looks at the ward for a long time. "Do you know how much they pay me?" she says at last. "Nothing. They pay me nothing, and they call it a share." She gets up, pulls off the grey cloak, drops it on the vault steps, and walks away down the stairs in her shirtsleeves. Her apprentice looks at the cloak, at you, and runs after her.', '', 1, 0, '', 0, '0'),
(8190, '"I warned you." She turns from the ward with frost already curling off her fingers.', '', 1, 15, '', 0, ''),
(8201, 'At the mouth of a tunnel cut into the hillside, three kobolds huddle round one candle, shaking. Their picks are thrown down in the dirt. From somewhere deep in the tunnel comes a low, slow, booming sound - and every time it comes, all three of them shriek. The one with the measuring rod sees you. / "You! You big! You go see what VOICE wants! You not take candle!"', '', 1, 0, '', 0, ''),
(8202, 'You go a little way in and listen. The tunnel opens into a dwarven hall - very old, the stone smooth as glass - and the ''voice'' is the wind across a broken air-shaft, booming round the hall like a drum. Every sound the kobolds make comes back to them louder. Including their own screaming.', '', 0, 0, 'echo', 0, ''),
(8203, 'You call a word down the tunnel, and it comes back to you, and again, and again. The kobolds stare. One of them tries it - "...hello?" - and the hall answers "hello, hello, hello." The surveyor''s ears go up. The next moment all three are taking turns shouting rude words down the tunnel and laughing, and then they pick up their picks and go back to work, and seem to have forgotten you entirely.', '', 0, 0, '', 0, ''),
(8204, 'The surveyor''s whiskers flatten. "You lie! VOICE angry now! Because of YOU!"', '', 1, 14, '', -1, ''),
(8205, 'Your voice rolls down the tunnel and comes back like the mountain itself speaking. LEAVE... leave... leave. The kobolds are gone before the last echo fades - picks, candle and all. You hear them for some time, squeaking away down the hillside.', '', 0, 0, '', 0, '0'),
(8206, 'The horn''s note goes down the shaft and the old hall takes it and makes it enormous: a long, deep dwarven call that shakes dust from the roof. The kobolds throw themselves flat. When it fades, they look at you as if you''d tamed a dragon. The surveyor presses his measuring rod into your hands like a holy relic, and the three of them back away down the hill, bowing.', '', 0, 0, '', 0, '0'),
(8207, 'You hold out a candle. The kobolds go quiet. The surveyor takes it, sniffs it, holds it up to his own - two flames now. Twice the light. Whatever is in the tunnel matters a great deal less with twice the light. They gather up their picks and go deeper, holding the candles high, and you hear them singing.', '', 0, 0, '', 0, '0'),
(8290, 'The voice booms again and the kobolds break - but towards you, picks up, shrieking, as if you were the thing in the dark.', '', 1, 15, '', 0, ''),
(8501, 'In a circle of carved stones on the hillside, two figures of living water heave and crash against nothing, as if the air at the circle''s edge were glass. One stops when it sees you. Its voice is the sound of surf on shingle. / "Mortal. Mortal. Break the ring. Let us go home to the sea."', '', 1, 0, '', 0, ''),
(8502, '"The Shadowmages. Long ago, when the kings still ruled here. They called us up from the deep water to fight for them, and bound us in these rings so we could not go back. They are all dust now." It strikes the edge of the circle again, and you see the crack it has worn in one of the stones over all those years. One more rune unbroken, and that''s all that holds it.', '', 1, 0, 'unbound', 0, ''),
(8503, 'You scrape your boot across the last rune and the circle goes dark. For a moment nothing happens. Then the two of them pour over the stones like a wave breaking, down the hill, across the grass, and away east toward the sea. The last thing you hear is the sound of surf, though the sea is miles off.', '', 0, 0, '', 0, '0'),
(8504, 'You find the broken lines and chalk them whole. The circle flares. The two exiles shrink into themselves, smaller and slower, until they''re two quiet pools in the bottom of the ring - held, now, for another hundred years. You don''t feel good about it. But they won''t trouble anyone.', '', 0, 0, '', 0, ''),
(8505, 'The circle flares the wrong way. The exiles howl, and for a moment the air at the edge of the circle bends outward toward you.', '', 1, 15, '', -1, ''),
(8506, 'You set the rune-stone in the gap, but you turn it - the way the old marks on it show - so that it opens the circle instead of closing it. The two exiles go still. Then the larger one bows, all the way down, until it is just water on the grass, and the water runs away downhill toward the sea, singing. The second follows.', '', 0, 0, '', 0, '0'),
(8590, 'The circle cracks right through. The exiles come out of it - but they have been caged too long to know friend from jailer.', '', 1, 15, '', 0, ''),
(20601, 'A balcony over the Magic Quarter, rimed with frost. A gaunt figure in faded violet robes leans on the rail, looking down at nothing. The robes were Kirin Tor once; the man in them has been dead a long time. He speaks without turning round. / "Living things. Here. How novel." Frost creeps out from his feet across the stones toward you. "Bethor Iceshard. Late of Dalaran. Very late. What do you want?"', '', 1, 0, '', 0, ''),
(20602, 'Among the frost on the balcony: a dried violet flower pressed under a stone, a cracked Kirin Tor brooch, a chalk outline on the wall that is - you look again - the skyline of Dalaran, drawn over and over, each one a little less sure than the last. He still remembers. He is trying very hard not to.', '', 0, 0, 'dalaran', 0, ''),
(20603, 'Frost, a rail, a dead man in old robes. The cold is getting into your fingers.', '', 0, 0, '', -1, ''),
(20604, 'At the name, Bethor''s shoulders go stiff. For a long moment there is only the drip of the canals below. "He made me an archmage''s apprentice," he says at last, very quietly. "He died at the Violet Citadel, and I died in the street outside, and I came back and he didn''t." The frost on the stones begins, slowly, to melt. "Go on, then. Do whatever you came to do. I find I don''t care to stop you." He turns back to his view, and when you look again the balcony is empty.', '', 0, 0, '', 0, '0'),
(20605, '"Tiresome." The frost on the stones thickens, and climbs.', '', 1, 274, '', -1, ''),
(20606, 'He takes the little book as if it might bite. It''s his own hand, from before: lecture notes, a list of books to borrow, a page of bad poetry about a girl in the Eventide quarter. Bethor reads the poem twice. Then he laughs - a cracked, dusty sound nobody has heard in this city for years. "Terrible," he says. "Truly terrible. Thank you." He tucks the book into his robe. "Whatever you''re here for - I didn''t see you. I was reading."', '', 0, 0, '', 0, '0'),
(20607, 'You trade cantrips across the balcony the way apprentices once did in Dalaran''s courtyards - a spark here, a shimmer of frost there, a flourish for style. Bethor''s answers are sharp, and old-fashioned, and beautiful; yours hold. At the end he bows, stiffly, the full Kirin Tor bow nobody makes any more. "{{Well cast, colleague|Not bad, for someone who swings things}}," he says. "I''d forgotten. Go on - I won''t stand in your way."', '', 0, 0, '', 0, '0'),
(20690, '"Enough." Bethor turns at last, and his eyes are two chips of blue ice. "I''ll add you to the view."', '', 1, 15, '', 0, ''),
(20801, 'A long hall in the Rogues'' Quarter, hung with black cloth. Two agents in Deathstalker leathers stand by the practice dummies, hoods up, very still. Their captain, an executor with a long pale face, looks you over without hurry. / "The living don''t walk the Undercity, so you must be lost. Or very stupid. Executor Zygand. Speak, before my agents decide which."', '', 1, 0, '', 0, ''),
(20802, 'The agents keep their sleeves pulled down, but one of them reaches for a dagger and the cuff rides up: the dead grey skin of his wrist is blistered green, in neat rows, the way a needle leaves marks. Testing marks. The other one has them too, and scratches at them when she thinks nobody''s looking. Whoever''s been trying out new brews on the queen''s own knives, it isn''t the enemy.', '', 0, 0, 'scars', 0, ''),
(20803, 'Two hooded agents, one executor, and a hall that smells of oil and steel.', '', 0, 0, '', -1, ''),
(20804, 'Zygand''s eyes go to his agent''s wrist, and stay there. The agent tugs his sleeve down - too late. "The Apothecaries said it was a ward against the Scourge''s plague," he mutters. "Every week. Just a scratch." The executor is very quiet. Then he picks up his blades. "The Master Apothecary and I are going to have a talk," he says, and goes out, and his agents go with him, and none of them look back at you at all.', '', 0, 0, '', 0, '0'),
(20805, '"Wrong answer." The two agents step apart, to come at you from both sides.', '', 1, 274, '', -1, ''),
(20806, 'Zygand reads the orders through. They''re the Apothecarium''s, sealed and signed: ''Subjects for the third trial: Deathstalker Agents ...'' and a list of names, and two of the names are standing behind him. He folds the paper very small. "You''ll forgive me," he says, in a voice like a closing door. "I have business in the Apothecarium." He leaves, and his agents with him.', '', 0, 0, '', 0, '0'),
(20807, 'The executor studies you for a long, cold moment. "Ashes," he says. "Tarren Mill always did send odd ones." He waves his agents off. "The queen keeps no audience before the late bell. Don''t touch anything in the Apothecarium, and don''t let the Overseer count you." He goes back to his dummies.', '', 0, 0, '', 0, '0'),
(20890, '"Enough talk." Zygand''s blades are out. "Make it quick - the queen dislikes a mess."', '', 1, 15, '', 0, ''),
(20901, 'A shadowed corner by the Apothecarium''s doors. A man in dark leathers sits on the steps, sharpening a knife, a black feather in his hat. He''s grey-faced like the Forsaken - but the grey is powder, and it''s starting to streak. / "Well. Two people in this city who aren''t dead." He doesn''t stop sharpening. "Andron Gant. Let''s not make each other''s lives difficult."', '', 1, 0, '', 0, ''),
(20902, '"What everybody wants. Knowing things." He tests the knife''s edge on his thumb. "Ravenholdt likes to know what the Apothecaries are brewing before they pour it into somebody''s well. Whoever''s well it is. We''re not particular about kingdoms, only about not being surprised." He shrugs. "You''re here for the same thing, near enough. I can tell by the way you keep looking at those doors."', '', 1, 0, 'ravenholdt', 0, ''),
(20903, '"Now that," says Andron Gant, "is the most sensible thing anyone''s said to me in a month." He sheathes the knife, pulls his hood down over the streaking powder, and gets up. "The Apothecaries keep their notes pinned up by the vats, if you''re the reading sort. Good luck. I''ll tell Ravenholdt you were polite." He''s gone through the Apothecarium''s doors before you can answer.', '', 0, 0, '', 0, '0'),
(20904, 'He looks at the coin - black, with a raven stamped on both faces - and then at you, with new respect. "Where did you get that?" Then: "No. Don''t tell me. If you''ve got one, somebody in Ravenholdt thought you were worth one." He gets up and bows, very slightly. "Then I''m off. Mind the Master Apothecary - he bites."', '', 0, 0, '', 0, '0'),
(20905, 'He stops sharpening. "Sharp eyes." A pause. "So: you could shout. I could put this knife in you. Or we could both go on not being noticed, which I find is the healthiest thing in this city." He stands, slow and careful, hands open. "I''ll take that as a yes." He backs into the shadows by the doors, and is gone.', '', 0, 0, '', 0, '0'),
(20906, '"Something on your mind?" The knife has stopped moving. He''s watching your hands.', '', 1, 0, '', -1, ''),
(20990, '"Shame." He''s up and moving before you see him rise. "I did like you."', '', 1, 14, '', 0, ''),
(21201, 'A chamber off the War Quarter, too warm for the Undercity. A dreadlord fills it: tall, bat-winged, horned, his hooves clicking on the stone as he paces. He stops when he sees you, and smiles with far too many teeth. / "Visitors! The living, in my lady''s city." A bow, beautifully done. "Varimathras, at your service. And I do mean that. I think you and I want the same thing - for once."', '', 1, 0, '', 0, ''),
(21202, 'He talks beautifully about the queen''s cruelty, about the chains she put on him, about freedom. He never once says what he would do with it. And every time he speaks her name, his claws curl - not in fear. In appetite. Whatever he offers you, he means to take the city when she falls, and the people who helped him will be the first loose end.', '', 0, 0, 'lies', 0, ''),
(21203, 'A dreadlord, smiling. You can''t read him at all, and he knows it.', '', 0, 0, '', -1, ''),
(21204, 'At the name the smile falters - the first honest thing his face has done. "You know a great deal for a mortal," he says softly. "Very well. I swear nothing. But I find I have urgent business in the War Quarter tonight, and the Dreadguard will be wherever I tell them. She''ll have nobody at her door." He bows again, and the shadows in the corner swallow him.', '', 0, 0, '', 0, '0'),
(21205, '"How disappointing." Varimathras stops pacing, and the air in the chamber gets very hot.', '', 1, 274, '', -1, ''),
(21206, 'He reads the letter, and every line of him goes still. It''s in his own hand, addressed to his brother Balnazzar, laying out exactly how he means to betray the queen - and who to. "Where did you -" He stops. "No matter. If she sees this, I burn." He holds out a claw, and you don''t give it to him. After a moment he laughs. "Very well. I will be elsewhere tonight. So will her guard. Keep that letter somewhere safe, little mortal." He''s gone in a swirl of shadow.', '', 0, 0, '', 0, '0'),
(21207, '"Splendid." He actually claps. "I knew we''d understand each other. The Dreadguard will find themselves very busy in the War Quarter tonight, and my lady will find her doors unwatched. Do try to win." He bows you out, and when you glance back the chamber is empty and smells of brimstone.', '', 0, 0, '', 0, '0'),
(21290, '"No? Then you are simply in the way." Varimathras spreads his wings, and the chamber fills with them.', '', 1, 15, '', 0, ''),
(21401, 'A desk on the bank ring, buried in ledgers. Behind it a fussy little Forsaken in a tall collar dips his quill and looks up. / "Name? Date of death? Cause?" He peers at you. "Hm. Not dead. Most irregular. Royal Overseer Bauhaus, Undercity Census. Everyone in the city is counted. Everyone." His quill hovers. "So. Name?"', '', 1, 0, '', 0, ''),
(21402, 'You read the open page upside down while he fusses with his ink. Name after name, with dates of death and trades - and through a third of them, a neat red line, and in the margin the same note again and again: ''requisitioned, Apothecarium''. Whole streets of the city have been crossed off and handed to the Apothecaries. The Overseer has been very careful not to wonder why.', '', 0, 0, 'gaps', 0, ''),
(21403, 'Ledgers, ink, and an Overseer who would very much like your name.', '', 0, 0, '', -1, ''),
(21404, 'Bauhaus goes, if it''s possible, paler. "Those were - the Master Apothecary assured me - royal authority -" He looks at the red lines as if seeing them for the first time. "Three hundred and twelve," he whispers. "I counted them. I counted every one." He gathers his ledgers to his chest. "I must - the queen must see the totals. Excuse me." He scurries away without counting you at all.', '', 0, 0, '', 0, '0'),
(21405, '"Irregular," he snaps. "Most irregular. Guards!"', '', 1, 5, '', -1, ''),
(21406, 'He takes the page, adjusts his spectacles, and reads. It''s a census entry, filled in, stamped with his own seal: two citizens of the Undercity, in good standing, deceased. Your descriptions are a little vague. "Well," he says, "well, why didn''t you say you were already counted?" He files it with a happy little sigh. "Carry on, citizens. Mind the canals."', '', 0, 0, '', 0, '0'),
(21407, 'You give him names - not your own - and dates of death, and causes, the more gruesome the better. "Eaten by a ghoul," he murmurs happily, writing. "Very good. Very regular." He stamps the page with a flourish. "Welcome to the Undercity, citizens. Do try not to breathe where people can see." He goes back to his ledgers, and forgets you.', '', 0, 0, '', 0, '0'),
(21490, '"Uncountable!" the Overseer shrieks. "Uncountable! Someone deal with these!"', '', 1, 5, '', 0, ''),
(21701, 'A quiet corner of the lower ring, out of the way. Three Forsaken sit on the steps around a little row of candle stubs: a woman in a mended dress, a big man with a shovel across his knees, an old man leaning on a cane. They look up when you come, but nobody reaches for a weapon. / "You''re alive," the woman says, wondering. "Oh. Oh, come and sit. We won''t bite. We''re not that sort."', '', 1, 0, '', 0, ''),
(21702, '"Ourselves," says the old man simply. "Who we were." The woman nods. "I was a schoolmistress in Andorhal. Davitt dug the graves at Brill - and then, well." The big man smiles, embarrassed. "Reginald kept the lamps on the Lordaeron road. We come here and light a candle for the people we were. Nobody else will. The queen says we should forget them. We''re not very good at forgetting."', '', 1, 0, 'mourning', 0, ''),
(21703, 'You sit on the cold step and let them talk. About Andorhal''s school, and the smell of turned earth at Brill, and the lamps going on one by one along the road at dusk. About people whose names nobody else remembers. When the candles gutter, the woman takes your hand in her cold one. "Thank you," she says. "We''ll not say we saw you. Go carefully." They blow out the candles, and go.', '', 0, 0, '', 0, '0'),
(21704, 'The woman takes the locket, and opens it, and makes a small sound. Inside are two little painted faces: a young woman in a schoolmistress''s collar, and a girl. "That''s me," she says. "That was me. And that''s my -" She can''t finish. The two men put their arms round her. When she looks up, her dead face is somehow wet. "Go," she says. "Go and do whatever you came for. You''ve done enough for us."', '', 0, 0, '', 0, '0'),
(21705, 'You tell them: the fields around Andorhal are wild now, but the farmhouses still stand; the Argent Dawn keeps the road at Light''s Hope; somewhere a schoolhouse has living children in it again. They listen like people hearing about a country they once visited. "Then it''s not all gone," the old man says at last. "Good. That''s good." They blow out their candles, one by one, and go home.', '', 0, 0, '', 0, '0'),
(21706, 'They listen politely, but your words go past them. The candles burn down.', '', 0, 0, '', -1, ''),
(21790, '"You''re like the rest of them," the big man says heavily, and stands, and the shovel comes up.', '', 2, 274, '', 0, ''),
(21801, 'The lowest hall of the Apothecarium, green-lit and stinking. Great copper vats bubble along the walls. A hunched Forsaken in a stained leather apron looks up from a flask; two assistants freeze at their stations. / "The living! In my Apothecarium!" Master Apothecary Faranell sets the flask down, very gently. "Do you know, I was just wishing for fresh subjects. Don''t touch the vats, there''s a dear. They''re nearly ready."', '', 1, 0, '', 0, ''),
(21802, 'The notes are pinned up beside the vats, the way a cook pins a recipe. You read the formula over Zinge''s shoulder: the plague itself, and a binding agent to stop it spreading where it isn''t wanted. Except the binding agent is wrong - a step copied out of order. As written, this plague would spread to the dead as happily as the living. Nobody in this room has noticed.', '', 0, 0, 'flaw', 0, ''),
(21803, 'Vats, flasks, and three Apothecaries watching your every move.', '', 0, 0, '', -1, ''),
(21804, 'You walk him through it, step by step: the binding agent, the order it''s mixed in, what it would do to Forsaken flesh. Faranell snatches the notes off the wall, reads, re-reads. "Zinge," he says, in a terrible voice. "Zinge, you copied this." The assistant backs away. Faranell turns to the vats. "It would have eaten us," he whispers. "The whole city." He pulls a lever, and with a great gurgle the vats empty into the drains. "Get out," he says, not looking at you. "Get out. I have work to start again."', '', 0, 0, '', 0, '0'),
(21805, '"Subjects," Faranell says pleasantly, "do not argue." His assistants reach for their flasks.', '', 1, 274, '', -1, ''),
(21806, 'Faranell reads the page, and his hands begin to shake. It''s in the queen''s own elegant hand: her orders for the plague, once it''s done. Stormwind first. Then the Forsaken who argue with her. Then - she isn''t particular - anyone she finds tiresome. His name is on the list. Faranell sits down heavily on an upturned crate. "I''m going to need some time to think," he says at last. He pulls the lever that empties the vats, and doesn''t watch them drain.', '', 0, 0, '', 0, '0'),
(21807, 'You set your shoulder against the biggest vat and heave. It rocks, groans on its stand - and goes over, a green tide sloshing across the floor and gurgling away down the drain. Months of work, gone. Faranell stares at it. His assistants stare at him. "That," he says faintly, "was the only batch." They flee up the stair before you can turn round, and he goes after them, shrieking.', '', 0, 0, '', 0, '0'),
(21890, '"Enough." Faranell uncorks a flask, and the smell alone makes your eyes stream. "Hold them still."', '', 1, 15, '', 0, ''),
(22101, 'A dark arch on the way into the Royal Quarter. Something pale drifts there, a hand''s breadth off the ground: a banshee, long hair floating as if under water, singing in Thalassian - a slow, sad song, beautiful and horrible at once. The song stops when she sees you. / "Living," she breathes. "Do you know how long it has been since I saw living eyes? Sharlindra, of the queen''s household. Why have you come to make me sing louder?"', '', 1, 0, '', 0, ''),
(22102, 'You listen while she sings it again, and catch some of the words: a river, a summer, a city of white towers, a girl who swam in the river and wanted to be a ranger when she grew up. She isn''t singing for the queen. She''s singing for that girl, and she breaks off every time before the second verse, as if she can''t bear to reach it.', '', 0, 0, 'grief', 0, ''),
(22103, 'A banshee, a song in a language you don''t know, and a cold that goes into your bones.', '', 0, 0, '', -1, ''),
(22104, 'You take up the second verse - the river in autumn, the girl grown up and gone to the rangers, the white towers waiting for her to come home. Your voice is rough and the tune is half-guessed. Sharlindra sings with you, and then, quietly, without you, all the way to the end, for the first time in years. When she''s done she is very faint. "Thank you," she says. "I can rest now, I think." She fades into the dark of the arch.', '', 0, 0, '', 0, '0'),
(22105, 'Her song rises to a shriek, and the stones crack with frost.', '', 1, 274, '', -1, ''),
(22106, 'It''s a ranger''s ribbon, the blue of Quel''Thalas, faded nearly white - the kind the Farstriders tied in their hair. Sharlindra reaches for it with fingers that can''t quite hold anything, and it passes through them. She doesn''t seem to mind. "I had one like that," she says. "Before." She looks at you for a long time. "The queen is through there. I won''t call her. Go, before I remember I should." She drifts away into the dark.', '', 0, 0, '', 0, '0'),
(22107, 'She wails, and it''s like being hit by a winter storm, and you stand there and take it - and don''t step back. When the scream finally dies she''s looking at you with something like respect. "The queen stood like that once," she says, "at the gates of Silvermoon." She drifts aside. "Go on, then. Let''s see if you stand in front of her."', '', 0, 0, '', 0, '0'),
(22190, '"Then join the song." Sharlindra''s mouth opens far too wide.', '', 1, 15, '', 0, ''),
(22401, 'The inn on the central rise: a long lodge of hides and poles, warm and smoky, a kettle singing on the fire. A tauren woman in an apron looks up from it - and for a moment her hand goes to the big iron ladle. Then she lets it go. / "Outsiders. On the rise." She sighs. "Well. The fire doesn''t ask who you are. Innkeeper Pala. Sit, if you mean no harm - and if you do, the ladle''s right here."', '', 1, 0, '', 0, ''),
(22402, '"The Grimtotem have been telling the chieftain that your Alliance is marching on Mulgore - that it means to burn the plains and take the land. Magatha''s been saying it loudest of all." She stirs the kettle. "Cairne''s called the braves to arms. I''ve lived on this rise sixty years and never seen a spear at my door before." She looks at you sideways. "You don''t look like an army."', '', 1, 0, 'rumour', 0, ''),
(22403, 'She considers you a long moment, then ladles out two bowls of something thick and fragrant. You eat by her fire, and she watches you do it, and somewhere in the eating she decides. "Armies don''t say thank you," she says. "Go on. I''ll not call the Bluffwatchers. And if anyone asks, I fed you because the fire doesn''t ask."', '', 0, 0, '', 0, '0'),
(22404, 'She turns the little stone over in her big hands - a carved hearthstone, the kind tauren children make for their mothers, with a name scratched in the bottom. Her name. "I made this for my mother," she says quietly. "It was lost when we came across the Barrens." She sets it on the mantel by the kettle, very carefully. "Whatever you''ve come for - go and do it. You''ve a friend at this fire."', '', 0, 0, '', 0, '0'),
(22405, 'You tell her the truth, or as much of it as matters: a war nobody wants, built on a crone''s lies, and the hope of ending it before the plains burn. Pala listens without a word. At the end she nods, slowly. "Sixty years," she says, "and I still know an honest face. Go on. I''ll keep the fire lit."', '', 0, 0, '', 0, '0'),
(22406, '"Hm." Her hand drifts back to the ladle.', '', 1, 0, '', -1, ''),
(22490, '"That''s enough out of you." Pala hefts the ladle, and outside a Bluffwatcher''s horn sounds.', '', 1, 274, '', 0, ''),
(22501, 'The Stonehoof forge, roaring. A huge tauren in a leather apron is drawing out spearheads one after another and dropping them hissing into the tank. He doesn''t stop hammering. / "Outsiders. Good. I''ve been making these for a week and I''d like to see one used." Clang. "Karn Stonehoof. Say your piece quickly - the chieftain wants two hundred more by the new moon."', '', 1, 0, '', 0, ''),
(22502, 'The order is nailed to the post by the anvil: two hundred spearheads, war-weight, for the defence of Mulgore. It''s sealed - but not with the Bloodhoof bull. With a black totem: the Grimtotem mark. Cairne never signed this. Karn has been hammering too hard to look.', '', 0, 0, 'seal', 0, ''),
(22503, 'Sparks, noise, and a smith who will not stop hammering.', '', 0, 0, '', -1, ''),
(22504, 'Karn stops hammering. He walks to the post and reads the seal, slowly, and his great face darkens. "Magatha," he says, and the word comes out like a stone. He tears the order down and throws it in the forge. "The Stonehoofs make weapons for the chieftain. Not for that crone." He banks the fire. "I''m going to have a word with Cairne. You - go where you like."', '', 0, 0, '', 0, '0'),
(22505, '"Talk, talk." Karn lifts the hammer, and it''s not pointed at the anvil.', '', 1, 274, '', -1, ''),
(22506, 'He takes the old hammer and stops dead. The haft is worn smooth by hands that aren''t his; the head bears the Stonehoof mark, very old. "My grandfather''s," he says. "Lost on the long walk from the Barrens." He weighs it, and something in him goes quiet. "Grandfather made ploughshares, mostly. Said spears were for people who''d run out of ideas." He sets down his war-hammer. "Go on. I need to think."', '', 0, 0, '', 0, '0'),
(22507, 'You take up a hammer and a blank and go at it - and the spearhead you draw out is straight and true, and you hold your own with him stroke for stroke. Karn watches with growing respect. "Hah!" He claps a hand on your back that nearly knocks you into the tank. "Anyone who can draw a point like that isn''t my enemy. Go on, smith-friend."', '', 0, 0, '', 0, '0'),
(22590, '"Enough." Karn pulls a glowing spearhead from the coals with his bare tongs. "Let''s test this batch."', '', 1, 15, '', 0, ''),
(22701, 'The Hunter Rise. A lean tauren huntress in feathers and hide stands among poles hung with trophies - skulls, horns, a cloud serpent''s wing. She has an arrow nocked before you''ve said a word. / "Prey that walks up to the hunter. I''ve heard of that, but never seen it." A slow smile. "Hesuwa Thunderhorn. Give me one reason I shouldn''t add you to the poles."', '', 1, 0, '', 0, ''),
(22702, 'Every trophy on the poles has its little tag: the beast, the place, the season. Every pole is full - except one, in the place of honour, which is bare but for a single tag in faded paint: ''the white plainstrider''. There are notes pinned under it, years of them: sightings, tracks, near misses. She''s been after one beast her whole life, and never caught it.', '', 0, 0, 'stag', 0, ''),
(22703, 'Skulls and horns. A very good hunter, and you are standing in front of her bow.', '', 0, 0, '', -1, ''),
(22704, 'The arrow comes off the string - not at you, but back into the quiver. "Where?" You tell her, and you tell it well: the split hoof, the long stride, the way it doubles back. Hesuwa''s eyes are shining. "Then I''ve a hunt to finish," she says, "and no time for you at all." She''s gone down the rise at a run.', '', 0, 0, '', 0, '0'),
(22705, '"Wrong answer." The bowstring creaks back.', '', 1, 274, '', -1, ''),
(22706, 'You hold out the feather: long, pure white, a plainstrider''s tail-plume, found where no plainstrider should be. Hesuwa lowers her bow and takes it as if it might break. "It''s real," she whispers. "It''s still out there." She ties it into her hair. "You''ve given me back my hunt. I won''t take your life for it." She steps aside.', '', 0, 0, '', 0, '0'),
(22707, 'You race - across the rise, round the far totem, back again, Hesuwa''s hooves drumming beside you the whole way - and touch the totem a hair''s breadth before she does. She doubles over, laughing and gasping. "Fast," she says. "Fast prey. I''ll give you that." She waves you on. "Go, before I want a rematch."', '', 0, 0, '', 0, '0'),
(22790, '"Enough talk. The hunt begins." Hesuwa looses, and somewhere above, a cloud serpent answers her whistle.', '', 1, 15, '', 0, ''),
(22901, 'The Pools of Vision, under the Spirit Rise: still water, glowing faintly, and shadows. In the shadows, bent over a little table of flasks, a Forsaken woman in an apothecary''s coat. She flinches when she sees you, and her hand goes to a flask. / "Don''t! Don''t come closer. I - I have every right to be here. The chieftain allows it. Apothecary Zamah. I study the waters. That is all I do."', '', 1, 0, '', 0, ''),
(22902, 'The flasks are labelled in the Apothecaries'' neat hand. Most are harmless - water samples, herbs. One is not: a dark green tincture, and the label says ''to be applied to the blade - for the Elder Crone, to her order''. Zamah keeps putting herself between you and it.', '', 0, 0, 'poison', 0, ''),
(22903, 'Flasks, water, and a frightened Forsaken.', '', 0, 0, '', -1, ''),
(22904, 'Zamah goes still. You can see her working it out: a chieftain dead of poison, a tribe looking for who to blame, and one Forsaken among the tauren. "She promised me safe passage home," she whispers. "She promised." She takes the green flask and pours it into the pool, where it fizzes and fades. "I''m leaving tonight," she says. "Please. Let me go."', '', 0, 0, '', 0, '0'),
(22905, '"Stay back!" She unstoppers the flask, and the fumes sting your eyes.', '', 1, 5, '', -1, ''),
(22906, 'She breaks the seal - the Society''s own - and reads, and sags with relief. "Recalled," she says. "I''m recalled. I can go home." She sweeps her flasks into a bag, the green one too, and then hesitates and empties that one into the pool. "I''ll not need that where I''m going," she says. "Thank you." She''s gone up the path before you can answer.', '', 0, 0, '', 0, '0'),
(22907, '"Home?" Her voice cracks. "The queen wants me home?" She doesn''t question it - she wants it too badly. She packs in a frantic hurry, pours away the green flask "so the tauren won''t find it", and follows your directions to the lift. By the time she realises nobody is waiting there, she''ll be well away from Magatha.', '', 0, 0, '', 0, '0'),
(22990, '"No - no!" Zamah hurls the flask, and calls out in Orcish for the Bluffwatchers.', '', 1, 5, '', 0, ''),
(23001, 'At the head of the lift to the lower rise stands an old tauren with great antlers bound in leather and leaves, leaning on a gnarled staff. He watches you come up with calm, unhurried eyes. / "I wondered when you would come." His voice is deep and slow. "Hamuul Runetotem, Arch Druid of the tauren. The winds told me of strangers. They didn''t tell me what you wanted."', '', 1, 0, '', 0, ''),
(23002, '"Magatha says your kind marches on Mulgore. The winds say nothing of the sort, and neither do the beasts, and neither does the grass." He leans on his staff. "Cairne is a good chieftain and an old one, and Magatha has been whispering in his ear for a long time. I have argued. He does not listen. And now you are here, and that will not help."', '', 1, 0, 'doubt', 0, ''),
(23003, 'He thinks about it for a long time, as druids do. "Very well," he says at last. "The druids will stay in the grove tonight. Whatever happens on the high rise, we will not be part of it." He looks at you hard. "Do not make me regret it." He steps onto the lift and is carried down, out of sight.', '', 0, 0, '', 0, '0'),
(23004, 'He takes the seed in his palm: a moonglade acorn, silver-skinned, still faintly warm with the Moonglade''s magic. "Where did you -" He stops and smiles. "Never mind. The Cenarion Circle''s gifts travel strangely." He tucks it away. "Go with the Earth Mother''s blessing, strangers. The druids will not stand against you."', '', 0, 0, '', 0, '0'),
(23005, 'A pause. Then the Arch Druid laughs - a low, rumbling laugh like distant thunder. "No," he admits. "I don''t. And I find I don''t care to bleed for it either." He waves you on with his staff. "Go. Do what you came to do. I will tend the grove."', '', 0, 0, '', 0, '0'),
(23006, '"Hm." The old druid''s eyes narrow. The leaves in his antlers rustle without a wind.', '', 1, 0, '', -1, ''),
(23090, '"Then you leave me no choice." Hamuul lifts his staff, and the moonlight comes with it.', '', 1, 15, '', 0, ''),
(23201, 'A lodge on the Elder Rise, dark and close, hung with bundles of drying herbs and strange charms. An ancient tauren woman sits by a low fire, wrapped in Grimtotem black. She smiles at you, and it is not a nice smile. / "The Alliance, come to the mesas, just as I told him." She cackles. "Magatha Grimtotem, Elder Crone. Sit, sit. I''ve been so wanting to meet the war I made up."', '', 1, 0, '', 0, ''),
(23202, 'While she talks, her hands are busy - stirring the fire, adjusting her charms, and once, quickly, tucking a small green vial deeper into her sleeve when she thinks your eyes are on her face. The same green as the Apothecaries'' brews. Whatever''s in it, she doesn''t want it seen.', '', 0, 0, 'vial', 0, ''),
(23203, 'An old woman, a fire, and a smile you don''t like.', '', 0, 0, '', -1, ''),
(23204, 'The smile freezes. For a moment the old crone looks every one of her years, and frightened. Then she spits into the fire. "Prove it," she hisses. "Go on - go tell Cairne a story about an old woman and a little bottle, and see who he believes." But she''s already gathering her charms. By the time you reach the door, she''s gone out the back, and the Grimtotem with her, off the mesas and down into the dark.', '', 0, 0, '', 0, '0'),
(23205, '"Foolish." Magatha rises, and the charms on her walls begin to rattle.', '', 1, 274, '', -1, ''),
(23206, 'She reads the first page of the ledger and knows her own hand: letters to every Grimtotem warband from Stonetalon to Feralas, with a date. The night Cairne falls. Magatha stares at it, and then at you. "Who else has seen this?" You don''t answer. She gathers her things in silence and goes out the back, and a moment later you hear her shrilling orders to her clan to leave the mesas. Tonight.', '', 0, 0, '', 0, '0'),
(23207, '"Sellswords!" She claps her bony hands, delighted. "Of course - of course. Even the Alliance has its hungry ones." She tells you a great deal more than she should: a war, a fall, a new chieftain in Grimtotem black. Then she sends you off to wait for her signal - far from the Elder Rise - and goes to raise your pay from the Grimtotem chests. She won''t find you when she comes back.', '', 0, 0, '', 0, '0'),
(23290, '"Enough." Magatha casts a handful of something on the fire, and the lodge fills with poisoned smoke.', '', 1, 15, '', 0, ''),
(23401, 'Below the chieftain''s lodge, a great war drum stands on the rise, taller than a tauren. A young bull in fine armour stands beside it, drumsticks in his belt, staring out over the plains. He turns as you come. / "So it''s true. The Alliance is here." His voice is steady, but his hand is tight on his mace. "Baine Bloodhoof. My father''s drums are mine to keep. Tell me why I shouldn''t sound them."', '', 1, 0, '', 0, ''),
(23402, 'He talks about the war the way someone talks about a duty they''ve been handed and don''t want. Every time he mentions Magatha his jaw tightens. He doesn''t believe in this. He''s been told to, by the father he loves, and he''s trying very hard.', '', 0, 0, 'doubt', 0, ''),
(23403, 'A young chieftain-to-be, a drum, and a mace he hasn''t let go of.', '', 0, 0, '', -1, ''),
(23404, 'Baine is quiet for a long time, looking out at the plains. "I''ve thought it," he says at last. "I''ve thought it every night since she started whispering. I didn''t dare say it." He takes the drumsticks from his belt and lays them on the drum, and covers it with a hide. "One night. I''ll give him one night without the drums. If you''re lying to me -" He doesn''t finish. He walks down the rise toward the Elder lodge.', '', 0, 0, '', 0, '0'),
(23405, '"I''ve heard enough." Baine reaches for the drumsticks.', '', 1, 274, '', -1, ''),
(23406, 'He takes the little carving - a kodo calf, whittled by a child''s knife, the legs uneven. "I made this," he says, astonished. "For my father. When I was small. He used to keep it by his bed." He turns it over in his big hands. "If he left it behind, then -" He stops, and decides something. He covers the drum. "There will be no drums tonight. Go."', '', 0, 0, '', 0, '0'),
(23407, 'You lock arms and heave - and he''s strong, a young bull, but you get a heel behind his hoof and he goes down with a crash that shakes the drum. He lies there a moment, then laughs. "My father wrestled like that," he says, getting up. "Fair, and hard." He covers the drum. "I''ll not sound them for someone who fights fair. Go on."', '', 0, 0, '', 0, '0'),
(23490, '"Then hear them." Baine strikes the drum once, deep and huge, and draws his mace.', '', 1, 15, '', 0, ''),
(23801, 'A hall off the Valley of Strength, hung with old banners and older trophies. A grizzled orc in battered plate stands under them, arms folded, scowling. / "Alliance! In my valley!" He doesn''t sound angry, exactly. He sounds pleased. "Overlord Runthak. I''ve waited twenty years for someone worth fighting to walk through that gate. Speak, before I decide you''re it."', '', 1, 0, '', 0, ''),
(23802, 'The banners are from the Second War. The trophies are old. Everyone who fought beside him has gone on to Grommash Hold or the Valley of Honor, and he''s been left here minding the gate. He keeps glancing toward the hold when he thinks you''re not looking. He wants to matter again - very badly.', '', 0, 0, 'vain', 0, ''),
(23803, 'An old orc in old armour, very eager for a fight.', '', 0, 0, '', -1, ''),
(23804, 'Runthak''s face goes through anger, doubt and wounded pride in about a heartbeat. "Hellscream," he growls. "That pup." He straps on his sword. "You''re right. A real overlord stands at the Warchief''s side, not at a gate." He storms out toward the Valley of Honor to have it out with Garrosh, and forgets all about you.', '', 0, 0, '', 0, '0'),
(23805, '"Enough talk!" Runthak draws his greatsword with a roar.', '', 1, 274, '', -1, ''),
(23806, 'He takes the medal - old iron, a Horde crest, his name stamped on the back - and turns it over and over. "Hillsbrad," he says. "I lost this at Hillsbrad. Twenty years." He pins it to his chest with shaking fingers. "Anyone who''d bring this back to an old orc isn''t here to murder babies in their beds." He waves you on, gruff. "Go on. I didn''t see you."', '', 0, 0, '', 0, '0'),
(23807, '"By name?" His chest swells. "Of course by name." He''s out of the hall at a run before you''ve finished lying, roaring for his guards, off to the Valley of Honor to break up a brawl that isn''t happening.', '', 0, 0, '', 0, '0'),
(23890, '"FIGHT ME!" Runthak charges, delighted.', '', 1, 15, '', 0, ''),
(23901, 'The orphanage, a low building in the Valley of Honor. A broad orc woman fills the doorway, a rolling pin in one fist. Behind her legs, small green and grey faces peer out at you. / "No," she says. "Whatever you''re here for, no. Orphan Matron Battlewail. These children have lost enough to soldiers already."', '', 1, 0, '', 0, ''),
(23902, '"Because every one of these little ones lost their parents to a war. Orc, troll, Forsaken - doesn''t matter. And now there''s Alliance in the city and the grunts are shouting about another one." She grips the rolling pin. "You''ll not get past this door without going through me, and I promise you I''m harder to go through than I look."', '', 1, 0, 'orphans', 0, ''),
(23903, 'She studies you for a long moment. Then she nods, once, and steps back inside, and you hear the bar drop across the door. Through the shutters, faintly, she starts the children singing - something loud, to cover whatever happens outside.', '', 0, 0, '', 0, '0'),
(23904, 'A small orc girl darts out from behind the matron and snatches the doll from your hand - a rag doll with button eyes and a tiny wooden axe. "Grommy!" She hugs it fiercely. The matron looks at you, and something in her face softens. "She''s cried for that doll for a month," she says. "Go on, then. And thank you." She shoos the children in and shuts the door.', '', 0, 0, '', 0, '0'),
(23905, 'You crouch down and talk to the children - about nothing, mostly: what their names are, which of them is fastest, whether the matron''s porridge is as bad as it smells. Somewhere in it they start to giggle. The matron lowers her rolling pin. "Well," she says. "That''s more than any grunt''s ever managed." She takes them in and shuts the door, gently.', '', 0, 0, '', 0, '0'),
(23906, 'The children shrink back behind her skirts. The matron''s knuckles whiten on the rolling pin.', '', 0, 0, '', -1, ''),
(23990, '"Not one step closer to these children." The matron bellows for the guard, and swings.', '', 1, 15, '', 0, ''),
(24001, 'The Cleft of Shadow: a dark gorge under the city, full of smoke and whispered bargains. A gaunt orc in red robes tends a stall of jars and pouches, and greets you with a merchant''s smile. / "Customers! From so very far away." His eyes are a little too bright. "Neeru Fireblade, humble seller of reagents. Whatever you need, Neeru has it. Whatever you''re running from, Neeru never saw you."', '', 1, 0, '', 0, ''),
(24002, 'Most of the stall is honest stock: herbs, ink, candles. But at the back, half-hidden behind a cloth, are jars no honest reagent seller keeps - felblood, soul-ash, demon salt, the makings of a summoning. And burnt into the wood of the stall''s back panel, half-sanded away, the mark of a flaming sword. The Burning Blade.', '', 0, 0, 'fel', 0, ''),
(24003, 'Jars, pouches, and a merchant whose smile never reaches his eyes.', '', 0, 0, '', -1, ''),
(24004, 'The smile goes out like a snuffed candle. Neeru looks at you, at the Kor''kron patrol passing the mouth of the Cleft, and back. "You''ll never prove it," he says softly. Then he sweeps the back jars into a sack and is gone into the smoke, and by morning his stall is bare and the Blade''s man is out of the city.', '', 0, 0, '', 0, '0'),
(24005, '"Pity." Neeru''s hands start to glow a sickly green. "I did so hope you''d buy something."', '', 1, 274, '', -1, ''),
(24006, 'You lay the sigil on the counter: an iron flame, the Burning Blade''s own token, the kind its leaders carry. Neeru stares at it, and you watch him do the sums. Someone else knows. Someone else has one. "I see," he says carefully. "Then I have urgent business elsewhere." He leaves the stall exactly as it stands and walks out of the Cleft without looking back.', '', 0, 0, '', 0, '0'),
(24007, 'Neeru goes grey. "Blown?" He doesn''t ask how you know the password - he''s too busy packing. "Tell the Master I did everything he asked," he babbles, stuffing jars into a sack. "Everything!" He''s gone into the smoke before you can answer.', '', 0, 0, '', 0, '0'),
(24090, '"Then burn." Neeru''s robes catch green fire, and the smoke in the Cleft starts to move.', '', 1, 15, '', 0, ''),
(24301, 'The Valley of Spirits, high on its ledge: drums, smoke, hanging charms. A tall troll with tusks bound in silver leans on a glaive, watching you climb up with cool, amused eyes. / "Mon, de Alliance be gettin'' bold." He doesn''t raise the glaive. "Vol''jin, of de Darkspear. Dis my valley. Speak true, or speak never again."', '', 1, 0, '', 0, ''),
(24302, 'He talks easily, but there''s steel under it. Twice he mentions Garrosh Hellscream, and both times his lip curls. He''s loyal to Thrall - you can hear that - but he has no love for war for its own sake, and none at all for the young warlord who wants one. He respects straight talk. He''s waiting to see if you have any.', '', 0, 0, 'honour', 0, ''),
(24303, 'A troll chieftain, a glaive, and a stare you can''t read.', '', 0, 0, '', -1, ''),
(24304, 'Vol''jin is quiet for a while. Then he laughs, low. "You see it too, eh? Dat boy would burn de whole Horde for a song about it." He shoulders his glaive. "De Darkspear stay in de valley tonight. What happen in de hold be between you and Thrall." He turns away. "Don'' make me regret it, mon."', '', 0, 0, '', 0, '0'),
(24305, '"Wrong words, mon." The glaive comes up.', '', 1, 274, '', -1, ''),
(24306, 'He takes the mask - an old Darkspear spirit mask, painted in faded colours, the kind carried off the Echo Isles when the trolls were driven out. He runs his thumb along it. "Dis be my father''s tribe''s," he says slowly. "Lost when we fled." He hangs it on the post beside him. "De loa brought you, maybe. Go. De Darkspear won'' stand in your way."', '', 0, 0, '', 0, '0'),
(24307, 'He stares. You stare back. Somewhere in it the drums stop. The smoke drifts. You don''t blink. Finally Vol''jin grins, tusks and all. "Strong spirit," he says. "De loa like dat." He steps aside. "Go on, strong spirit. Let''s see if Thrall like it too."', '', 0, 0, '', 0, '0'),
(24390, '"So be it." Vol''jin whistles, and a raptor answers from below the ledge.', '', 1, 15, '', 0, ''),
(24601, 'The training grounds of the Valley of Honor. An old orc, grey-bearded and scarred, works a training dummy with slow, perfect strokes. He finishes the form before he looks at you. / "Alliance." He doesn''t sound surprised. "I am Eitrigg. I command the Warchief''s guard, for my sins. Say what you came to say, and then we''ll see."', '', 1, 0, '', 0, ''),
(24602, 'He moves like a soldier, but tired - a soldier who has fought too many wars to enjoy another. And round his neck, on a leather cord, hangs something no orc warrior should wear: a small silver token of the Order of the Silver Hand. A human paladin''s. He touches it, without thinking, when he looks at you.', '', 0, 0, 'tirion', 0, ''),
(24603, 'An old warrior, a training dummy, and a patience that won''t last forever.', '', 0, 0, '', -1, ''),
(24604, 'The old orc stops. His hand closes on the silver token. "Tirion," he says, very quietly. "He gave up everything for me. His lands, his order, his name." He looks at you for a long time. "The Kor''kron will be at drill in the Valley of Honor tonight," he says at last. "All of them. Whatever happens in the hold - they won''t hear it." He goes back to his dummy.', '', 0, 0, '', 0, '0'),
(24605, '"Enough." Eitrigg turns from the dummy, and his axe is no training blade.', '', 1, 274, '', -1, ''),
(24606, 'He reads the letter twice. It''s addressed to him, in a firm human hand: ''Old friend - if this finds you, know that I am well, and that I think of the day we met. I hope there will never be war between our peoples again. - T. F.'' Eitrigg folds it very carefully and puts it inside his armour. "The Kor''kron will be elsewhere tonight," he says, and his voice is rough. "Go."', '', 0, 0, '', 0, '0'),
(24607, 'He tosses you a training blade, and you go at it on the sand - and he''s old, but he''s good, and you''re just good enough. When it''s done you''re both breathing hard. "Hah," says Eitrigg. "You fight like a Silver Hand. Honest." He hangs up the blades. "The guard drills in the valley tonight. You never heard it from me."', '', 0, 0, '', 0, '0'),
(24690, '"So be it." Eitrigg raises his axe in the old salute, and then attacks.', '', 1, 15, '', 0, ''),
(24801, 'A young orc paces at the edge of the Valley of Honor like a caged wolf: brown-skinned, tattooed jaw, a great axe across his shoulders. He stops dead when he sees you, and his face splits in a fierce grin. / "Finally! The Alliance comes to Orgrimmar!" He hefts the axe. "Garrosh Hellscream, son of Grom. Thrall would talk to you. I''d rather see what you''re made of."', '', 1, 0, '', 0, ''),
(24802, 'He wants a war the way a starving wolf wants meat. But under it, there''s something else: every time he mentions Thrall his voice tightens, and when he says ''son of Grom'' he says it like a man who''s afraid he''ll never measure up. He doesn''t want your blood. He wants an enemy big enough to make him a hero.', '', 0, 0, 'pride', 0, ''),
(24803, 'A young orc with a very large axe and no patience at all.', '', 0, 0, '', -1, ''),
(24804, '"The Burning Blade?" Garrosh''s grin vanishes. "In my city?" You tell him where: the Cleft of Shadow, the reagent stalls, the felblood jars. His knuckles go white on the axe. "Demon-worshippers. The ones my father died to free us from." He turns and strides toward the Drag without another word, and anyone in the Cleft tonight is going to have a very bad evening.', '', 0, 0, '', 0, '0'),
(24805, '"Talk!" Garrosh spits. "Your kind always talks." The axe comes off his shoulders.', '', 1, 274, '', -1, ''),
(24806, 'He snatches it from your hand: a tusk pendant on a worn thong, carved with the Warsong mark. He knows it at once. "My father''s," he says hoarsely. "Where did -" He stares at you, and for a moment he looks very young. Then he closes his fist on it and turns away. "Go," he says. "Before I change my mind. I owe you this one, Alliance. Only this one."', '', 0, 0, '', 0, '0'),
(24807, '"Now?" Garrosh scowls. "He never sends for me unless -" He breaks off, already striding away toward the hold, muttering. By the time he finds out nobody sent for him, he''ll be nowhere near you.', '', 0, 0, '', 0, '0'),
(24890, '"FOR THE HORDE!" Garrosh charges, and Gorehowl screams through the air.', '', 1, 15, '', 0, ''),
(24901, 'A quiet corner of the Valley of Wisdom, where the wind always seems to blow. An old orc shaman sits cross-legged on a mat, eyes closed, totems standing around him. He opens one eye. / "Ah. The strangers." His voice is calm and dry. "Zor Lonetree, Far Seer. The spirits said you would come. They said a great many things. Sit, if you like."', '', 1, 0, '', 0, ''),
(24902, '"The spirits are uneasy." He frowns at the wind. "The Warchief calls them in anger now - against you, against the cult in the Cleft, against shadows. They answer, because he is Thrall. But they do not like to be a weapon. Earth, wind and fire are not soldiers." He sighs. "I have told him so. He is very tired, and very angry, and he does not hear me."', '', 1, 0, 'uneasy', 0, ''),
(24903, 'The old shaman closes his eyes and is silent a long while. The wind shifts, and drops, and is still. "They agree," he says at last. "Tonight the storm will not come when the Warchief calls it. Whatever happens in the hold will be between living hands." He opens his eyes. "Go gently, if you can."', '', 0, 0, '', 0, '0'),
(24904, 'He takes the little totem - an old wind-totem, feathers and bone, the kind a shaman makes once and keeps for life. "Drek''Thar''s," he says, wondering. "I''d know his knots anywhere." He plants it in the earth beside him, and the wind quiets around it. "The spirits will rest tonight. Go."', '', 0, 0, '', 0, '0'),
(24905, 'The Far Seer smiles - just a little. "No," he says. "I don''t. He built this city for peace, and now he would bleed it for a quarrel with strangers who came through a hole in the air." He closes his eyes. "Go on. I will ask the spirits to sit this one out."', '', 0, 0, '', 0, '0'),
(24906, 'He closes his eye again. The wind picks up.', '', 1, 0, '', -1, ''),
(24990, '"Then let the spirits judge you." The Far Seer rises, and lightning crackles between his totems.', '', 1, 15, '', 0, '');
