(801, 1, 'I didn''t take anything. Calm down and tell me exactly what happened.', 'Persuasion', 14, 803, 804, '', '', '', 1),
(801, 2, 'What exactly was in these schematics?', '', 0, 805, 805, '', '', '', 1),
(801, 3, 'Who else was in camp last night?', '', 0, 806, 806, '', '', '', 1),
(801, 4, 'Take a closer look at the camp.', '', 0, 808, 808, '', '', '', 1),
(801, 5, 'Brakk. Did you see anything last night?', '', 0, 807, 807, '', 'askedwho', '', 1),
(801, 6, 'You said your frost-ink glows blue in the cold. So why is Nim''s satchel glowing?', '', 0, 810, 810, '', 'ink,glow', '', 0),
(801, 7, 'Nim. What were you writing by lamplight all night?', 'Insight', 15, 810, 811, '', 'scratching', 'glow', 1),
(801, 8, 'Out with it, Nim. What''s in the satchel?', 'Intimidation', 15, 810, 811, '', 'glow', 'scratching', 1),
(801, 9, 'Only a trained tinker can read frost-script, you said. You have an apprentice.', '', 0, 812, 812, 'INT>=14', 'askedwho', '', 0),
(801, 10, 'Fizzik. Friend. We''ll solve this together.', '', 0, 826, 826, 'CHA>=13', '', '', 1),
(801, 11, 'One tinker to another: I''ve no use for anyone else''s designs. I build my own.', '', 0, 819, 819, 'Gnome', '', '', 1),
(801, 12, 'Have you tried checking your other pockets?', '', 0, 817, 817, '', '', '', 1),
(801, 13, 'It was the dwarf. Obviously. Look at him.', '', 0, 818, 818, '', 'askedwho', '', 1),
(801, 14, 'You want a fight, tinker? You''ve got one.', '', 0, -1, -1, '', '', '', 0),
(801, 15, 'I don''t have time for this.', '', 0, 0, 0, '', '', '', 0),
