-- zones and the level each needs; encounters count toward one zone and pay their XP once per character
DELETE FROM `dnd_zone` WHERE `id` IN (1,2,3,5,6,10,11,4,12,13,14,15,16,7,8,9,17,18,19,21,20,22);
INSERT INTO `dnd_zone` (`id`, `name`, `min_level`, `areas`, `gate_text`, `clear_text`) VALUES
(1, 'Coldridge Valley', 1, '132,77,800', '', 'Coldridge Valley is safe. Coldridge Pass leads on into Dun Morogh.'),
(2, 'Dun Morogh', 2, '1', 'A notice is nailed at the tunnel mouth: "By order of the Mountaineers - greenhorns past this point do so at their own risk."', 'Dun Morogh is quiet at last. Two roads lead on: east through the North Gate pass to Loch Modan, and up the mountain to the Gates of Ironforge, where Dark Iron banners hang.'),
(3, 'Loch Modan', 3, '38', 'A mountaineer at the North Gate pass shakes his head as you go by: "Loch Modan? You''re green for it, friend. Don''t say nobody warned you."', 'Loch Modan is safe again. Two roads lead on: north through the tunnels of Dun Algaz, down into the Wetlands, and south over the pass past the Uldaman dig, into the Badlands.'),
(5, 'Wetlands', 4, '11', 'A mountaineer at Algaz Station calls after you: "The Wetlands? With Loch Modan still crawling? The Dragonmaw will have you for breakfast, friend."', 'The Wetlands are safe again - Menethil''s road is open from the harbour to the pass. North, over the Thandol Span, lie the Arathi Highlands.'),
(6, 'Badlands', 4, '3', 'A dwarf of the Explorers'' League, coming north up the pass, stops you: "The Badlands? There''s ogres down there, and Dark Irons, and the ravine''s full of dragons. You look like you''d last an afternoon."', 'The Badlands are quiet again - as quiet as a land of dust and dragons gets. West, beyond the ogre hills, the road climbs into the Searing Gorge.'),
(10, 'Searing Gorge', 5, '51', 'Past the slag-walls the air shimmers with heat, and somewhere below, iron rings on iron. A Thorium Brotherhood scout eyes you from a ledge: "Turn back, if you''ve any sense. The Dark Irons down there eat adventurers your size."', 'The Searing Gorge is quiet - or as quiet as the Cauldron gets. South, past the Dark Iron gates, lies Blackrock Mountain and the Burning Steppes beyond it: still closed, for now.'),
(11, 'Burning Steppes', 99, '46,25', 'Blackrock Mountain''s gates stand shut, and the chain across the great bridge is drawn tight. No one goes south into the Burning Steppes. Not yet.', ''),
(4, 'Ironforge', 3, '1537', 'The Gates of Ironforge stand open, and the guards in them wear Dark Iron black. One looks you over and laughs: "In you come, little one. The regent''s city has room for everyone - in chains, if need be."', 'Ironforge has settled, one way or another - the factions have had their say, and the halls are quieter. Whatever happens to the High Seat now, you had a hand in it. The Deeprun Tram still runs south, to Stormwind.'),
(12, 'Stormwind City', 4, '1519', 'The gate guards wear the Lady''s black and gold. "The Lord Protector welcomes all visitors," one recites. Under his breath: "Turn round, if you''ve any sense. This city eats the green ones."', 'Stormwind has had its reckoning. The Lady''s court is broken or bargained with, and the city breathes again. Through the gate, the road runs on into Elwynn Forest.'),
(13, 'Elwynn Forest', 5, '12', 'A farmer is nailing boards over his windows by the road. He looks up as you pass: "Elwynn''s not the safe old forest it was, friend. Defias on the roads, gnolls at the farms. You look a bit green for it."', 'Elwynn Forest is quieter. The roads are walkable again, and Goldshire sleeps with its shutters open. Beyond the forest, the roads to Westfall, Redridge and Duskwood are still closed.'),
(14, 'Westfall', 99, '40', 'A Stormwind soldier at the bridge shakes her head: "Westfall''s closed. Defias country now, all of it. Nobody goes over till the Marshal says."', ''),
(15, 'Redridge Mountains', 99, '44', 'The road to Lakeshire is barred by a wagon and two nervous militiamen. "Orcs in the hills, friend. Lakeshire''s shut till they''re dealt with."', ''),
(16, 'Duskwood', 99, '10', 'Where the road enters the dark trees, a Night Watch sign: DUSKWOOD - CLOSED. Someone has scratched underneath it: ''and for good reason''.', ''),
(7, 'Arathi Highlands', 5, '45', 'A dwarf sentry at the north end of the Thandol Span watches you cross: "Arathi''s no place for the untried. Ogres, trolls, the Syndicate - take your pick of what kills you."', 'The Arathi Highlands are quiet again: the trolls are back in their hills, the ogres in their hall, and the Syndicate''s hold on Stromgarde is broken. The roads beyond - west to Hillsbrad, north into Alterac - are still closed, for now.'),
(8, 'Hillsbrad Foothills', 99, '267', 'A Refuge Pointe outrider shakes her head. "Hillsbrad? Not this season. The Syndicate hold every road west, and we''ve no one to spare to escort you."', ''),
(9, 'Alterac Mountains', 99, '36', 'The pass into Alterac is choked with snow and worse. Whatever waits up there will have to keep.', ''),
(17, 'Undercity', 6, '1497', 'The air is cold and smells of the grave. Somewhere far off, something is screaming, and nobody is hurrying to see why. This is the Banshee Queen''s city, and it was not built for the living.', 'The Undercity is broken. The queen''s court is scattered, the Apothecarium''s vats are cold, and the portal keeper in the Magic Quarter can send you home whenever you are ready.'),
(18, 'Tirisfal Glades', 99, '85', 'The lifts groan up toward the Ruins of Lordaeron - and stop. Up there is the Horde''s country, and an army between you and home. The only way out is the way you came.', ''),
(19, 'Thunder Bluff', 6, '1638', 'Wind and drums. The mesas stand high over the plains, and every brave on them has been told the Alliance is coming to burn Mulgore. They will not be glad to see you.', 'Thunder Bluff has had its reckoning. The war drums are silent, and the portal keeper by the bank on the central rise can send you home whenever you are ready.'),
(21, 'Mulgore', 99, '215', 'The lift creaks down toward the plains of Mulgore - and stops. Down there are a thousand braves and nowhere to hide. The only way out is the way you came.', ''),
(20, 'Orgrimmar', 6, '1637', 'Red stone and iron spikes, smoke and drums. This is the Warchief''s city, the heart of the Horde, and every grunt in it has wanted a war with your kind for years.', 'Orgrimmar has fallen silent. The Warchief''s hold is broken, the Burning Blade is scattered, and the portal keeper by the bank in the Valley of Strength can send you home whenever you are ready.'),
(22, 'Durotar', 99, '14', 'The great gate opens onto the red land of Durotar - and an army camped across it. The only way out is the way you came.', '');

DROP TABLE IF EXISTS `dnd_encounter`;
CREATE TABLE `dnd_encounter` (
  `id` INT UNSIGNED NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `aggro_range` FLOAT NOT NULL DEFAULT 12,
  `join_range` FLOAT NOT NULL DEFAULT 30,
  `zone_id` INT UNSIGNED NOT NULL DEFAULT 0,
  `xp` INT UNSIGNED NOT NULL DEFAULT 0,
  `dialogue_node` INT UNSIGNED NOT NULL DEFAULT 0,
  `after_text` VARCHAR(255) NOT NULL DEFAULT '',
  `patience` TINYINT NOT NULL DEFAULT 0,
  `snap_node` INT UNSIGNED NOT NULL DEFAULT 0,
  `meter_label` VARCHAR(32) NOT NULL DEFAULT '',
  `sour_node` INT UNSIGNED NOT NULL DEFAULT 0,
  `minion` INT UNSIGNED NOT NULL DEFAULT 0,
  `legendary` TINYINT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `dnd_encounter` (`id`, `name`, `aggro_range`, `join_range`, `zone_id`, `xp`, `dialogue_node`, `after_text`,
  `patience`, `snap_node`, `meter_label`, `sour_node`, `minion`, `legendary`) VALUES
(1, 'Hungry Wolves', 12, 30, 1, 25, 101, 'The pups ignore you, busy with what''s left of their meal.', 3, 190, 'Restraint', 0, 0, 0),
(2, 'Rockjaw Ambush', 12, 30, 1, 30, 201, 'The plundered supply crate lies abandoned in the snow.', 0, 0, '', 0, 0, 0),
(3, 'Boar Wallow', 12, 30, 1, 20, 301, 'The boars wallow contentedly and ignore you.', 0, 0, '', 0, 0, 0),
(4, 'Timber Wolf Pack', 14, 30, 1, 30, 401, 'Only tracks in the snow are left of the wolves.', 0, 0, '', 0, 0, 0),
(5, 'Rockjaw Dig Site', 13, 30, 1, 35, 501, 'The collapsed dig site is quiet now.', 0, 0, '', 0, 0, 0),
(6, 'Frostmane Scouts', 14, 32, 1, 35, 601, 'The ritual circle is cold and empty.', 3, 690, '', 0, 0, 0),
(7, 'Claim Jumpers', 10, 30, 1, 35, 701, 'Grumbold grunts without looking up. "Still here? Go on, I''ve diggin'' to do."', 3, 790, '', 0, 0, 0),
(8, 'The Tinker''s Grudge', 10, 30, 1, 30, 801, 'Fizzik waves you off without looking up from his notes.', 3, 830, '', 831, 0, 0),
(9, 'Grik''nir''s Camp', 14, 35, 1, 60, 901, 'Grik''nir''s bone throne sits empty.', 2, 990, '', 0, 0, 0),
(10, 'Raiders at the Pass', 13, 30, 2, 35, 1001, 'The raiders'' fire is cold ashes now.', 0, 0, '', 0, 0, 0),
(11, 'Shimmer Ridge Vigil', 14, 30, 2, 45, 1101, 'The seers'' smoke has blown away on the wind.', 3, 1190, '', 0, 0, 0),
(12, 'The Grizzled Den', 14, 32, 2, 50, 1201, 'The den is quiet. Nothing moves in the dark.', 0, 0, '', 0, 0, 0),
(13, 'Old Icebeard', 14, 35, 2, 60, 1301, 'Old Icebeard''s cave is silent and empty.', 0, 0, '', 0, 1134, 0),
(14, 'Fimble''s Folk', 12, 30, 2, 40, 1401, 'The gnome waves vaguely. "Fine. Everything''s fine. Off you go."', 3, 1490, '', 0, 0, 0),
(15, 'Gol''Bolar Quarry', 14, 32, 2, 45, 1501, 'The quarry is empty but for the wind and a broken chain.', 0, 0, '', 0, 0, 0),
(16, 'Vejrek''s War Camp', 12, 35, 2, 65, 1601, 'The skull throne stands empty.', 2, 1690, '', 0, 0, 0),
(17, 'Ice Claw Den', 14, 30, 2, 30, 1701, 'The bears'' den is quiet.', 0, 0, '', 0, 0, 0),
(18, 'Snowstrider Hunt', 14, 32, 2, 35, 1801, 'Only a muddle of tracks in the snow remains.', 0, 0, '', 0, 0, 0),
(19, 'Winter Wolves', 14, 30, 2, 30, 1901, 'The elk carcass has been picked clean.', 0, 0, '', 0, 0, 0),
(20, 'Stalked', 14, 30, 2, 30, 2001, 'Nothing watches you from the rocks now.', 0, 0, '', 0, 0, 0),
(21, 'The Rampaging Boar', 15, 30, 2, 35, 2101, 'Broken fence posts and churned snow.', 0, 0, '', 0, 1191, 0),
(22, 'Trogg Trail', 13, 30, 2, 30, 2201, 'The trail is quiet.', 0, 0, '', 0, 0, 0),
(23, 'Frostmane Outriders', 12, 30, 2, 35, 2301, 'The toll-stones by the road lie scattered.', 2, 2390, '', 0, 0, 0),
(24, 'The Honey Thief', 13, 30, 2, 35, 2401, 'The torn pack lies empty in the snow.', 0, 0, '', 0, 1186, 0),
(30, 'Stonesplinter Lookouts', 14, 30, 3, 150, 0, '', 0, 0, '', 0, 0, 0),
(31, 'Candlelight', 12, 30, 3, 120, 3101, 'The candle stubs are gone, and so are the kobolds.', 0, 0, '', 0, 0, 0),
(32, 'The Mo''grosh Toll', 14, 32, 3, 150, 3201, 'Only a flattened patch of road where the ogres stood.', 2, 3290, '', 0, 0, 0),
(33, 'Chok''sul', 15, 35, 3, 200, 0, '', 0, 0, '', 0, 0, 0),
(34, 'Powder by the Dam', 13, 30, 3, 150, 3401, 'A scorch mark and an empty crate by the water.', 2, 3490, '', 0, 0, 0),
(35, 'Lord of the Highlands', 15, 32, 3, 130, 0, '', 0, 0, '', 0, 0, 0),
(36, 'The Spinner''s Nest', 14, 30, 3, 150, 0, '', 0, 0, '', 0, 0, 0),
(37, 'Lochside Crocolisks', 13, 30, 3, 100, 0, '', 0, 0, '', 0, 0, 0),
(38, 'Bears in the Pines', 14, 30, 3, 100, 0, '', 0, 0, '', 0, 0, 0),
(39, 'The Herd', 14, 30, 3, 100, 0, '', 0, 0, '', 0, 0, 0),
(40, 'Carrion Birds', 14, 30, 3, 90, 0, '', 0, 0, '', 0, 0, 0),
(41, 'Webs in the Woods', 13, 30, 3, 100, 0, '', 0, 0, '', 0, 0, 0),
(42, 'The Storm Circle', 14, 32, 3, 120, 0, '', 0, 0, '', 0, 0, 0),
(43, 'The Old King', 15, 32, 3, 140, 0, '', 0, 0, '', 0, 1186, 0),
(50, 'Bluegill Shallows', 13, 30, 5, 130, 0, '', 0, 0, '', 0, 0, 0),
(51, 'The Gobbler', 12, 30, 5, 200, 5101, 'A trail of fish bones leads off into the reeds. Nothing else is left.', 3, 5190, 'Appetite', 0, 0, 0),
(52, 'Crocolisk Wallow', 13, 30, 5, 120, 0, '', 0, 0, '', 0, 0, 0),
(53, 'The Slime Pools', 12, 30, 5, 130, 0, '', 0, 0, '', 0, 0, 0),
(54, 'Mottled Raptors', 14, 30, 5, 180, 0, '', 0, 0, '', 0, 0, 0),
(55, 'Sarltooth', 15, 32, 5, 240, 0, '', 0, 0, '', 0, 0, 0),
(56, 'Mosshide Camp', 12, 30, 5, 180, 5601, 'A gnawed boar haunch and three sets of tracks, all going different ways.', 3, 5690, '', 0, 0, 0),
(57, 'The Leech Widow', 14, 30, 5, 220, 0, '', 0, 0, '', 0, 0, 0),
(58, 'Ma''ruk''s Patrol', 13, 32, 5, 240, 5801, 'The pass stands open. Someone has kicked the Dragonmaw banner into the ditch.', 2, 5890, '', 0, 0, 0),
(59, 'The Drowned Crew', 14, 30, 5, 200, 0, '', 0, 0, '', 0, 0, 0),
(60, 'Captain Halyndor', 13, 32, 5, 300, 6001, 'The tide has smoothed the sand where they stood. A gull sits where the captain was.', 3, 6090, 'Composure', 0, 0, 0),
(61, 'Gnawbone''s Pack', 13, 32, 5, 240, 6101, 'A heap of old bones, and nobody sitting on it.', 3, 6190, '', 0, 0, 0),
(62, 'The Fen Lord', 14, 32, 5, 200, 0, '', 0, 0, '', 0, 0, 0),
(63, 'Angerfang Raiders', 14, 32, 5, 220, 0, '', 0, 0, '', 0, 0, 0),
(64, 'Chieftain Nek''rosh', 13, 35, 5, 350, 6401, 'The war table is overturned and the camp is cold.', 2, 6490, '', 0, 0, 0),
(65, 'Highland Pack', 14, 30, 5, 150, 0, '', 0, 0, '', 0, 0, 0),
(66, 'The Lost Whelps', 14, 30, 5, 200, 0, '', 0, 0, '', 0, 0, 0),
(67, 'Balgaras the Foul', 13, 32, 5, 300, 6701, 'A cracked cauldron, a black scorch on the hillside, and a smell that will take years to leave.', 2, 6790, 'Temper', 0, 0, 0),
(110, 'Crag Coyote Pack', 14, 30, 6, 150, 0, '', 0, 0, '', 0, 0, 0),
(111, 'Ridge Stalkers', 14, 30, 6, 180, 0, '', 0, 0, '', 0, 0, 0),
(112, 'Boss Tho''grun', 13, 32, 6, 300, 11201, 'Tho''grun''s rock by the road is empty. Somewhere in the hills, an ogre is still nursing his jaw.', 3, 11290, '', 0, 0, 0),
(113, 'The Dustbelcher Camp', 13, 30, 6, 200, 0, '', 0, 0, '', 0, 0, 0),
(114, 'Hammertoe''s Dig', 13, 30, 6, 250, 11401, 'The dig is quiet. Somebody has stacked the Dark Irons'' tools neatly by the shaft.', 2, 11490, '', 0, 0, 0),
(115, 'Shadowforge Tunnelers', 13, 30, 6, 180, 0, '', 0, 0, '', 0, 0, 0),
(116, 'Murdaloc''s Warren', 13, 30, 6, 250, 11601, 'The warren is empty. Whatever the troggs were waiting for, they''ve gone to find it.', 3, 11690, '', 0, 0, 0),
(117, 'Walking Stones', 12, 28, 6, 160, 0, '', 0, 0, '', 0, 0, 0),
(118, 'The Guardian of Lethlor', 14, 32, 6, 300, 11801, 'The ravine is quiet, but you feel something watching you from the rocks. It lets you pass.', 2, 11890, '', 0, 0, 0),
(119, 'Scalding Whelps', 14, 30, 6, 180, 0, '', 0, 0, '', 0, 0, 0),
(120, 'The Runaway Golem', 12, 30, 6, 220, 12001, 'Lotwil''s golem has gone back to its camp. You can hear it clanking from here.', 3, 12090, 'Strain', 0, 0, 0),
(121, 'Circling Buzzards', 15, 30, 6, 130, 0, '', 0, 0, '', 0, 0, 0),
(122, 'Angor Fortress', 13, 30, 6, 280, 12201, 'Angor''s gate stands open, and the Shadowforge banner is down.', 2, 12290, '', 0, 0, 0),
(123, 'The Rumbler', 13, 32, 6, 250, 0, '', 0, 0, '', 0, 0, 0),
(124, 'Anathemus', 14, 32, 6, 300, 12401, 'A long low hill lies here, with a face you can make out if you squint. It is asleep.', 3, 12490, 'Waking', 0, 2735, 0),
(125, 'Zaricotl''s Roost', 15, 30, 6, 150, 0, '', 0, 0, '', 0, 0, 0),
(126, 'The Stonevault Seers', 13, 30, 6, 180, 0, '', 0, 0, '', 0, 0, 0),
(127, 'Broken Tooth', 14, 30, 6, 140, 0, '', 0, 0, '', 0, 0, 0),
(130, 'Glassweb Spiders', 13, 30, 10, 350, 0, '', 0, 0, '', 0, 0, 0),
(131, 'Searing Lava Spiders', 13, 30, 10, 350, 0, '', 0, 0, '', 0, 0, 0),
(132, 'Slave Master Blackheart', 13, 32, 10, 550, 13201, 'The rim of the Cauldron is quiet. The slaves'' chains lie in a heap where Blackheart left them.', 2, 13290, '', 0, 0, 0),
(133, 'Dark Iron Slavers', 13, 30, 10, 400, 0, '', 0, 0, '', 0, 0, 0),
(134, 'The Twilight Highlord', 13, 32, 10, 600, 13401, 'The pulpit-stone on Firewatch Ridge is bare. The wind has scattered the last of the tracts.', 3, 13490, '', 0, 0, 0),
(135, 'Magma Elementals', 12, 28, 10, 400, 0, '', 0, 0, '', 0, 0, 0),
(136, 'The Geologists'' Camp', 13, 30, 10, 450, 13601, 'The geologists'' camp is struck. Their survey stakes still stand in neat lines across the rock.', 3, 13690, '', 0, 0, 0),
(137, 'Heavy War Golems', 12, 28, 10, 450, 0, '', 0, 0, '', 0, 0, 0),
(138, 'Obsidion', 12, 30, 10, 500, 13801, 'The obsidian golem stands where it stood before, very still, keeping its watch.', 3, 13890, 'Alarm', 0, 0, 0),
(139, 'Incendosaurs', 13, 30, 10, 350, 0, '', 0, 0, '', 0, 0, 0),
(140, 'The Lone Idolater', 12, 30, 10, 350, 14001, 'The idolater''s little shrine is kicked over. He won''t be back.', 3, 14090, 'Panic', 0, 0, 0),
(141, 'Rekk''tilac', 13, 32, 10, 450, 0, '', 0, 0, '', 0, 0, 0),
(142, 'The Steamsmith''s Forge', 13, 30, 10, 450, 14201, 'The forge is cold. The steamsmith has gone - and taken his golem, and his ego, with him.', 3, 14290, '', 0, 0, 0),
(143, 'Dark Iron Lookouts', 15, 32, 10, 350, 0, '', 0, 0, '', 0, 0, 0),
(144, 'Smoldar', 13, 32, 10, 500, 14401, 'The chain-stakes stand empty, glowing faintly. Whatever they held is gone.', 2, 14490, 'Heat', 0, 0, 0),
(145, 'Inferno Elementals', 12, 28, 10, 350, 0, '', 0, 0, '', 0, 0, 0),
(146, 'Twilight Geomancers', 13, 30, 10, 350, 0, '', 0, 0, '', 0, 0, 0),
(147, 'Tempered War Golems', 12, 28, 10, 300, 0, '', 0, 0, '', 0, 0, 0),
(150, 'The High Seat', 12, 30, 4, 250, 15001, 'The High Seat is quiet. Whoever sits in it now, they''ve had their word with you.', 3, 15090, '', 0, 0, 0),
(151, 'The Great Forge', 12, 28, 4, 150, 15101, 'The Great Forge roars on, and nobody here is holding a whip.', 2, 15190, '', 0, 0, 0),
(152, 'Regency Patrol', 13, 28, 4, 120, 0, '', 0, 0, '', 0, 0, 0),
(153, 'The Deeprun Spies', 12, 28, 4, 150, 15301, 'The tram tunnel is empty. A few chalk marks on the wall, rubbed half out.', 2, 15390, '', 0, 0, 0),
(154, 'The Forlorn Cavern', 12, 28, 4, 150, 15401, 'The Forlorn Cavern''s pulpit-crate is overturned. The sermon is over.', 3, 15490, '', 0, 0, 0),
(155, 'Tinker Town Refugees', 12, 28, 4, 100, 15501, 'The refugees'' corner is tidier than it was. Somebody has swept.', 3, 15590, 'Desperation', 0, 0, 0),
(156, 'The League''s Watcher', 12, 30, 4, 120, 15601, 'The earthen guardian stands in its alcove like a statue, its eyes dim.', 3, 15690, 'Alarm', 0, 0, 0),
(157, 'The Vault Robbers', 13, 28, 4, 120, 0, '', 0, 0, '', 0, 0, 0),
(158, 'The Loyalist Cell', 12, 28, 4, 130, 15801, 'The loyalists'' corner of the Military Ward is empty. They''ve gone wherever loyalists go.', 2, 15890, 'Suspicion', 0, 0, 0),
(159, 'The Hall of Mysteries', 13, 28, 4, 110, 0, '', 0, 0, '', 0, 0, 0),
(160, 'The Anvilrage Checkpoint', 13, 28, 4, 100, 0, '', 0, 0, '', 0, 0, 0),
(161, 'The Stonefire Brawl', 12, 28, 4, 100, 16101, 'The Stonefire Tavern has been put back together. Mostly.', 3, 16190, '', 0, 0, 0),
(162, 'The Forger in the Vault', 12, 28, 4, 100, 16201, 'The vault''s ledger-desk is cleared. Someone has put the real deeds back.', 2, 16290, '', 0, 0, 0),
(163, 'The Ambassador''s Escort', 13, 28, 4, 100, 0, '', 0, 0, '', 0, 0, 0),
(170, 'The Lord Protector', 12, 30, 12, 450, 17001, 'The throne room is quiet. Whatever sits on the throne now, it has had its word with you.', 3, 17090, '', 0, 0, 0),
(171, 'The War Room', 13, 28, 12, 300, 0, '', 0, 0, '', 0, 0, 0),
(172, 'Lescovar''s Garden', 12, 30, 12, 300, 17201, 'Lescovar''s garden is empty. The hedges have been cut back, hard.', 2, 17290, '', 0, 0, 0),
(173, 'The Stonemasons'' Picket', 12, 28, 12, 280, 17301, 'The picket''s placards are stacked neatly by the architect''s door.', 3, 17390, 'Anger', 0, 0, 0),
(174, 'The Stockade Breakout', 13, 28, 12, 300, 0, '', 0, 0, '', 0, 0, 0),
(175, 'Bazil''s Canal Crew', 12, 28, 12, 260, 17501, 'This stretch of canal is quiet. A crate of Defias red bandanas floats by, empty.', 2, 17590, '', 0, 0, 0),
(176, 'The Slaughtered Lamb', 12, 28, 12, 280, 17601, 'The Lamb''s back room smells of chalk and smoke. The circle has been scrubbed away.', 2, 17690, '', 0, 0, 0),
(177, 'SI:7''s Offer', 12, 28, 12, 200, 17701, 'The SI:7 man is gone. Nobody in Old Town saw him leave. Nobody ever does.', 3, 17790, 'Doubt', 0, 0, 0),
(178, 'The Ironforge Refugees', 12, 28, 12, 200, 17801, 'The mountaineers'' corner of the Dwarven District is tidy and empty.', 3, 17890, 'Nerves', 0, 0, 0),
(179, 'Something in the Canals', 13, 28, 12, 300, 0, '', 0, 0, '', 0, 0, 0),
(180, 'The Dark Iron Envoy', 12, 28, 12, 270, 18001, 'The envoy''s bench outside the House of Nobles is empty.', 2, 18090, '', 0, 0, 0),
(181, 'The Harbour Wreckers', 13, 28, 12, 220, 0, '', 0, 0, '', 0, 0, 0),
(182, 'The Rift in the Mage Quarter', 13, 28, 12, 220, 0, '', 0, 0, '', 0, 0, 0),
(183, 'The Pig and Whistle', 12, 28, 12, 220, 18301, 'The Pig and Whistle is quiet. Somebody has paid for the broken chairs.', 3, 18390, 'Temper', 0, 0, 0),
(190, 'Fargodeep''s Mouth', 13, 28, 13, 400, 0, '', 0, 0, '', 0, 0, 0),
(191, 'Narg the Taskmaster', 12, 28, 13, 450, 19101, 'Fargodeep''s foreman''s ledge is empty. A stub of candle burns there, on its own.', 2, 19190, 'Candle', 0, 0, 0),
(192, 'Hogger', 14, 30, 13, 800, 0, '', 0, 0, '', 0, 0, 0),
(193, 'Gruff Swiftbite''s Pack', 12, 28, 13, 450, 19301, 'The gnoll camp at the forest''s edge is cold. Paw-prints lead away west.', 3, 19390, '', 0, 0, 0),
(194, 'Fedfennel''s Raiders', 13, 28, 13, 450, 0, '', 0, 0, '', 0, 0, 0),
(195, 'The Stone Cairn Murlocs', 13, 28, 13, 450, 0, '', 0, 0, '', 0, 0, 0),
(196, 'The Crystal Lake Tidecaller', 12, 28, 13, 450, 19601, 'The stream mouth is quiet. A ring of pebbles on the bank, carefully arranged.', 3, 19690, 'Wariness', 0, 0, 0),
(197, 'Morgaine the Sly', 12, 28, 13, 450, 19701, 'The Defias lookout post is empty. Somebody left in a hurry, and tidily.', 2, 19790, '', 0, 0, 0),
(198, 'Thuros''s Ambush', 13, 28, 13, 450, 0, '', 0, 0, '', 0, 0, 0),
(199, 'The Rogue Wizards', 12, 28, 13, 450, 19901, 'The rogue wizards'' camp is struck. A scorch mark where their circle was.', 3, 19990, '', 0, 0, 0),
(200, 'Mother Fang', 13, 28, 13, 600, 0, '', 0, 0, '', 0, 0, 0),
(201, 'The Jasperlode Geomancer', 13, 28, 13, 400, 0, '', 0, 0, '', 0, 0, 0),
(202, 'Princess', 13, 28, 13, 450, 0, '', 0, 0, '', 0, 0, 0),
(203, 'The Prowler Pack', 14, 28, 13, 400, 0, '', 0, 0, '', 0, 0, 0),
(204, 'Garrick Padfoot', 12, 28, 13, 450, 20401, 'The vineyard is quiet. The vines have been tied up properly, for once.', 2, 20490, '', 0, 0, 0),
(205, 'The Bears of Brackwell', 13, 28, 13, 400, 0, '', 0, 0, '', 0, 0, 0),
(70, 'Strider Flock', 14, 30, 7, 300, 0, '', 0, 0, '', 0, 0, 0),
(71, 'The Creeper Nest', 13, 30, 7, 350, 0, '', 0, 0, '', 0, 0, 0),
(72, 'Thrasher Pack', 15, 32, 7, 400, 0, '', 0, 0, '', 0, 0, 0),
(73, 'Mesa Buzzards', 15, 30, 7, 250, 0, '', 0, 0, '', 0, 0, 0),
(74, 'Witherbark Headhunters', 14, 32, 7, 400, 0, '', 0, 0, '', 0, 0, 0),
(75, 'The Witch Doctor''s Circle', 13, 32, 7, 500, 7501, 'A ring of scorched stones and a burned-out fire. Nobody is chanting here now.', 2, 7590, '', 0, 0, 0),
(76, 'Boulderfist Brutes', 14, 32, 7, 400, 0, '', 0, 0, '', 0, 0, 0),
(77, 'The Boulderfist Outpost', 13, 32, 7, 450, 7701, 'A trampled ring of dirt where the ogres played. The kobold is long gone.', 3, 7790, '', 0, 0, 0),
(78, 'Or''Kalar', 13, 35, 7, 650, 7801, 'Boulderfist Hall is quiet. The great chair at the end of it is empty.', 3, 7890, 'Patience', 0, 0, 0),
(79, 'Highwaymen at Northfold', 13, 32, 7, 450, 7901, 'Wheel ruts, and a farmer''s hat in the ditch, and nothing else on the road.', 2, 7990, '', 0, 0, 0),
(80, 'Looters of Stromgarde', 14, 32, 7, 450, 0, '', 0, 0, '', 0, 0, 0),
(81, 'The Syndicate Magus', 13, 32, 7, 500, 8101, 'The vault door stands as the Trollbanes left it, the ward bright and whole.', 2, 8190, '', 0, 0, 0),
(82, 'The Drywhisker Dig', 12, 30, 7, 400, 8201, 'The tunnel mouth is quiet. Somewhere far down it, something hums to itself.', 3, 8290, 'Nerve', 0, 0, 0),
(83, 'The Rumbling Exiles', 13, 30, 7, 400, 0, '', 0, 0, '', 0, 0, 0),
(84, 'The Burning Exiles', 13, 30, 7, 400, 0, '', 0, 0, '', 0, 0, 0),
(85, 'The Cresting Exile', 13, 30, 7, 400, 8501, 'The circle is cracked and dry. Whatever it held has gone back to the sea.', 3, 8590, 'Strain', 0, 0, 0),
(86, 'The Thundering Exiles', 13, 30, 7, 400, 0, '', 0, 0, '', 0, 0, 0),
(87, 'Fleshstalker Ridge', 15, 32, 7, 400, 0, '', 0, 0, '', 0, 0, 0),
(206, 'Bethor''s Balcony', 12, 28, 17, 0, 20601, 'Bethor''s balcony is empty. Frost has crept over the rail where he used to lean.', 3, 20690, 'Patience', 0, 17906, 0),
(207, 'The Summoning Circle', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 0, 0),
(208, 'The Deathstalkers'' Hall', 12, 28, 17, 0, 20801, 'The Deathstalkers'' hall is dark and empty. The practice dummies have all had their throats cut.', 2, 20890, 'Suspicion', 0, 0, 0),
(209, 'Ravenholdt''s Man', 12, 28, 17, 0, 20901, 'Andron Gant''s corner is empty. A single black feather lies on the step.', 3, 20990, 'Interest', 0, 13155, 0),
(210, 'The Bone Workshop', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 17895, 0),
(211, 'The Abomination Pens', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 0, 0),
(212, 'The Dreadlord''s Offer', 12, 28, 17, 0, 21201, 'The dreadlord''s chamber is empty. The air still smells faintly of brimstone.', 2, 21290, 'Amusement', 0, 17906, 1),
(213, 'The Dark Rangers'' Range', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 0, 0),
(214, 'The Census', 12, 28, 17, 0, 21401, 'The census desk is empty. The ledger lies open at a blank page.', 3, 21490, 'Patience', 0, 13155, 0),
(215, 'The Bat Roost', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 0, 0),
(216, 'The Canal Slimes', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 0, 0),
(217, 'The Mourners'' Corner', 12, 28, 17, 0, 21701, 'The mourners'' corner is quiet. Someone has left three candles burning.', 3, 21790, 'Trust', 0, 0, 0),
(218, 'The New Plague', 12, 28, 17, 0, 21801, 'The vats are cold. Whatever was brewing here will never be finished.', 2, 21890, 'Patience', 0, 0, 0),
(219, 'The Cages', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 0, 0),
(220, 'The Dreadguard Gate', 13, 28, 17, 0, 0, '', 0, 0, '', 0, 0, 0),
(221, 'Sharlindra''s Watch', 12, 28, 17, 0, 22101, 'Nobody sings here any more. The silence is almost worse.', 2, 22190, 'Calm', 0, 17905, 0),
(222, 'The Banshee Queen', 14, 32, 17, 0, 0, '', 0, 0, '', 0, 13839, 1),
(223, 'The Bluffwatchers'' Post', 13, 28, 19, 0, 0, '', 0, 0, '', 0, 0, 0),
(224, 'Pala''s Hearth', 12, 28, 19, 0, 22401, 'Pala''s fire burns low in an empty lodge. A kettle sits by it, still warm.', 3, 22490, 'Welcome', 0, 3084, 0),
(225, 'The Stonehoof Forge', 12, 28, 19, 0, 22501, 'The Stonehoof forge is cold. The half-finished spearheads have been thrown in the quench-tank.', 2, 22590, 'Temper', 0, 3084, 0),
(226, 'The Cloud Serpent Roost', 13, 28, 19, 0, 0, '', 0, 0, '', 0, 0, 0),
(227, 'Hesuwa''s Challenge', 12, 28, 19, 0, 22701, 'Hesuwa''s hunting ground is empty. Her trophies still hang on the rise''s poles.', 3, 22790, 'Interest', 0, 4117, 0),
(228, 'The Training Grounds', 13, 28, 19, 0, 0, '', 0, 0, '', 0, 0, 0),
(229, 'The Pools of Vision', 12, 28, 19, 0, 22901, 'The Pools of Vision are still. Nobody hides in the shadows by the water now.', 2, 22990, 'Nerves', 0, 3084, 0),
(230, 'The Arch Druid''s Lift', 12, 28, 19, 0, 23001, 'The Arch Druid''s place by the lift is empty. A few leaves skitter across the boards.', 3, 23090, 'Patience', 0, 3084, 0),
(231, 'The Grimtotem Plotters', 13, 28, 19, 0, 0, '', 0, 0, '', 0, 0, 0),
(232, 'The Elder Crone', 12, 28, 19, 0, 23201, 'The crone''s lodge is empty, the fire scattered. The smell of her herbs lingers.', 2, 23290, 'Patience', 0, 11912, 0),
(233, 'The Wind Rider Roost', 13, 28, 19, 0, 0, '', 0, 0, '', 0, 0, 0),
(234, 'The Chieftain''s Son', 12, 28, 19, 0, 23401, 'The war drums stand silent and covered. Nobody is beating them now.', 2, 23490, 'Temper', 0, 3083, 0),
(235, 'The Honor Guard''s Muster', 13, 28, 19, 0, 0, '', 0, 0, '', 0, 0, 0),
(236, 'The High Chieftain', 14, 32, 19, 0, 0, '', 0, 0, '', 0, 3083, 1),
(237, 'The Gate Watch', 13, 28, 20, 0, 0, '', 0, 0, '', 0, 0, 0),
(238, 'The Overlord''s Hall', 12, 28, 20, 0, 23801, 'The overlord''s hall is empty. His banners have been taken down.', 3, 23890, 'Temper', 0, 31416, 0),
(239, 'The Orphanage', 12, 28, 20, 0, 23901, 'The orphanage door is shut. Behind it, children are singing.', 3, 23990, 'Trust', 0, 31416, 0),
(240, 'The Reagent Seller', 12, 28, 20, 0, 24001, 'The reagent stall in the Cleft is bare. Somebody has scrubbed a burnt sigil off the wall.', 2, 24090, 'Suspicion', 0, 3199, 0),
(241, 'The Burning Blade Coven', 13, 28, 20, 0, 0, '', 0, 0, '', 0, 0, 0),
(242, 'The Drag''s Thugs', 13, 28, 20, 0, 0, '', 0, 0, '', 0, 0, 0),
(243, 'The Darkspear Chieftain', 12, 28, 20, 0, 24301, 'Vol''jin''s place in the Valley of Spirits is empty. A voodoo charm swings from a post.', 2, 24390, 'Patience', 0, 33299, 0),
(244, 'The Raptor Pens', 13, 28, 20, 0, 0, '', 0, 0, '', 0, 0, 0),
(245, 'The Wind Rider Tower', 13, 28, 20, 0, 0, '', 0, 0, '', 0, 0, 0),
(246, 'The Old Warrior', 12, 28, 20, 0, 24601, 'The old warrior''s training dummy stands alone, notched by a thousand blows.', 3, 24690, 'Patience', 0, 14304, 0),
(247, 'The Valley of Honor', 13, 28, 20, 0, 0, '', 0, 0, '', 0, 0, 0),
(248, 'Hellscream''s Challenge', 12, 28, 20, 0, 24801, 'Hellscream''s corner of the valley is empty. The ground is scarred where he paced.', 2, 24890, 'Temper', 0, 14304, 1),
(249, 'The Far Seer', 12, 28, 20, 0, 24901, 'The Far Seer has gone. The wind still smells of rain where he stood.', 3, 24990, 'Patience', 0, 31416, 0),
