-- townsfolk roles (tools/townsfolk.py): who says what, and the gift for winning them round
DROP TABLE IF EXISTS `dnd_townsfolk_role`;
CREATE TABLE `dnd_townsfolk_role` (
  `ord` INT UNSIGNED NOT NULL,
  `role` VARCHAR(32) NOT NULL,
  `keywords` VARCHAR(255) NOT NULL DEFAULT '',
  `nodes` VARCHAR(64) NOT NULL DEFAULT '',
  `money` INT UNSIGNED NOT NULL DEFAULT 0,
  `item` INT UNSIGNED NOT NULL DEFAULT 0,
  `gift` VARCHAR(255) NOT NULL DEFAULT '',
  `after_text` VARCHAR(255) NOT NULL DEFAULT '',
  `games` VARCHAR(32) NOT NULL DEFAULT '',
  `zone` INT UNSIGNED NOT NULL DEFAULT 0,
  PRIMARY KEY (`ord`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT INTO `dnd_townsfolk_role` (`ord`, `role`, `keywords`, `nodes`, `money`, `item`, `gift`, `after_text`, `games`, `zone`) VALUES
(0, 'guard:327', 'sergeant hilde brassjaw', '9000', 0, 118, 'A healing draught from the sergeant\'s own belt.', '"Back again? Good. Means you\'re still breathing."', '', 0),
(1, 'guard:329', 'old tam kettlebeard', '9020', 600, 0, 'A few coins - Tam\'s winnings from a card game he swears he didn\'t cheat at.', '"Ah, it\'s you. Come to hear the rest of the story? No? Pity."', '', 0),
(2, 'guard:353', 'brenna stoutvale', '9040', 0, 2139, 'Brenna\'s spare belt knife - a plain, well-kept dagger.', '"Road\'s quiet today. Let\'s keep it that way."', '', 0),
(3, 'guard:410', 'corporal durn ashgrip', '9060', 900, 0, 'Durn\'s share of a toll the Watch hasn\'t been collecting.', '"Hearth\'s still lit. I checked."', '', 0),
(4, 'guard:291', 'gorrim flintwhistle', '9080', 0, 118, 'A healing draught, from Gorrim\'s \'emergency\' pouch.', '"Still alive! Told you the road was the safe part."', '', 0),
(5, 'guard:229', 'mira coldforge', '9100', 1200, 0, 'Mira\'s bounty money for a trogg she says you basically caught.', '"Any more trogg sign on your travels? No? Good."', '', 0),
(6, 'guard:212', 'captain bolvar thaneshield', '9120', 2000, 0, 'Watch pay, for an irregular the captain has decided to recognise.', '"Irregular. Good to see you."', '', 0),
(7, 'guard:4133', 'ysolde granitebrow', '9140', 0, 2504, 'Ysolde\'s old hunting bow. She has a better one.', '"Keep your bowstring dry."', '', 0),
(8, 'guard:4479', 'brannoc ironsong', '9160', 0, 858, 'A potion of greater healing - Brannoc\'s last.', '"The road east is still shut, friend. For now."', '', 0),
(9, 'guard:4067', 'kessa hammerfall', '9180', 0, 2134, 'A handaxe from the depot stores, no questions asked.', '"Depot\'s still standing. Thanks for asking."', '', 0),
(10, 'guard:150', 'dagran stonefist', '9200', 700, 0, 'Dagran\'s wager - a bet he lost fair and square.', '"Arm\'s still sore. Don\'t gloat."', '', 0),
(11, 'guard:2283', 'pell brightanvil', '9220', 500, 118, 'A healing draught and a few coins from Pell\'s patrol pay.', '"Same loop, same snow. Wouldn\'t have it any other way. Would have it SLIGHTLY other ways."', '', 0),
(12, 'guard:161007', 'hrodar the watcher', '9240', 1500, 0, 'A bag of coins Hrodar says the mountain gave him.', '"The mountain remembers you."', '', 0),
(13, 'guard:145', 'warden torvald grimbrand', '9260', 0, 2362, 'A Watch shield, slightly dented, entirely serviceable.', '"Mind the Dark Irons inside. They mind you."', '', 0),
(14, 'guard:140', 'warden brodd ironhelm', '9280', 0, 118, 'A healing draught from the gatehouse stores.', '"Still standing. For now."', '', 0),
(15, 'guard:4471', 'aldrena frostbeard', '9300', 0, 118, 'A healing draught, with the camp\'s thanks.', '"Camp\'s holding. You helped."', '', 0),
(16, 'guard:4159', 'olgar deepbarrel', '9320', 800, 0, 'Olgar\'s \'tax\' on passing travellers, returned with interest.', '"Road\'s yours, friend. No toll for you."', '', 0),
(17, 'guard:6336', 'gilda stormhammer', '9340', 0, 15807, 'A light crossbow from the post\'s armoury.', '"Loch Modan waits beyond the hills. Earn it."', '', 0),
(18, 'guard:3028', 'borin icewater', '9360', 1000, 0, 'Coins from the bottom of the lake. Borin\'s fishing has its rewards.', '"Fish are biting! ...No they\'re not."', '', 0),
(19, 'guard:6358', 'ragna steelbrow', '9380', 0, 2130, 'A mace from Ragna\'s own kit.', '"Hold the line, friend."', '', 0),
(20, 'harbor_healer', 'physician,chirurgeon,healer,priest,alchemy,apothecary', '9400,9401', 0, 118, 'A healing draught from the apothecary\'s shelf.', '"Keep your feet dry and that draught handy."', '', 11),
(21, 'harbor_inn', 'innkeeper,tavern,barmaid,potboy,cook', '9420,9421', 300, 4540, 'Bread for the road and a few coins from the till.', '"Fire\'s lit and the stew\'s fish. It\'s always fish."', 'dice,cards', 11),
(22, 'harbor_sailor', 'sailor,first mate,captain,crewman,dock,fisher,harbor,quartermaster,navigator', '9440,9441', 600, 0, 'A sailor\'s tip, and a coin for luck.', '"Fair winds to you."', '', 11),
(23, 'harbor_guard', 'sentry,guard,watch,mountaineer,rifleman', '9460,9461', 0, 118, 'A healing draught from the watch\'s stores.', '"Stay out of the hills after dark."', '', 11),
(24, 'harbor_merchant', 'provisioner,tanner,peddler,supplies,merchant,goods,trader,clothier,baker,trade', '9480,9481', 500, 0, 'A few coins, from the trader\'s own purse.', '"Come back when the ships do."', '', 11),
(25, 'harbor_folk', '*', '9500,9501', 500, 0, 'A few coins, given with thanks.', '"Mind the bog."', '', 11),
(26, 'refuge_guard', 'defender,captain,commander,sentry,guard,marshal,sergeant,elite', '9520,9521', 0, 118, 'A healing draught from the camp\'s stores.', '"Keep your back to the wall out there."', '', 45),
(27, 'refuge_merchant', 'supplies,goods,butcher,macecrafter,tradesman,merchant,trader,alchemy,leatherworking', '9540,9541', 500, 0, 'A few coins, from the trader\'s own purse.', '"Come back alive - I want your custom."', '', 45),
(28, 'refuge_folk', '*', '9560,9561', 500, 0, 'A few coins, given with thanks.', '"Light keep you, out there."', '', 45),
(29, 'thorium_guard', 'lookout,captain,sentry,guard', '9580,9581', 0, 118, 'A healing draught from the Brotherhood\'s stores.', '"Keep your head below the ridgeline."', '', 51),
(30, 'thorium_smith', 'smith,heavyhands,sootsmoker,taskmaster,overseer,merchant', '9600,9601', 500, 0, 'A few coins, and a smith\'s nod.', '"Mind the slag on the way out."', '', 51),
(31, 'thorium_folk', '*', '9620,9621', 500, 0, 'A few coins, given gruffly.', '"Watch the Cauldron."', '', 51),
(32, 'if_guard', 'gate warden,guard,warden', '9640,9641', 0, 118, 'A healing draught from the guardhouse, passed over quietly.', '"For the king. The real one."', '', 1537),
(33, 'if_inn', 'innkeeper,barmaid,bartender,tavern', '9660,9661', 300, 4540, 'A meal on the house and a few coins from the till.', '"Keep your head down and your mug full."', 'dice,cards', 1537),
(34, 'if_merchant', 'merchant,goods,banker,dealer,armor,weapon,gun', '9680,9681', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Come back while there\'s still a market."', '', 1537),
(35, 'if_court', 'explorer,curator,historian,senator,librarian,league', '9700,9701', 600, 0, 'A few coins, and a scholar\'s thanks.', '"History is watching us. Do try to behave."', '', 1537),
(36, 'if_gnome', 'tinker,mechanic,gnome,king of gnomes,citizen,mekkatorque,klockmort', '9720,9721', 400, 118, 'A few coins and a draught from the refugees\' little store.', '"Mind the gears!"', '', 1537),
(37, 'if_folk', '*', '9740,9741', 400, 0, 'A few coins, given quietly.', '"Keep your head down."', '', 1537),
(38, 'sw_guard', 'guard,officer,major,watch', '9760,9761', 0, 118, 'A healing draught from the guardhouse, slipped across.', '"Light keep you. Somebody has to."', '', 1519),
(39, 'sw_inn', 'innkeeper,barmaid,bartender,tavern,barkeep', '9780,9781', 300, 4540, 'A meal on the house and a few coins from the till.', '"Mind how you go - and mind who\'s listening."', 'dice,cards', 1519),
(40, 'sw_merchant', 'merchant,goods,banker,supplies,vendor,dealer,gun,bow,armor,cheese,florist,wine,clothier,cobbler', '9800,9801', 500, 0, 'A few coins, from the merchant\'s own purse.', '"Come back while there\'s still a market."', '', 1519),
(41, 'sw_court', 'bishop,brother,nurse,count,lord,librarian,architect,archmage,sorcerer,priest,acolyte', '9820,9821', 600, 0, 'A few coins, and a scholar\'s - or a priest\'s - thanks.', '"The Light watches, even here. Especially here."', '', 1519),
(42, 'sw_dwarf', 'longbeard,elmore,brohann,thistlenettle,league,deepforge,axehand,flintcrag', '9840,9841', 400, 118, 'A few coins and a draught from the dwarves\' own store.', '"Mind yourself, lad - or lass. Mind yourself."', '', 1519),
(43, 'sw_folk', '*', '9860,9861', 400, 0, 'A few coins, given quietly.', '"Keep your head down."', '', 1519),
(44, 'el_inn', 'innkeeper,barkeep,bartender,cook,butcher', '9880,9881', 300, 4540, 'A meal on the house and a few coins from the till.', '"Mind the roads. Mind the Defias. Mind your purse."', 'dice,cards', 12),
(45, 'el_merchant', 'merchant,supplies,weaponsmith,armorer,bowyer,physician,lumberjack,breeder,trade', '9900,9901', 500, 0, 'A few coins, from the trader\'s own purse.', '"Safe roads, if there are any."', '', 12),
(46, 'el_guard', 'guard,marshal,deputy,sergeant,quartermaster,officer', '9920,9921', 0, 118, 'A healing draught from the garrison\'s chest.', '"Stay on the road. And stay alive."', '', 12),
(47, 'el_abbey', 'brother,priestess,librarian,paxton,neals', '9940,9941', 600, 0, 'A few coins and the Abbey\'s blessing.', '"The Light go with you on the road."', '', 12),
(48, 'el_folk', '*', '9960,9961', 400, 0, 'A few coins, given quietly.', '"Mind the roads."', '', 12),
(49, 'healer', 'physician,chirurgeon,healer,priest', '9980,9981', 0, 118, 'A healing draught from the chirurgeon\'s own shelf.', '"Mind you keep that draught for when it counts."', '', 0),
(50, 'inn', 'innkeeper,tavern,barmaid,potboy', '10000,10001', 300, 4540, 'Bread for the road and a few coins from the till.', '"Room\'s warm and the stew\'s hot, if you want either."', 'dice,cards', 0),
(51, 'noble', 'senator,captain,elder,depot master,magistrate,chief engineer', '10020,10021', 1500, 0, 'A purse, pressed on you with official thanks.', '"Carry on. And keep your eyes open out there."', '', 0),
(52, 'guard', 'mountaineer,guard,rifleman,spotter,watch,warden,lookout,sentry', '10040,10041', 0, 118, 'A healing draught from the Watch\'s stores.', '"Stay on the roads where you can, and keep your back to the rocks."', '', 0),
(53, 'brewer', 'brew,ale & wine,vintner,victualler,food & drink,cellar', '10060,10061', 800, 0, 'A brewer\'s thanks, in coin.', '"Next batch\'ll be better. They always are."', 'drink', 0),
(54, 'smith', 'smith,armorer,forge,gunsmith,bowyer,macecrafter', '10080,10081', 1000, 0, 'Coin from the forge, for honest work.', '"Blade\'s only as good as the arm behind it. Look after yours."', '', 0),
(55, 'rancher', 'ram,amberstill', '10100,10101', 800, 0, 'A rancher\'s thanks, and a few coins.', '"The rams like you. That\'s more than they say for most."', '', 0),
(56, 'miner', 'miner,prospector,explorer,foreman,league', '10120,10121', 1000, 0, 'A miner\'s coin for a sharp eye.', '"If you ever want honest work, there\'s always a pick going spare."', '', 0),
(57, 'tinker', 'tinker,mechano,clockwork,engineer,sprocket,evacuee,leper,f875,f64', '10140,10141', 1000, 0, 'A gnome\'s grateful coins.', '"If it whistles, don\'t touch it. If it doesn\'t whistle, definitely don\'t touch it."', '', 0),
(58, 'merchant', 'provisioner,tanner,peddler,angler,supplies,merchant,goods,trader,clothier,baker', '10160,10161', 700, 0, 'A merchant\'s coins - and the start of a beautiful friendship.', '"Come back when the roads are open. I\'ll have better stock by then. Probably."', '', 0),
(59, 'folk', '*', '10180,10181', 500, 0, 'A few coins, given with thanks.', '"Mind how you go."', '', 0);

